insert into public.parts(id,section_id,name,display_order,metadata) values('7404498b-69de-518e-aeec-f2bb9a98409c','bee41358-7368-5bbb-bb76-e42afe3c1c44','Problem-Solving and Data Analysis',12,'{"sat_official_domain":"problem_solving_data_analysis","content_revision":"original-2026-10-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('32c05947-34a7-8c0c-c9d5-b064708138a0','7404498b-69de-518e-aeec-f2bb9a98409c','question_single_choice','{"prompt":"A pancake recipe uses $3$ cups of flour for every $2$ cups of milk. If a cook uses $12$ cups of flour and keeps the same ratio, how many cups of milk are needed?","options":[{"id":"A","label":"$6$"},{"id":"B","label":"$8$"},{"id":"C","label":"$11$"},{"id":"D","label":"$18$"}]}'::jsonb,1,'{"section_type":"math","sat_domain":"problem_solving_data_analysis","sat_official_domain":"problem_solving_data_analysis","sat_skill":"ratios_rates_proportions_units","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"psda-ratio-001","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('32c05947-34a7-8c0c-c9d5-b064708138a0','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"The flour is multiplied by $\\frac{12}{3} = 4$, so the milk must also be multiplied by 4: $2 \\times 4 = 8$ cups. Choice B is correct. Choice A is incorrect. This divides the flour by the milk amount from the ratio, which does not keep the ratio constant. Choice C is incorrect. This adds and subtracts the same amounts instead of scaling both quantities by the same factor. Choice D is incorrect. This uses the ratio upside down, multiplying 12 by $\\frac{3}{2}$ instead of $\\frac{2}{3}$."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('19739beb-cfba-da35-c67c-8ecc4002eb37','7404498b-69de-518e-aeec-f2bb9a98409c','question_spr','{"prompt":"A car travels $168$ miles in $3$ hours at a constant speed. At this speed, how many miles does the car travel in $5$ hours?"}'::jsonb,2,'{"section_type":"math","sat_domain":"problem_solving_data_analysis","sat_official_domain":"problem_solving_data_analysis","sat_skill":"ratios_rates_proportions_units","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"psda-ratio-002","answer_format":"spr"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('19739beb-cfba-da35-c67c-8ecc4002eb37','{"accepted":["280"]}'::jsonb,'{"feedback":{"explanation":"The speed is $\\frac{168}{3} = 56$ miles per hour, so in 5 hours the car travels $56 \\times 5 = 280$ miles."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('4caadfcb-db9c-182c-e300-66c226694325','7404498b-69de-518e-aeec-f2bb9a98409c','question_single_choice','{"prompt":"There are $12$ inches in $1$ foot. A wooden board is $7.5$ feet long. What is the length of the board, in inches?","options":[{"id":"A","label":"$0.625$"},{"id":"B","label":"$19.5$"},{"id":"C","label":"$84$"},{"id":"D","label":"$90$"}]}'::jsonb,3,'{"section_type":"math","sat_domain":"problem_solving_data_analysis","sat_official_domain":"problem_solving_data_analysis","sat_skill":"ratios_rates_proportions_units","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"psda-ratio-003","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('4caadfcb-db9c-182c-e300-66c226694325','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"Multiply the number of feet by 12 inches per foot: $7.5 \\times 12 = 90$ inches. Choice D is correct. Choice A is incorrect. This divides by 12 instead of multiplying; inches are smaller units, so the number of inches must be larger. Choice B is incorrect. This adds 12 instead of multiplying by 12. Choice C is incorrect. This converts only the 7 whole feet and ignores the extra half foot."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('f2e2d8c2-c7c6-8ebe-6246-ddb9a751ce81','7404498b-69de-518e-aeec-f2bb9a98409c','question_single_choice','{"prompt":"A printer prints $45$ pages per minute. At this rate, how many minutes will it take the printer to print $1{,}260$ pages?","options":[{"id":"A","label":"$2.8$"},{"id":"B","label":"$28$"},{"id":"C","label":"$1{,}215$"},{"id":"D","label":"$56{,}700$"}]}'::jsonb,4,'{"section_type":"math","sat_domain":"problem_solving_data_analysis","sat_official_domain":"problem_solving_data_analysis","sat_skill":"ratios_rates_proportions_units","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"psda-ratio-004","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('f2e2d8c2-c7c6-8ebe-6246-ddb9a751ce81','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"Time equals pages divided by rate: $\\frac{1{,}260}{45} = 28$ minutes. Choice B is correct. Choice A is incorrect. This misplaces the decimal point when dividing 1,260 by 45. Choice C is incorrect. This subtracts the rate from the number of pages instead of dividing. Choice D is incorrect. This multiplies the rate by the number of pages, which gives units of pages squared per minute, not minutes."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('53fdd11b-cdfa-24e2-196b-285cddcc8a81','7404498b-69de-518e-aeec-f2bb9a98409c','question_spr','{"prompt":"On a map, $1$ centimeter represents $2.5$ kilometers. Two towns are $6.4$ centimeters apart on the map. What is the actual distance between the towns, in kilometers?"}'::jsonb,5,'{"section_type":"math","sat_domain":"problem_solving_data_analysis","sat_official_domain":"problem_solving_data_analysis","sat_skill":"ratios_rates_proportions_units","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"psda-ratio-005","answer_format":"spr"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('53fdd11b-cdfa-24e2-196b-285cddcc8a81','{"accepted":["16"]}'::jsonb,'{"feedback":{"explanation":"Multiply the map distance by the scale: $6.4 \\times 2.5 = 16$ kilometers."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('7d6953ae-724e-8ad0-7167-5a468050c0d7','7404498b-69de-518e-aeec-f2bb9a98409c','question_single_choice','{"prompt":"A pump moves water at a constant rate of $750$ liters per hour. How many liters of water does the pump move in $36$ minutes?","options":[{"id":"A","label":"$20.8$"},{"id":"B","label":"$450$"},{"id":"C","label":"$1{,}250$"},{"id":"D","label":"$27{,}000$"}]}'::jsonb,6,'{"section_type":"math","sat_domain":"problem_solving_data_analysis","sat_official_domain":"problem_solving_data_analysis","sat_skill":"ratios_rates_proportions_units","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"psda-ratio-006","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('7d6953ae-724e-8ad0-7167-5a468050c0d7','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"36 minutes is $\\frac{36}{60} = 0.6$ hour, so the pump moves $750 \\times 0.6 = 450$ liters. Choice B is correct. Choice A is incorrect. This divides the hourly rate by 36, which mixes hours and minutes incorrectly. Choice C is incorrect. This multiplies by $\\frac{60}{36}$ instead of $\\frac{36}{60}$, so the conversion factor is inverted. Choice D is incorrect. This multiplies 750 liters per hour by 36 as if 36 minutes were 36 hours."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('2e590f22-a1e4-f9eb-da74-fec94b165e21','7404498b-69de-518e-aeec-f2bb9a98409c','question_single_choice','{"prompt":"A runner''s top speed is $20$ meters per second. What is this speed in kilometers per hour? ($1$ kilometer $= 1{,}000$ meters)","options":[{"id":"A","label":"$1.2$"},{"id":"B","label":"$5.56$"},{"id":"C","label":"$72$"},{"id":"D","label":"$1{,}200$"}]}'::jsonb,7,'{"section_type":"math","sat_domain":"problem_solving_data_analysis","sat_official_domain":"problem_solving_data_analysis","sat_skill":"ratios_rates_proportions_units","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"psda-ratio-007","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('2e590f22-a1e4-f9eb-da74-fec94b165e21','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"Multiply by 3,600 seconds per hour and divide by 1,000 meters per kilometer: $20 \\times \\frac{3{,}600}{1{,}000} = 72$ kilometers per hour. Choice C is correct. Choice A is incorrect. This converts seconds to minutes only (multiplying by 60), giving kilometers per minute. Choice B is incorrect. This divides by 3.6 instead of multiplying; the conversion factors are applied in the wrong direction. Choice D is incorrect. This multiplies by 60 and does not convert meters to kilometers."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('a46e19ad-d8f2-3f1f-06c9-ccf4aedf8838','7404498b-69de-518e-aeec-f2bb9a98409c','question_spr','{"prompt":"A bag contains only red and blue marbles in a ratio of $5$ to $3$. There are $64$ marbles in the bag. How many more red marbles than blue marbles are in the bag?"}'::jsonb,8,'{"section_type":"math","sat_domain":"problem_solving_data_analysis","sat_official_domain":"problem_solving_data_analysis","sat_skill":"ratios_rates_proportions_units","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"psda-ratio-008","answer_format":"spr"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('a46e19ad-d8f2-3f1f-06c9-ccf4aedf8838','{"accepted":["16"]}'::jsonb,'{"feedback":{"explanation":"The ratio has $5 + 3 = 8$ parts, so each part is $\\frac{64}{8} = 8$ marbles. There are $40$ red and $24$ blue marbles, a difference of $16$."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('15a4e32a-d557-d241-0a56-c7a3ac3bd6a5','7404498b-69de-518e-aeec-f2bb9a98409c','question_single_choice','{"prompt":"Every $100$ milliliters of a salt solution contains $12$ grams of salt. How many milliliters of the solution contain $30$ grams of salt?","options":[{"id":"A","label":"$2.5$"},{"id":"B","label":"$40$"},{"id":"C","label":"$250$"},{"id":"D","label":"$360$"}]}'::jsonb,9,'{"section_type":"math","sat_domain":"problem_solving_data_analysis","sat_official_domain":"problem_solving_data_analysis","sat_skill":"ratios_rates_proportions_units","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"psda-ratio-009","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('15a4e32a-d557-d241-0a56-c7a3ac3bd6a5','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"Set up $\\frac{12}{100} = \\frac{30}{v}$. Then $v = \\frac{30 \\times 100}{12} = 250$ milliliters. Choice C is correct. Choice A is incorrect. This is $\\frac{30}{12}$, the number of 100-milliliter portions, not the number of milliliters. Choice B is incorrect. This sets up the proportion upside down, $\\frac{12 \\cdot 100}{30}$. Choice D is incorrect. This multiplies the two given amounts of salt, which has no meaning in this context."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('7f538fc0-e8ce-c605-5d7e-bcee1a9d6e4d','7404498b-69de-518e-aeec-f2bb9a98409c','question_single_choice','{"prompt":"A cyclist rides $\\frac{3}{4}$ mile in $2.5$ minutes. At this rate, how many miles does the cyclist ride in $1$ hour?","options":[{"id":"A","label":"$0.3$"},{"id":"B","label":"$1.875$"},{"id":"C","label":"$18$"},{"id":"D","label":"$30$"}]}'::jsonb,10,'{"section_type":"math","sat_domain":"problem_solving_data_analysis","sat_official_domain":"problem_solving_data_analysis","sat_skill":"ratios_rates_proportions_units","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"psda-ratio-010","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('7f538fc0-e8ce-c605-5d7e-bcee1a9d6e4d','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"The rate is $\\frac{0.75}{2.5} = 0.3$ mile per minute, so in 60 minutes the cyclist rides $0.3 \\times 60 = 18$ miles. Choice C is correct. Choice A is incorrect. This is the rate in miles per minute; it still needs to be multiplied by 60. Choice B is incorrect. This multiplies distance by time instead of dividing distance by time. Choice D is incorrect. This uses only the whole number of minutes and ignores the distance of $\\frac{3}{4}$ mile."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('6abb4955-678e-94b5-c54e-746bfd0686d9','7404498b-69de-518e-aeec-f2bb9a98409c','question_single_choice','{"prompt":"The quantity $y$ is directly proportional to $x$. When $x = 4$, $y = 14$. What is the value of $y$ when $x = 10$?","options":[{"id":"A","label":"$2.86$"},{"id":"B","label":"$20$"},{"id":"C","label":"$35$"},{"id":"D","label":"$140$"}]}'::jsonb,11,'{"section_type":"math","sat_domain":"problem_solving_data_analysis","sat_official_domain":"problem_solving_data_analysis","sat_skill":"ratios_rates_proportions_units","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"psda-ratio-011","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('6abb4955-678e-94b5-c54e-746bfd0686d9','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"Since $y = kx$, $k = \\frac{14}{4} = 3.5$. Then $y = 3.5 \\times 10 = 35$. Choice C is correct. Choice A is incorrect. This uses the constant $\\frac{x}{y}$ in the wrong place, computing $\\frac{4 \\cdot 10}{14}$. Choice B is incorrect. This adds the change in $x$ to $y$, treating the relationship as $y = x + 10$ rather than $y = kx$. Choice D is incorrect. This multiplies 14 by 10 without first dividing by 4 to find the constant of proportionality."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('e8dd5a52-a867-2790-2d60-933ecf8a0660','7404498b-69de-518e-aeec-f2bb9a98409c','question_single_choice','{"prompt":"A carpet costs $24$ dollars per square yard. What is the cost of the carpet, in dollars per square foot? ($1$ yard $= 3$ feet)","options":[{"id":"A","label":"$\\frac{8}{3}$"},{"id":"B","label":"$8$"},{"id":"C","label":"$72$"},{"id":"D","label":"$216$"}]}'::jsonb,12,'{"section_type":"math","sat_domain":"problem_solving_data_analysis","sat_official_domain":"problem_solving_data_analysis","sat_skill":"ratios_rates_proportions_units","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"psda-ratio-012","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('e8dd5a52-a867-2790-2d60-933ecf8a0660','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"One square yard is $3 \\text{ ft} \\times 3 \\text{ ft} = 9$ square feet. The cost per square foot is $\\frac{24}{9} = \\frac{8}{3} \\approx 2.67$ dollars. Choice A is correct. Choice B is incorrect. This divides by 3, converting a length rather than an area. One square yard is $3 \\times 3 = 9$ square feet. Choice C is incorrect. This multiplies by 3; a square foot is smaller than a square yard, so the cost per square foot must be less than 24. Choice D is incorrect. This multiplies by 9 instead of dividing by 9."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('a44cfe07-4402-f62b-e5d7-86d810d96043','7404498b-69de-518e-aeec-f2bb9a98409c','question_spr','{"prompt":"Machine A fills $240$ bottles in $8$ minutes. Working together at their constant rates, machines A and B fill $600$ bottles in $12$ minutes. How many minutes would it take machine B, working alone, to fill $400$ bottles?"}'::jsonb,13,'{"section_type":"math","sat_domain":"problem_solving_data_analysis","sat_official_domain":"problem_solving_data_analysis","sat_skill":"ratios_rates_proportions_units","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"psda-ratio-013","answer_format":"spr"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('a44cfe07-4402-f62b-e5d7-86d810d96043','{"accepted":["20"]}'::jsonb,'{"feedback":{"explanation":"Machine A fills $\\frac{240}{8} = 30$ bottles per minute, and together they fill $\\frac{600}{12} = 50$ bottles per minute. Machine B fills $50 - 30 = 20$ bottles per minute, so 400 bottles take $\\frac{400}{20} = 20$ minutes."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('a9e21834-0d74-1ac5-d855-fa7fb0c6e9bf','7404498b-69de-518e-aeec-f2bb9a98409c','question_single_choice','{"prompt":"For positive quantities $a$, $b$, and $c$, the ratio of $a$ to $b$ is $3 : 5$ and the ratio of $b$ to $c$ is $4 : 7$. What is the ratio of $a$ to $c$?","options":[{"id":"A","label":"$7 : 12$"},{"id":"B","label":"$21 : 20$"},{"id":"C","label":"$3 : 7$"},{"id":"D","label":"$12 : 35$"}]}'::jsonb,14,'{"section_type":"math","sat_domain":"problem_solving_data_analysis","sat_official_domain":"problem_solving_data_analysis","sat_skill":"ratios_rates_proportions_units","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"psda-ratio-014","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('a9e21834-0d74-1ac5-d855-fa7fb0c6e9bf','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"Rewrite both ratios with a common value of $b$: $a : b = 12 : 20$ and $b : c = 20 : 35$. So $a : c = 12 : 35$. Equivalently, $\\frac{a}{c} = \\frac{a}{b} \\cdot \\frac{b}{c} = \\frac{3}{5} \\cdot \\frac{4}{7} = \\frac{12}{35}$. Choice D is correct. Choice A is incorrect. This adds the corresponding terms of the two ratios, which is not a valid way to combine ratios. Choice B is incorrect. This divides $\\frac{3}{5}$ by $\\frac{4}{7}$ instead of multiplying $\\frac{a}{b} \\cdot \\frac{b}{c}$. Choice C is incorrect. This pairs the first term of one ratio with the second term of the other without making $b$ the same in both ratios."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('3e488b2c-b8fc-b7ab-95c0-11b30e7fe023','7404498b-69de-518e-aeec-f2bb9a98409c','question_single_choice','{"prompt":"What is $15\\%$ of $240$?","options":[{"id":"A","label":"$3.6$"},{"id":"B","label":"$16$"},{"id":"C","label":"$36$"},{"id":"D","label":"$204$"}]}'::jsonb,15,'{"section_type":"math","sat_domain":"problem_solving_data_analysis","sat_official_domain":"problem_solving_data_analysis","sat_skill":"percentages","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"psda-pct-001","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('3e488b2c-b8fc-b7ab-95c0-11b30e7fe023','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"$15\\%$ of 240 is $0.15 \\times 240 = 36$. Choice C is correct. Choice A is incorrect. This uses 0.015 instead of 0.15 for 15%. Choice B is incorrect. This divides 240 by 15 instead of multiplying 240 by 0.15. Choice D is incorrect. This is 85% of 240, the amount left after removing 15%."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('3c5febcb-48a2-3a0c-ef1f-0ad4e1bad114','7404498b-69de-518e-aeec-f2bb9a98409c','question_spr','{"prompt":"A jacket that regularly sells for $80$ dollars is on sale for $25\\%$ off the regular price. What is the sale price of the jacket, in dollars?"}'::jsonb,16,'{"section_type":"math","sat_domain":"problem_solving_data_analysis","sat_official_domain":"problem_solving_data_analysis","sat_skill":"percentages","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"psda-pct-002","answer_format":"spr"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('3c5febcb-48a2-3a0c-ef1f-0ad4e1bad114','{"accepted":["60"]}'::jsonb,'{"feedback":{"explanation":"The discount is $0.25 \\times 80 = 20$ dollars, so the sale price is $80 - 20 = 60$ dollars."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('44320ce6-eb7d-fe1d-60d0-2e557bf623a6','7404498b-69de-518e-aeec-f2bb9a98409c','question_single_choice','{"prompt":"The number $18$ is what percent of $72$?","options":[{"id":"A","label":"$4\\%$"},{"id":"B","label":"$25\\%$"},{"id":"C","label":"$54\\%$"},{"id":"D","label":"$400\\%$"}]}'::jsonb,17,'{"section_type":"math","sat_domain":"problem_solving_data_analysis","sat_official_domain":"problem_solving_data_analysis","sat_skill":"percentages","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"psda-pct-003","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('44320ce6-eb7d-fe1d-60d0-2e557bf623a6','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"Divide the part by the whole: $\\frac{18}{72} = 0.25$, which is $25\\%$. Choice B is correct. Choice A is incorrect. This is the quotient $\\frac{72}{18} = 4$ written as a percent without multiplying by 100. Choice C is incorrect. This subtracts the two numbers instead of dividing. Choice D is incorrect. This is $\\frac{72}{18} \\times 100$; it tells what percent 72 is of 18."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('7e9a4c25-88dd-4d8a-19bf-d797fa9ebe06','7404498b-69de-518e-aeec-f2bb9a98409c','question_single_choice','{"prompt":"The population of a town increased from $1{,}250$ to $1{,}500$. What was the percent increase in the population?","options":[{"id":"A","label":"$16.7\\%$"},{"id":"B","label":"$20\\%$"},{"id":"C","label":"$83.3\\%$"},{"id":"D","label":"$120\\%$"}]}'::jsonb,18,'{"section_type":"math","sat_domain":"problem_solving_data_analysis","sat_official_domain":"problem_solving_data_analysis","sat_skill":"percentages","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"psda-pct-004","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('7e9a4c25-88dd-4d8a-19bf-d797fa9ebe06','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"The increase is $1{,}500 - 1{,}250 = 250$. Divide by the original amount: $\\frac{250}{1{,}250} = 0.2$, a $20\\%$ increase. Choice B is correct. Choice A is incorrect. This divides the increase by the new population instead of the original population. Choice C is incorrect. This is the original population as a percent of the new population. Choice D is incorrect. This is the new population as a percent of the original; the increase is $120\\% - 100\\% = 20\\%$."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('2ae49ff5-37ef-bdcf-b5e1-8e9becb90031','7404498b-69de-518e-aeec-f2bb9a98409c','question_spr','{"prompt":"If $p\\%$ of $60$ is $21$, what is the value of $p$?"}'::jsonb,19,'{"section_type":"math","sat_domain":"problem_solving_data_analysis","sat_official_domain":"problem_solving_data_analysis","sat_skill":"percentages","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"psda-pct-005","answer_format":"spr"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('2ae49ff5-37ef-bdcf-b5e1-8e9becb90031','{"accepted":["35"]}'::jsonb,'{"feedback":{"explanation":"Write $\\frac{p}{100} \\times 60 = 21$. Then $p = \\frac{21 \\times 100}{60} = 35$."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('1dc61c1d-6290-6fe4-1ef6-3424cbb13626','7404498b-69de-518e-aeec-f2bb9a98409c','question_single_choice','{"prompt":"A store increased the price of a lamp, originally $150$ dollars, by $20\\%$. Later, the store decreased the new price by $20\\%$. What is the final price of the lamp, in dollars?","options":[{"id":"A","label":"$120$"},{"id":"B","label":"$144$"},{"id":"C","label":"$150$"},{"id":"D","label":"$180$"}]}'::jsonb,20,'{"section_type":"math","sat_domain":"problem_solving_data_analysis","sat_official_domain":"problem_solving_data_analysis","sat_skill":"percentages","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"psda-pct-006","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('1dc61c1d-6290-6fe4-1ef6-3424cbb13626','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"After the increase the price is $150 \\times 1.2 = 180$ dollars. After the decrease it is $180 \\times 0.8 = 144$ dollars. Choice B is correct. Choice A is incorrect. This takes 20% off the original price and ignores the earlier increase. Choice C is incorrect. This assumes the increase and decrease cancel; the 20% decrease is applied to a larger amount, 180 dollars. Choice D is incorrect. This is the price after the increase only; the 20% decrease was not applied."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('7c9e2cdc-4372-336a-85af-2e1ea82b6d5e','7404498b-69de-518e-aeec-f2bb9a98409c','question_single_choice','{"prompt":"After a $12\\%$ increase, the membership of a club is $1{,}568$. What was the membership before the increase?","options":[{"id":"A","label":"$1{,}379.84$"},{"id":"B","label":"$1{,}400$"},{"id":"C","label":"$1{,}556$"},{"id":"D","label":"$1{,}756.16$"}]}'::jsonb,21,'{"section_type":"math","sat_domain":"problem_solving_data_analysis","sat_official_domain":"problem_solving_data_analysis","sat_skill":"percentages","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"psda-pct-007","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('7c9e2cdc-4372-336a-85af-2e1ea82b6d5e','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"If $m$ is the original membership, $1.12m = 1{,}568$, so $m = \\frac{1{,}568}{1.12} = 1{,}400$. Choice B is correct. Choice A is incorrect. This multiplies by 0.88, taking 12% of the new total away; the 12% was based on the original membership. Choice C is incorrect. This subtracts 12 members instead of reversing a 12% increase. Choice D is incorrect. This applies another 12% increase instead of undoing one."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('993b8c23-eb76-4ba7-f641-dd891e8cd799','7404498b-69de-518e-aeec-f2bb9a98409c','question_spr','{"prompt":"A store sets the retail price of a backpack by marking up its wholesale cost by $60\\%$. The retail price is $72$ dollars. What is the wholesale cost, in dollars?"}'::jsonb,22,'{"section_type":"math","sat_domain":"problem_solving_data_analysis","sat_official_domain":"problem_solving_data_analysis","sat_skill":"percentages","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"psda-pct-008","answer_format":"spr"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('993b8c23-eb76-4ba7-f641-dd891e8cd799','{"accepted":["45"]}'::jsonb,'{"feedback":{"explanation":"If $w$ is the wholesale cost, then $1.6w = 72$, so $w = \\frac{72}{1.6} = 45$ dollars. (Taking 60% off 72 dollars would give 28.8 dollars, which is not correct, because the markup is based on the wholesale cost.)"},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('d3c952e2-bca2-25c3-5452-146956c538bb','7404498b-69de-518e-aeec-f2bb9a98409c','question_single_choice','{"prompt":"The number $x$ is $30\\%$ greater than the number $y$, and $y$ is $20\\%$ less than the positive number $z$. The number $x$ is what percent of $z$?","options":[{"id":"A","label":"$84\\%$"},{"id":"B","label":"$90\\%$"},{"id":"C","label":"$104\\%$"},{"id":"D","label":"$110\\%$"}]}'::jsonb,23,'{"section_type":"math","sat_domain":"problem_solving_data_analysis","sat_official_domain":"problem_solving_data_analysis","sat_skill":"percentages","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"psda-pct-009","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('d3c952e2-bca2-25c3-5452-146956c538bb','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"Write $y = 0.8z$ and $x = 1.3y$. Then $x = 1.3(0.8z) = 1.04z$, so $x$ is $104\\%$ of $z$. Choice C is correct. Choice A is incorrect. This computes $0.7 \\times 1.2 = 0.84$, applying each change in the wrong direction. Choice B is incorrect. This adds and subtracts the percents with the signs reversed: $100 - 30 + 20 = 90$. Choice D is incorrect. This adds and subtracts the percents directly: $100 + 30 - 20 = 110$."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('830bc28f-bf1e-7412-5f64-cffb7b2f2d8a','7404498b-69de-518e-aeec-f2bb9a98409c','question_single_choice','{"prompt":"The table shows the number of members of a school robotics club in each grade. What percent of the club''s members are in grade 11?","table":{"headers":["Grade","Number of members"],"rows":[["9","48"],["10","60"],["11","72"],["12","60"]]},"options":[{"id":"A","label":"$25\\%$"},{"id":"B","label":"$30\\%$"},{"id":"C","label":"$42.9\\%$"},{"id":"D","label":"$72\\%$"}]}'::jsonb,24,'{"section_type":"math","sat_domain":"problem_solving_data_analysis","sat_official_domain":"problem_solving_data_analysis","sat_skill":"percentages","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"psda-pct-010","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('830bc28f-bf1e-7412-5f64-cffb7b2f2d8a','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"The total membership is $48 + 60 + 72 + 60 = 240$. The grade 11 percent is $\\frac{72}{240} = 0.3$, or $30\\%$. Choice B is correct. Choice A is incorrect. This is the percent of members in grade 10 (or grade 12), not grade 11. Choice C is incorrect. This divides by the number of members not in grade 11 instead of by the total. Choice D is incorrect. This treats the number of grade 11 members as a percent without dividing by the total."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('75078062-42df-ec2e-b404-9c20f10929a3','7404498b-69de-518e-aeec-f2bb9a98409c','question_spr','{"prompt":"A $400$-milliliter solution is $15\\%$ acid. How many milliliters of pure acid must be added to make a solution that is $20\\%$ acid?"}'::jsonb,25,'{"section_type":"math","sat_domain":"problem_solving_data_analysis","sat_official_domain":"problem_solving_data_analysis","sat_skill":"percentages","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"psda-pct-011","answer_format":"spr"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('75078062-42df-ec2e-b404-9c20f10929a3','{"accepted":["25"]}'::jsonb,'{"feedback":{"explanation":"The solution starts with $0.15 \\times 400 = 60$ mL of acid. After adding $a$ mL of pure acid, $\\frac{60 + a}{400 + a} = 0.2$. Then $60 + a = 80 + 0.2a$, so $0.8a = 20$ and $a = 25$."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('26c37fad-cd31-78af-0501-2f34fd8e0cbc','7404498b-69de-518e-aeec-f2bb9a98409c','question_single_choice','{"prompt":"The value of a machine decreases by $15\\%$ each year. At the end of $3$ years, the value of the machine is approximately what percent of its original value?","options":[{"id":"A","label":"$39\\%$"},{"id":"B","label":"$45\\%$"},{"id":"C","label":"$55\\%$"},{"id":"D","label":"$61\\%$"}]}'::jsonb,26,'{"section_type":"math","sat_domain":"problem_solving_data_analysis","sat_official_domain":"problem_solving_data_analysis","sat_skill":"percentages","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"psda-pct-012","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('26c37fad-cd31-78af-0501-2f34fd8e0cbc','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"Each year the value is multiplied by $0.85$. After 3 years it is $0.85^3 = 0.614125$ times the original, or about $61\\%$. Choice D is correct. Choice A is incorrect. This is the approximate percent of the value that was lost, not the percent that remains. Choice B is incorrect. This is the total of three 15% decreases treated as simple, which is not the remaining value. Choice C is incorrect. This subtracts $3 \\times 15\\% = 45\\%$ from 100%, but each decrease applies to the reduced value, not the original."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('8494b88a-b150-c745-8690-0636c8973386','7404498b-69de-518e-aeec-f2bb9a98409c','question_spr','{"prompt":"At a school, $40\\%$ of the students in a physics program are juniors and the rest are seniors. Of the juniors, $25\\%$ take an advanced lab, and of the seniors, $50\\%$ take the advanced lab. Of the students in the program who take the advanced lab, $p\\%$ are juniors. What is the value of $p$?"}'::jsonb,27,'{"section_type":"math","sat_domain":"problem_solving_data_analysis","sat_official_domain":"problem_solving_data_analysis","sat_skill":"percentages","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"psda-pct-013","answer_format":"spr"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('8494b88a-b150-c745-8690-0636c8973386','{"accepted":["25"]}'::jsonb,'{"feedback":{"explanation":"Juniors in the lab make up $0.40 \\times 0.25 = 0.10$ of the program, and seniors in the lab make up $0.60 \\times 0.50 = 0.30$. The lab is $0.10 + 0.30 = 0.40$ of the program, so juniors are $\\frac{0.10}{0.40} = 0.25$, or $25\\%$, of the lab students."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('4fc11b0d-cc9f-5e3c-d985-c296eccd5fe9','7404498b-69de-518e-aeec-f2bb9a98409c','question_single_choice','{"prompt":"The positive number $A$ is $25\\%$ greater than the positive number $B$. The number $B$ is what percent less than $A$?","options":[{"id":"A","label":"$20\\%$"},{"id":"B","label":"$25\\%$"},{"id":"C","label":"$75\\%$"},{"id":"D","label":"$80\\%$"}]}'::jsonb,28,'{"section_type":"math","sat_domain":"problem_solving_data_analysis","sat_official_domain":"problem_solving_data_analysis","sat_skill":"percentages","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"psda-pct-014","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('4fc11b0d-cc9f-5e3c-d985-c296eccd5fe9','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"Let $B = 100$. Then $A = 125$, and $B$ is $125 - 100 = 25$ less than $A$. As a percent of $A$, that is $\\frac{25}{125} = 0.2$, or $20\\%$. Choice A is correct. Choice B is incorrect. This assumes the percent difference is the same in both directions, but the comparison to $A$ uses a larger base. Choice C is incorrect. This subtracts 25% from 100%, which compares to $B$ rather than to $A$. Choice D is incorrect. This is $B$ as a percent of $A$; $B$ is $100\\% - 80\\% = 20\\%$ less than $A$."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('55853abe-f8da-00e4-eb3f-32b468c01ac4','7404498b-69de-518e-aeec-f2bb9a98409c','question_single_choice','{"prompt":"The numbers of laps swum by $5$ students during a practice were $12$, $15$, $9$, $20$, and $24$. What is the mean number of laps swum by these students?","options":[{"id":"A","label":"$15$"},{"id":"B","label":"$16$"},{"id":"C","label":"$24$"},{"id":"D","label":"$80$"}]}'::jsonb,29,'{"section_type":"math","sat_domain":"problem_solving_data_analysis","sat_official_domain":"problem_solving_data_analysis","sat_skill":"one_variable_data","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"psda-onevar-001","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('55853abe-f8da-00e4-eb3f-32b468c01ac4','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"The sum is $12 + 15 + 9 + 20 + 24 = 80$, so the mean is $\\frac{80}{5} = 16$. Choice B is correct. Choice A is incorrect. This is the median, the middle value of the ordered list, not the mean. Choice C is incorrect. This is the greatest value in the data set. Choice D is incorrect. This is the total number of laps; it still needs to be divided by 5."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('9e64040e-2e3a-7472-004c-42a0fec730f1','7404498b-69de-518e-aeec-f2bb9a98409c','question_spr','{"prompt":"The mean of $4$ numbers is $9$. Three of the numbers are $6$, $11$, and $7$. What is the fourth number?"}'::jsonb,30,'{"section_type":"math","sat_domain":"problem_solving_data_analysis","sat_official_domain":"problem_solving_data_analysis","sat_skill":"one_variable_data","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"psda-onevar-002","answer_format":"spr"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('9e64040e-2e3a-7472-004c-42a0fec730f1','{"accepted":["12"]}'::jsonb,'{"feedback":{"explanation":"The four numbers have a sum of $4 \\times 9 = 36$. The three known numbers add to $24$, so the fourth number is $36 - 24 = 12$."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('b36183fa-d946-a851-8987-a8aef90e4670','7404498b-69de-518e-aeec-f2bb9a98409c','question_single_choice','{"prompt":"The dot plot shows the number of hours each of $10$ volunteers worked at a community garden last week. What is the range of the number of hours worked?","figure_svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 420 220\" width=\"420\" height=\"220\" font-family=\"Arial, Helvetica, sans-serif\" font-size=\"17\" role=\"img\"><title>Dot plot of hours worked by 10 volunteers: one at 2, two at 3, three at 4, two at 5, one at 6, one at 8.</title><rect x=\"0\" y=\"0\" width=\"420\" height=\"220\" fill=\"#ffffff\"/><line x1=\"20\" y1=\"160\" x2=\"400\" y2=\"160\" stroke=\"#1f2937\" stroke-width=\"1.5\"/><line x1=\"30\" y1=\"160\" x2=\"30\" y2=\"166\" stroke=\"#1f2937\" stroke-width=\"1.5\"/><text x=\"30\" y=\"184\" text-anchor=\"middle\" font-size=\"15\" fill=\"#1f2937\">1</text><line x1=\"75\" y1=\"160\" x2=\"75\" y2=\"166\" stroke=\"#1f2937\" stroke-width=\"1.5\"/><text x=\"75\" y=\"184\" text-anchor=\"middle\" font-size=\"15\" fill=\"#1f2937\">2</text><line x1=\"120\" y1=\"160\" x2=\"120\" y2=\"166\" stroke=\"#1f2937\" stroke-width=\"1.5\"/><text x=\"120\" y=\"184\" text-anchor=\"middle\" font-size=\"15\" fill=\"#1f2937\">3</text><line x1=\"165\" y1=\"160\" x2=\"165\" y2=\"166\" stroke=\"#1f2937\" stroke-width=\"1.5\"/><text x=\"165\" y=\"184\" text-anchor=\"middle\" font-size=\"15\" fill=\"#1f2937\">4</text><line x1=\"210\" y1=\"160\" x2=\"210\" y2=\"166\" stroke=\"#1f2937\" stroke-width=\"1.5\"/><text x=\"210\" y=\"184\" text-anchor=\"middle\" font-size=\"15\" fill=\"#1f2937\">5</text><line x1=\"255\" y1=\"160\" x2=\"255\" y2=\"166\" stroke=\"#1f2937\" stroke-width=\"1.5\"/><text x=\"255\" y=\"184\" text-anchor=\"middle\" font-size=\"15\" fill=\"#1f2937\">6</text><line x1=\"300\" y1=\"160\" x2=\"300\" y2=\"166\" stroke=\"#1f2937\" stroke-width=\"1.5\"/><text x=\"300\" y=\"184\" text-anchor=\"middle\" font-size=\"15\" fill=\"#1f2937\">7</text><line x1=\"345\" y1=\"160\" x2=\"345\" y2=\"166\" stroke=\"#1f2937\" stroke-width=\"1.5\"/><text x=\"345\" y=\"184\" text-anchor=\"middle\" font-size=\"15\" fill=\"#1f2937\">8</text><line x1=\"390\" y1=\"160\" x2=\"390\" y2=\"166\" stroke=\"#1f2937\" stroke-width=\"1.5\"/><text x=\"390\" y=\"184\" text-anchor=\"middle\" font-size=\"15\" fill=\"#1f2937\">9</text><circle cx=\"75\" cy=\"148\" r=\"6\" fill=\"#1f2937\"/><circle cx=\"120\" cy=\"148\" r=\"6\" fill=\"#1f2937\"/><circle cx=\"120\" cy=\"130\" r=\"6\" fill=\"#1f2937\"/><circle cx=\"165\" cy=\"148\" r=\"6\" fill=\"#1f2937\"/><circle cx=\"165\" cy=\"130\" r=\"6\" fill=\"#1f2937\"/><circle cx=\"165\" cy=\"112\" r=\"6\" fill=\"#1f2937\"/><circle cx=\"210\" cy=\"148\" r=\"6\" fill=\"#1f2937\"/><circle cx=\"210\" cy=\"130\" r=\"6\" fill=\"#1f2937\"/><circle cx=\"255\" cy=\"148\" r=\"6\" fill=\"#1f2937\"/><circle cx=\"345\" cy=\"148\" r=\"6\" fill=\"#1f2937\"/><text x=\"210\" y=\"210\" text-anchor=\"middle\" font-size=\"16\" fill=\"#1f2937\">Hours worked</text></svg>","options":[{"id":"A","label":"$4$"},{"id":"B","label":"$6$"},{"id":"C","label":"$8$"},{"id":"D","label":"$10$"}]}'::jsonb,31,'{"section_type":"math","sat_domain":"problem_solving_data_analysis","sat_official_domain":"problem_solving_data_analysis","sat_skill":"one_variable_data","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"psda-onevar-003","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('b36183fa-d946-a851-8987-a8aef90e4670','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"The greatest value is 8 and the least value is 2, so the range is $8 - 2 = 6$. Choice B is correct. Choice A is incorrect. This is the mode, the value that appears most often. Choice C is incorrect. This is the greatest value, not the difference between the greatest and least values. Choice D is incorrect. This is the number of volunteers."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('ced2fb4e-cb3b-fcb3-b630-bdcdc7469fc6','7404498b-69de-518e-aeec-f2bb9a98409c','question_single_choice','{"prompt":"What is the median of the data set $7$, $3$, $9$, $4$, $12$, $10$?","options":[{"id":"A","label":"$6.5$"},{"id":"B","label":"$7.5$"},{"id":"C","label":"$8$"},{"id":"D","label":"$9$"}]}'::jsonb,32,'{"section_type":"math","sat_domain":"problem_solving_data_analysis","sat_official_domain":"problem_solving_data_analysis","sat_skill":"one_variable_data","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"psda-onevar-004","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('ced2fb4e-cb3b-fcb3-b630-bdcdc7469fc6','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"In order, the values are $3, 4, 7, 9, 10, 12$. With 6 values, the median is the mean of the two middle values: $\\frac{7 + 9}{2} = 8$. Choice C is correct. Choice A is incorrect. This averages the two middle numbers of the list as given, without first putting the values in order. Choice B is incorrect. This is the mean of the data set. Choice D is incorrect. This is only one of the two middle values of the ordered list $3, 4, 7, 9, 10, 12$."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('719f466f-d2b8-8509-6a3f-3167c4f59d56','7404498b-69de-518e-aeec-f2bb9a98409c','question_single_choice','{"prompt":"The table shows the number of goals a soccer team scored in each of its $20$ games last season. What is the total number of goals the team scored in these games?","table":{"headers":["Goals scored","Number of games"],"rows":[["0","3"],["1","6"],["2","5"],["3","4"],["4","2"]]},"options":[{"id":"A","label":"$10$"},{"id":"B","label":"$20$"},{"id":"C","label":"$36$"},{"id":"D","label":"$46$"}]}'::jsonb,33,'{"section_type":"math","sat_domain":"problem_solving_data_analysis","sat_official_domain":"problem_solving_data_analysis","sat_skill":"one_variable_data","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"psda-onevar-005","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('719f466f-d2b8-8509-6a3f-3167c4f59d56','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"Multiply each number of goals by its frequency and add: $0(3) + 1(6) + 2(5) + 3(4) + 4(2) = 0 + 6 + 10 + 12 + 8 = 36$. Choice C is correct. Choice A is incorrect. This adds the different goal values without weighting each by its frequency. Choice B is incorrect. This is the number of games, not the number of goals. Choice D is incorrect. This counts each of the 5 games with 2 goals as 4 goals."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('63f2c2b6-c2f0-cf38-a40b-b69a8cbc35e3','7404498b-69de-518e-aeec-f2bb9a98409c','question_single_choice','{"prompt":"The bar graph shows the number of pets owned by each of $25$ households on a street. What is the median number of pets owned by these households?","figure_svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 420 320\" width=\"420\" height=\"320\" font-family=\"Arial, Helvetica, sans-serif\" font-size=\"17\" role=\"img\"><title>Bar graph: 0 pets, 9 households; 1 pet, 7; 2 pets, 5; 3 pets, 3; 4 pets, 1.</title><rect x=\"0\" y=\"0\" width=\"420\" height=\"320\" fill=\"#ffffff\"/><line x1=\"62\" y1=\"262\" x2=\"400\" y2=\"262\" stroke=\"#d1d5db\" stroke-width=\"1\"/><text x=\"54\" y=\"267\" text-anchor=\"end\" font-size=\"15\" fill=\"#1f2937\">0</text><line x1=\"62\" y1=\"213.2\" x2=\"400\" y2=\"213.2\" stroke=\"#d1d5db\" stroke-width=\"1\"/><text x=\"54\" y=\"218.2\" text-anchor=\"end\" font-size=\"15\" fill=\"#1f2937\">2</text><line x1=\"62\" y1=\"164.4\" x2=\"400\" y2=\"164.4\" stroke=\"#d1d5db\" stroke-width=\"1\"/><text x=\"54\" y=\"169.4\" text-anchor=\"end\" font-size=\"15\" fill=\"#1f2937\">4</text><line x1=\"62\" y1=\"115.6\" x2=\"400\" y2=\"115.6\" stroke=\"#d1d5db\" stroke-width=\"1\"/><text x=\"54\" y=\"120.6\" text-anchor=\"end\" font-size=\"15\" fill=\"#1f2937\">6</text><line x1=\"62\" y1=\"66.8\" x2=\"400\" y2=\"66.8\" stroke=\"#d1d5db\" stroke-width=\"1\"/><text x=\"54\" y=\"71.8\" text-anchor=\"end\" font-size=\"15\" fill=\"#1f2937\">8</text><line x1=\"62\" y1=\"18\" x2=\"400\" y2=\"18\" stroke=\"#d1d5db\" stroke-width=\"1\"/><text x=\"54\" y=\"23\" text-anchor=\"end\" font-size=\"15\" fill=\"#1f2937\">10</text><line x1=\"62\" y1=\"262\" x2=\"400\" y2=\"262\" stroke=\"#1f2937\" stroke-width=\"1.5\"/><line x1=\"62\" y1=\"18\" x2=\"62\" y2=\"262\" stroke=\"#1f2937\" stroke-width=\"1.5\"/><text x=\"231\" y=\"310\" text-anchor=\"middle\" font-size=\"16\" fill=\"#1f2937\">Number of pets</text><text x=\"18\" y=\"140\" text-anchor=\"middle\" font-size=\"16\" transform=\"rotate(-90 18 140)\" fill=\"#1f2937\">Number of households</text><rect x=\"75.52\" y=\"42.4\" width=\"40.56\" height=\"219.6\" fill=\"#1d4ed8\" fill-opacity=\"0.75\" stroke=\"#1f2937\" stroke-width=\"1\"/><text x=\"95.8\" y=\"282\" text-anchor=\"middle\" font-size=\"15\" fill=\"#1f2937\">0</text><rect x=\"143.12\" y=\"91.2\" width=\"40.56\" height=\"170.8\" fill=\"#1d4ed8\" fill-opacity=\"0.75\" stroke=\"#1f2937\" stroke-width=\"1\"/><text x=\"163.4\" y=\"282\" text-anchor=\"middle\" font-size=\"15\" fill=\"#1f2937\">1</text><rect x=\"210.72\" y=\"140\" width=\"40.56\" height=\"122\" fill=\"#1d4ed8\" fill-opacity=\"0.75\" stroke=\"#1f2937\" stroke-width=\"1\"/><text x=\"231\" y=\"282\" text-anchor=\"middle\" font-size=\"15\" fill=\"#1f2937\">2</text><rect x=\"278.32\" y=\"188.8\" width=\"40.56\" height=\"73.2\" fill=\"#1d4ed8\" fill-opacity=\"0.75\" stroke=\"#1f2937\" stroke-width=\"1\"/><text x=\"298.6\" y=\"282\" text-anchor=\"middle\" font-size=\"15\" fill=\"#1f2937\">3</text><rect x=\"345.92\" y=\"237.6\" width=\"40.56\" height=\"24.4\" fill=\"#1d4ed8\" fill-opacity=\"0.75\" stroke=\"#1f2937\" stroke-width=\"1\"/><text x=\"366.2\" y=\"282\" text-anchor=\"middle\" font-size=\"15\" fill=\"#1f2937\">4</text></svg>","options":[{"id":"A","label":"$0$"},{"id":"B","label":"$1$"},{"id":"C","label":"$2$"},{"id":"D","label":"$5$"}]}'::jsonb,34,'{"section_type":"math","sat_domain":"problem_solving_data_analysis","sat_official_domain":"problem_solving_data_analysis","sat_skill":"one_variable_data","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"psda-onevar-006","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('63f2c2b6-c2f0-cf38-a40b-b69a8cbc35e3','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"With 25 households, the median is the 13th value when the data are ordered. The first 9 values are 0 and the next 7 values (the 10th through 16th) are 1, so the 13th value is 1. Choice B is correct. Choice A is incorrect. This is the mode, the number of pets owned by the most households. Choice C is incorrect. This is the middle category on the horizontal axis, which is not necessarily the middle value of the data. Choice D is incorrect. This is the middle frequency among the bar heights, not a number of pets."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('a4c5706c-7bf1-c9d9-ebf3-515538f31985','7404498b-69de-518e-aeec-f2bb9a98409c','question_single_choice','{"prompt":"A data set consists of $9$ different numbers. The greatest number, $40$, is replaced with $85$. Which statement about the new data set compared with the original data set must be true?","options":[{"id":"A","label":"The mean increases by 5, and the median does not change."},{"id":"B","label":"The mean and the median each increase by 5."},{"id":"C","label":"The mean does not change, and the median increases."},{"id":"D","label":"The mean increases by 45, and the median does not change."}]}'::jsonb,35,'{"section_type":"math","sat_domain":"problem_solving_data_analysis","sat_official_domain":"problem_solving_data_analysis","sat_skill":"one_variable_data","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"psda-onevar-007","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('a4c5706c-7bf1-c9d9-ebf3-515538f31985','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"The sum of the data increases by $85 - 40 = 45$, so the mean increases by $\\frac{45}{9} = 5$. The greatest value stays the greatest, so the 5th value in order, the median, is unchanged. Choice A is correct. Choice B is incorrect. The median is the 5th value in order, and changing the greatest value does not change it. Choice C is incorrect. Increasing a value increases the sum, so the mean must increase; the middle value is unaffected. Choice D is incorrect. The sum increases by 45, but the mean is the sum divided by 9, so it increases by $\\frac{45}{9} = 5$."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('91ad109e-caaa-4708-9d2d-d950f915d772','7404498b-69de-518e-aeec-f2bb9a98409c','question_spr','{"prompt":"The mean of $8$ numbers is $14$. When a ninth number is added to the data set, the mean of the $9$ numbers is $15$. What is the ninth number?"}'::jsonb,36,'{"section_type":"math","sat_domain":"problem_solving_data_analysis","sat_official_domain":"problem_solving_data_analysis","sat_skill":"one_variable_data","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"psda-onevar-008","answer_format":"spr"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('91ad109e-caaa-4708-9d2d-d950f915d772','{"accepted":["23"]}'::jsonb,'{"feedback":{"explanation":"The original sum is $8 \\times 14 = 112$, and the new sum is $9 \\times 15 = 135$. The ninth number is $135 - 112 = 23$."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('32ffa2f8-6788-4d0f-4356-972318ed1248','7404498b-69de-518e-aeec-f2bb9a98409c','question_single_choice','{"prompt":"The table shows the frequency of each value in data set A and data set B. Each data set contains $12$ values. Which statement best compares the standard deviations of the two data sets?","table":{"headers":["Value","Frequency in data set A","Frequency in data set B"],"rows":[["1","1","4"],["2","2","1"],["3","6","2"],["4","2","1"],["5","1","4"]]},"options":[{"id":"A","label":"The standard deviations of the two data sets are equal."},{"id":"B","label":"The standard deviation of data set A is greater than that of data set B."},{"id":"C","label":"There is not enough information to compare the standard deviations."},{"id":"D","label":"The standard deviation of data set A is less than that of data set B."}]}'::jsonb,37,'{"section_type":"math","sat_domain":"problem_solving_data_analysis","sat_official_domain":"problem_solving_data_analysis","sat_skill":"one_variable_data","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"psda-onevar-009","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('32ffa2f8-6788-4d0f-4356-972318ed1248','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"Both data sets are symmetric about 3, so each has a mean of 3. In data set A, half the values equal the mean, while in data set B, 8 of the 12 values are 1 or 5, as far from the mean as possible. So data set B is more spread out and has the greater standard deviation. Choice D is correct. Choice A is incorrect. The data sets have the same mean and range, but data set B has many more values at the extremes 1 and 5. Choice B is incorrect. Data set A has most of its values at the center, 3, so its values are closer to the mean, not farther. Choice C is incorrect. The table gives every value in both data sets, which is enough to compare their spread."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('b56ca557-8b22-d19c-882e-4c3d95fb957f','7404498b-69de-518e-aeec-f2bb9a98409c','question_single_choice','{"prompt":"The histogram shows the commute times, in minutes, of $30$ employees. Each interval includes its left endpoint but not its right endpoint. Which interval contains the median commute time?","figure_svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 420 320\" width=\"420\" height=\"320\" font-family=\"Arial, Helvetica, sans-serif\" font-size=\"17\" role=\"img\"><title>Histogram of commute times: 0 to 10 minutes, 9 employees; 10 to 20, 5; 20 to 30, 6; 30 to 40, 7; 40 to 50, 3.</title><rect x=\"0\" y=\"0\" width=\"420\" height=\"320\" fill=\"#ffffff\"/><line x1=\"62\" y1=\"262\" x2=\"400\" y2=\"262\" stroke=\"#d1d5db\" stroke-width=\"1\"/><text x=\"54\" y=\"267\" text-anchor=\"end\" font-size=\"15\" fill=\"#1f2937\">0</text><line x1=\"62\" y1=\"213.2\" x2=\"400\" y2=\"213.2\" stroke=\"#d1d5db\" stroke-width=\"1\"/><text x=\"54\" y=\"218.2\" text-anchor=\"end\" font-size=\"15\" fill=\"#1f2937\">2</text><line x1=\"62\" y1=\"164.4\" x2=\"400\" y2=\"164.4\" stroke=\"#d1d5db\" stroke-width=\"1\"/><text x=\"54\" y=\"169.4\" text-anchor=\"end\" font-size=\"15\" fill=\"#1f2937\">4</text><line x1=\"62\" y1=\"115.6\" x2=\"400\" y2=\"115.6\" stroke=\"#d1d5db\" stroke-width=\"1\"/><text x=\"54\" y=\"120.6\" text-anchor=\"end\" font-size=\"15\" fill=\"#1f2937\">6</text><line x1=\"62\" y1=\"66.8\" x2=\"400\" y2=\"66.8\" stroke=\"#d1d5db\" stroke-width=\"1\"/><text x=\"54\" y=\"71.8\" text-anchor=\"end\" font-size=\"15\" fill=\"#1f2937\">8</text><line x1=\"62\" y1=\"18\" x2=\"400\" y2=\"18\" stroke=\"#d1d5db\" stroke-width=\"1\"/><text x=\"54\" y=\"23\" text-anchor=\"end\" font-size=\"15\" fill=\"#1f2937\">10</text><text x=\"62\" y=\"282\" text-anchor=\"middle\" font-size=\"15\" fill=\"#1f2937\">0</text><text x=\"129.6\" y=\"282\" text-anchor=\"middle\" font-size=\"15\" fill=\"#1f2937\">10</text><text x=\"197.2\" y=\"282\" text-anchor=\"middle\" font-size=\"15\" fill=\"#1f2937\">20</text><text x=\"264.8\" y=\"282\" text-anchor=\"middle\" font-size=\"15\" fill=\"#1f2937\">30</text><text x=\"332.4\" y=\"282\" text-anchor=\"middle\" font-size=\"15\" fill=\"#1f2937\">40</text><text x=\"400\" y=\"282\" text-anchor=\"middle\" font-size=\"15\" fill=\"#1f2937\">50</text><line x1=\"62\" y1=\"262\" x2=\"400\" y2=\"262\" stroke=\"#1f2937\" stroke-width=\"1.5\"/><line x1=\"62\" y1=\"18\" x2=\"62\" y2=\"262\" stroke=\"#1f2937\" stroke-width=\"1.5\"/><text x=\"231\" y=\"310\" text-anchor=\"middle\" font-size=\"16\" fill=\"#1f2937\">Commute time (minutes)</text><text x=\"18\" y=\"140\" text-anchor=\"middle\" font-size=\"16\" transform=\"rotate(-90 18 140)\" fill=\"#1f2937\">Number of employees</text><rect x=\"62\" y=\"42.4\" width=\"67.6\" height=\"219.6\" fill=\"#1d4ed8\" fill-opacity=\"0.75\" stroke=\"#1f2937\" stroke-width=\"1\"/><rect x=\"129.6\" y=\"140\" width=\"67.6\" height=\"122\" fill=\"#1d4ed8\" fill-opacity=\"0.75\" stroke=\"#1f2937\" stroke-width=\"1\"/><rect x=\"197.2\" y=\"115.6\" width=\"67.6\" height=\"146.4\" fill=\"#1d4ed8\" fill-opacity=\"0.75\" stroke=\"#1f2937\" stroke-width=\"1\"/><rect x=\"264.8\" y=\"91.2\" width=\"67.6\" height=\"170.8\" fill=\"#1d4ed8\" fill-opacity=\"0.75\" stroke=\"#1f2937\" stroke-width=\"1\"/><rect x=\"332.4\" y=\"188.8\" width=\"67.6\" height=\"73.2\" fill=\"#1d4ed8\" fill-opacity=\"0.75\" stroke=\"#1f2937\" stroke-width=\"1\"/></svg>","options":[{"id":"A","label":"0 to 10 minutes"},{"id":"B","label":"10 to 20 minutes"},{"id":"C","label":"20 to 30 minutes"},{"id":"D","label":"30 to 40 minutes"}]}'::jsonb,38,'{"section_type":"math","sat_domain":"problem_solving_data_analysis","sat_official_domain":"problem_solving_data_analysis","sat_skill":"one_variable_data","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"psda-onevar-010","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('b56ca557-8b22-d19c-882e-4c3d95fb957f','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"The median is the mean of the 15th and 16th values in order. The first two intervals hold $9 + 5 = 14$ values, and the third interval holds values 15 through 20. So the median is in the interval from 20 to 30 minutes. Choice C is correct. Choice A is incorrect. This interval has the most employees, so it contains the mode, not the median. Choice B is incorrect. Only $9 + 5 = 14$ employees have commutes less than 20 minutes, so the 15th and 16th values are not in this interval. Choice D is incorrect. By 30 minutes, $9 + 5 + 6 = 20$ values have already been counted, which is past the 15th and 16th values."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('94d17d05-86d6-99e6-e892-062c038a1c23','7404498b-69de-518e-aeec-f2bb9a98409c','question_single_choice','{"prompt":"A data set of $15$ numbers has a mean of $40$ and a standard deviation of $6$. Two numbers in the data set, each equal to $40$, are removed. Which statement about the remaining $13$ numbers must be true?","options":[{"id":"A","label":"The mean is 40, and the standard deviation is greater than 6."},{"id":"B","label":"The mean is 40, and the standard deviation is 6."},{"id":"C","label":"The mean is less than 40, and the standard deviation is greater than 6."},{"id":"D","label":"The mean is 40, and the standard deviation is less than 6."}]}'::jsonb,39,'{"section_type":"math","sat_domain":"problem_solving_data_analysis","sat_official_domain":"problem_solving_data_analysis","sat_skill":"one_variable_data","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"psda-onevar-011","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('94d17d05-86d6-99e6-e892-062c038a1c23','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"The original sum is $15 \\times 40 = 600$. After removing two 40s, the sum is $520$ and $\\frac{520}{13} = 40$, so the mean is unchanged. The removed values each had a distance of 0 from the mean, so the sum of squared distances stays the same while the number of values decreases. The standard deviation therefore increases. Choice A is correct. Choice B is incorrect. The total of the squared distances from the mean is unchanged, but it is now shared among fewer values, so the standard deviation changes. Choice C is incorrect. The removed values equal the mean, so the sum decreases by 80 while the count decreases by 2; the mean stays $\\frac{600 - 80}{13} = 40$. Choice D is incorrect. Removing values that sit exactly at the mean leaves only values that are, on average, farther from the mean, so the spread increases."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('76ca6366-06ce-6069-6cc5-0fa36982fb8b','7404498b-69de-518e-aeec-f2bb9a98409c','question_spr','{"prompt":"The mean test score of the $20$ students in class A is $78$. The mean test score of the students in class B is $84$. The mean score of all the students in both classes combined is $81.6$. How many students are in class B?"}'::jsonb,40,'{"section_type":"math","sat_domain":"problem_solving_data_analysis","sat_official_domain":"problem_solving_data_analysis","sat_skill":"one_variable_data","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"psda-onevar-012","answer_format":"spr"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('76ca6366-06ce-6069-6cc5-0fa36982fb8b','{"accepted":["30"]}'::jsonb,'{"feedback":{"explanation":"Let $b$ be the number of students in class B. Then $\\frac{20(78) + 84b}{20 + b} = 81.6$. This gives $1{,}560 + 84b = 1{,}632 + 81.6b$, so $2.4b = 72$ and $b = 30$."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('21e40bc7-a2bc-e511-9f4a-89b739b35e66','7404498b-69de-518e-aeec-f2bb9a98409c','question_single_choice','{"prompt":"The data set $3$, $5$, $8$, $11$, $x$ has $5$ numbers, where $x > 11$. The mean of the data set is $2$ greater than its median. What is the value of $x$?","options":[{"id":"A","label":"$13$"},{"id":"B","label":"$18$"},{"id":"C","label":"$23$"},{"id":"D","label":"$50$"}]}'::jsonb,41,'{"section_type":"math","sat_domain":"problem_solving_data_analysis","sat_official_domain":"problem_solving_data_analysis","sat_skill":"one_variable_data","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"psda-onevar-013","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('21e40bc7-a2bc-e511-9f4a-89b739b35e66','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"Because $x > 11$, the ordered data are $3, 5, 8, 11, x$, and the median is 8. The mean must be $8 + 2 = 10$, so the sum is $5 \\times 10 = 50$. Then $3 + 5 + 8 + 11 + x = 50$, so $x = 23$. Choice C is correct. Choice A is incorrect. This makes the mean equal to the median, 8, rather than 2 greater. Choice B is incorrect. This makes the mean 9, which is only 1 greater than the median. Choice D is incorrect. This is the sum of all five numbers when the mean is 10, not the value of $x$."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('330df7f2-00d4-1c0c-f468-45d2eae1023c','7404498b-69de-518e-aeec-f2bb9a98409c','question_single_choice','{"prompt":"The scatterplot shows the number of hours $10$ students spent studying for a quiz and their quiz scores. A line of best fit is also shown. Based on the line of best fit, what is the predicted score for a student who studied for $6$ hours?","figure_svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 420 320\" width=\"420\" height=\"320\" font-family=\"Arial, Helvetica, sans-serif\" font-size=\"17\" role=\"img\"><title>Scatterplot of quiz score versus hours studied with a line of best fit through (0, 55) and (8, 95).</title><rect x=\"0\" y=\"0\" width=\"420\" height=\"320\" fill=\"#ffffff\"/><line x1=\"62\" y1=\"262\" x2=\"400\" y2=\"262\" stroke=\"#d1d5db\" stroke-width=\"1\"/><text x=\"54\" y=\"267\" text-anchor=\"end\" font-size=\"15\" fill=\"#1f2937\">50</text><line x1=\"62\" y1=\"213.2\" x2=\"400\" y2=\"213.2\" stroke=\"#d1d5db\" stroke-width=\"1\"/><text x=\"54\" y=\"218.2\" text-anchor=\"end\" font-size=\"15\" fill=\"#1f2937\">60</text><line x1=\"62\" y1=\"164.4\" x2=\"400\" y2=\"164.4\" stroke=\"#d1d5db\" stroke-width=\"1\"/><text x=\"54\" y=\"169.4\" text-anchor=\"end\" font-size=\"15\" fill=\"#1f2937\">70</text><line x1=\"62\" y1=\"115.6\" x2=\"400\" y2=\"115.6\" stroke=\"#d1d5db\" stroke-width=\"1\"/><text x=\"54\" y=\"120.6\" text-anchor=\"end\" font-size=\"15\" fill=\"#1f2937\">80</text><line x1=\"62\" y1=\"66.8\" x2=\"400\" y2=\"66.8\" stroke=\"#d1d5db\" stroke-width=\"1\"/><text x=\"54\" y=\"71.8\" text-anchor=\"end\" font-size=\"15\" fill=\"#1f2937\">90</text><line x1=\"62\" y1=\"18\" x2=\"400\" y2=\"18\" stroke=\"#d1d5db\" stroke-width=\"1\"/><text x=\"54\" y=\"23\" text-anchor=\"end\" font-size=\"15\" fill=\"#1f2937\">100</text><line x1=\"62\" y1=\"18\" x2=\"62\" y2=\"262\" stroke=\"#d1d5db\" stroke-width=\"1\"/><text x=\"62\" y=\"282\" text-anchor=\"middle\" font-size=\"15\" fill=\"#1f2937\">0</text><line x1=\"99.56\" y1=\"18\" x2=\"99.56\" y2=\"262\" stroke=\"#d1d5db\" stroke-width=\"1\"/><text x=\"99.56\" y=\"282\" text-anchor=\"middle\" font-size=\"15\" fill=\"#1f2937\">1</text><line x1=\"137.11\" y1=\"18\" x2=\"137.11\" y2=\"262\" stroke=\"#d1d5db\" stroke-width=\"1\"/><text x=\"137.11\" y=\"282\" text-anchor=\"middle\" font-size=\"15\" fill=\"#1f2937\">2</text><line x1=\"174.67\" y1=\"18\" x2=\"174.67\" y2=\"262\" stroke=\"#d1d5db\" stroke-width=\"1\"/><text x=\"174.67\" y=\"282\" text-anchor=\"middle\" font-size=\"15\" fill=\"#1f2937\">3</text><line x1=\"212.22\" y1=\"18\" x2=\"212.22\" y2=\"262\" stroke=\"#d1d5db\" stroke-width=\"1\"/><text x=\"212.22\" y=\"282\" text-anchor=\"middle\" font-size=\"15\" fill=\"#1f2937\">4</text><line x1=\"249.78\" y1=\"18\" x2=\"249.78\" y2=\"262\" stroke=\"#d1d5db\" stroke-width=\"1\"/><text x=\"249.78\" y=\"282\" text-anchor=\"middle\" font-size=\"15\" fill=\"#1f2937\">5</text><line x1=\"287.33\" y1=\"18\" x2=\"287.33\" y2=\"262\" stroke=\"#d1d5db\" stroke-width=\"1\"/><text x=\"287.33\" y=\"282\" text-anchor=\"middle\" font-size=\"15\" fill=\"#1f2937\">6</text><line x1=\"324.89\" y1=\"18\" x2=\"324.89\" y2=\"262\" stroke=\"#d1d5db\" stroke-width=\"1\"/><text x=\"324.89\" y=\"282\" text-anchor=\"middle\" font-size=\"15\" fill=\"#1f2937\">7</text><line x1=\"362.44\" y1=\"18\" x2=\"362.44\" y2=\"262\" stroke=\"#d1d5db\" stroke-width=\"1\"/><text x=\"362.44\" y=\"282\" text-anchor=\"middle\" font-size=\"15\" fill=\"#1f2937\">8</text><line x1=\"400\" y1=\"18\" x2=\"400\" y2=\"262\" stroke=\"#d1d5db\" stroke-width=\"1\"/><text x=\"400\" y=\"282\" text-anchor=\"middle\" font-size=\"15\" fill=\"#1f2937\">9</text><line x1=\"62\" y1=\"262\" x2=\"400\" y2=\"262\" stroke=\"#1f2937\" stroke-width=\"1.5\"/><line x1=\"62\" y1=\"18\" x2=\"62\" y2=\"262\" stroke=\"#1f2937\" stroke-width=\"1.5\"/><text x=\"231\" y=\"310\" text-anchor=\"middle\" font-size=\"16\" fill=\"#1f2937\">Hours studied</text><text x=\"18\" y=\"140\" text-anchor=\"middle\" font-size=\"16\" transform=\"rotate(-90 18 140)\" fill=\"#1f2937\">Quiz score</text><line x1=\"62\" y1=\"237.6\" x2=\"400\" y2=\"18\" stroke=\"#1d4ed8\" stroke-width=\"2\"/><circle cx=\"99.56\" cy=\"198.56\" r=\"4\" fill=\"#1f2937\"/><circle cx=\"137.11\" cy=\"208.32\" r=\"4\" fill=\"#1f2937\"/><circle cx=\"137.11\" cy=\"179.04\" r=\"4\" fill=\"#1f2937\"/><circle cx=\"174.67\" cy=\"174.16\" r=\"4\" fill=\"#1f2937\"/><circle cx=\"212.22\" cy=\"120.48\" r=\"4\" fill=\"#1f2937\"/><circle cx=\"212.22\" cy=\"154.64\" r=\"4\" fill=\"#1f2937\"/><circle cx=\"249.78\" cy=\"110.72\" r=\"4\" fill=\"#1f2937\"/><circle cx=\"287.33\" cy=\"96.08\" r=\"4\" fill=\"#1f2937\"/><circle cx=\"324.89\" cy=\"52.16\" r=\"4\" fill=\"#1f2937\"/><circle cx=\"362.44\" cy=\"52.16\" r=\"4\" fill=\"#1f2937\"/></svg>","options":[{"id":"A","label":"$70$"},{"id":"B","label":"$80$"},{"id":"C","label":"$85$"},{"id":"D","label":"$90$"}]}'::jsonb,42,'{"section_type":"math","sat_domain":"problem_solving_data_analysis","sat_official_domain":"problem_solving_data_analysis","sat_skill":"two_variable_data","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"psda-twovar-001","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('330df7f2-00d4-1c0c-f468-45d2eae1023c','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"The line passes through $(0, 55)$ and $(4, 75)$, so it rises 5 points per hour. At 6 hours it gives $55 + 5(6) = 85$. Choice C is correct. Choice A is incorrect. This is the predicted score for 3 hours of study, not 6. Choice B is incorrect. This is the predicted score for 5 hours of study, not 6. Choice D is incorrect. This is the predicted score for 7 hours of study."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('7b5d827a-1691-8c14-c295-7f5959f46327','7404498b-69de-518e-aeec-f2bb9a98409c','question_single_choice','{"prompt":"The scatterplot shows the age, in years, and the resale value, in hundreds of dollars, of $10$ used bicycles of the same model. Which statement best describes the relationship between age and resale value for these bicycles?","figure_svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 420 320\" width=\"420\" height=\"320\" font-family=\"Arial, Helvetica, sans-serif\" font-size=\"17\" role=\"img\"><title>Scatterplot of resale value versus age for 10 bicycles; points fall steadily from about 92 at age 1 to 40 at age 10.</title><rect x=\"0\" y=\"0\" width=\"420\" height=\"320\" fill=\"#ffffff\"/><line x1=\"62\" y1=\"262\" x2=\"400\" y2=\"262\" stroke=\"#d1d5db\" stroke-width=\"1\"/><text x=\"54\" y=\"267\" text-anchor=\"end\" font-size=\"15\" fill=\"#1f2937\">30</text><line x1=\"62\" y1=\"227.14\" x2=\"400\" y2=\"227.14\" stroke=\"#d1d5db\" stroke-width=\"1\"/><text x=\"54\" y=\"232.14\" text-anchor=\"end\" font-size=\"15\" fill=\"#1f2937\">40</text><line x1=\"62\" y1=\"192.29\" x2=\"400\" y2=\"192.29\" stroke=\"#d1d5db\" stroke-width=\"1\"/><text x=\"54\" y=\"197.29\" text-anchor=\"end\" font-size=\"15\" fill=\"#1f2937\">50</text><line x1=\"62\" y1=\"157.43\" x2=\"400\" y2=\"157.43\" stroke=\"#d1d5db\" stroke-width=\"1\"/><text x=\"54\" y=\"162.43\" text-anchor=\"end\" font-size=\"15\" fill=\"#1f2937\">60</text><line x1=\"62\" y1=\"122.57\" x2=\"400\" y2=\"122.57\" stroke=\"#d1d5db\" stroke-width=\"1\"/><text x=\"54\" y=\"127.57\" text-anchor=\"end\" font-size=\"15\" fill=\"#1f2937\">70</text><line x1=\"62\" y1=\"87.71\" x2=\"400\" y2=\"87.71\" stroke=\"#d1d5db\" stroke-width=\"1\"/><text x=\"54\" y=\"92.71\" text-anchor=\"end\" font-size=\"15\" fill=\"#1f2937\">80</text><line x1=\"62\" y1=\"52.86\" x2=\"400\" y2=\"52.86\" stroke=\"#d1d5db\" stroke-width=\"1\"/><text x=\"54\" y=\"57.86\" text-anchor=\"end\" font-size=\"15\" fill=\"#1f2937\">90</text><line x1=\"62\" y1=\"18\" x2=\"400\" y2=\"18\" stroke=\"#d1d5db\" stroke-width=\"1\"/><text x=\"54\" y=\"23\" text-anchor=\"end\" font-size=\"15\" fill=\"#1f2937\">100</text><line x1=\"62\" y1=\"18\" x2=\"62\" y2=\"262\" stroke=\"#d1d5db\" stroke-width=\"1\"/><text x=\"62\" y=\"282\" text-anchor=\"middle\" font-size=\"15\" fill=\"#1f2937\">0</text><line x1=\"92.73\" y1=\"18\" x2=\"92.73\" y2=\"262\" stroke=\"#d1d5db\" stroke-width=\"1\"/><text x=\"92.73\" y=\"282\" text-anchor=\"middle\" font-size=\"15\" fill=\"#1f2937\">1</text><line x1=\"123.45\" y1=\"18\" x2=\"123.45\" y2=\"262\" stroke=\"#d1d5db\" stroke-width=\"1\"/><text x=\"123.45\" y=\"282\" text-anchor=\"middle\" font-size=\"15\" fill=\"#1f2937\">2</text><line x1=\"154.18\" y1=\"18\" x2=\"154.18\" y2=\"262\" stroke=\"#d1d5db\" stroke-width=\"1\"/><text x=\"154.18\" y=\"282\" text-anchor=\"middle\" font-size=\"15\" fill=\"#1f2937\">3</text><line x1=\"184.91\" y1=\"18\" x2=\"184.91\" y2=\"262\" stroke=\"#d1d5db\" stroke-width=\"1\"/><text x=\"184.91\" y=\"282\" text-anchor=\"middle\" font-size=\"15\" fill=\"#1f2937\">4</text><line x1=\"215.64\" y1=\"18\" x2=\"215.64\" y2=\"262\" stroke=\"#d1d5db\" stroke-width=\"1\"/><text x=\"215.64\" y=\"282\" text-anchor=\"middle\" font-size=\"15\" fill=\"#1f2937\">5</text><line x1=\"246.36\" y1=\"18\" x2=\"246.36\" y2=\"262\" stroke=\"#d1d5db\" stroke-width=\"1\"/><text x=\"246.36\" y=\"282\" text-anchor=\"middle\" font-size=\"15\" fill=\"#1f2937\">6</text><line x1=\"277.09\" y1=\"18\" x2=\"277.09\" y2=\"262\" stroke=\"#d1d5db\" stroke-width=\"1\"/><text x=\"277.09\" y=\"282\" text-anchor=\"middle\" font-size=\"15\" fill=\"#1f2937\">7</text><line x1=\"307.82\" y1=\"18\" x2=\"307.82\" y2=\"262\" stroke=\"#d1d5db\" stroke-width=\"1\"/><text x=\"307.82\" y=\"282\" text-anchor=\"middle\" font-size=\"15\" fill=\"#1f2937\">8</text><line x1=\"338.55\" y1=\"18\" x2=\"338.55\" y2=\"262\" stroke=\"#d1d5db\" stroke-width=\"1\"/><text x=\"338.55\" y=\"282\" text-anchor=\"middle\" font-size=\"15\" fill=\"#1f2937\">9</text><line x1=\"369.27\" y1=\"18\" x2=\"369.27\" y2=\"262\" stroke=\"#d1d5db\" stroke-width=\"1\"/><text x=\"369.27\" y=\"282\" text-anchor=\"middle\" font-size=\"15\" fill=\"#1f2937\">10</text><line x1=\"400\" y1=\"18\" x2=\"400\" y2=\"262\" stroke=\"#d1d5db\" stroke-width=\"1\"/><text x=\"400\" y=\"282\" text-anchor=\"middle\" font-size=\"15\" fill=\"#1f2937\">11</text><line x1=\"62\" y1=\"262\" x2=\"400\" y2=\"262\" stroke=\"#1f2937\" stroke-width=\"1.5\"/><line x1=\"62\" y1=\"18\" x2=\"62\" y2=\"262\" stroke=\"#1f2937\" stroke-width=\"1.5\"/><text x=\"231\" y=\"310\" text-anchor=\"middle\" font-size=\"16\" fill=\"#1f2937\">Age (years)</text><text x=\"18\" y=\"140\" text-anchor=\"middle\" font-size=\"16\" transform=\"rotate(-90 18 140)\" fill=\"#1f2937\">Resale value (hundreds of dollars)</text><circle cx=\"92.73\" cy=\"45.89\" r=\"4\" fill=\"#1f2937\"/><circle cx=\"123.45\" cy=\"70.29\" r=\"4\" fill=\"#1f2937\"/><circle cx=\"154.18\" cy=\"77.26\" r=\"4\" fill=\"#1f2937\"/><circle cx=\"184.91\" cy=\"108.63\" r=\"4\" fill=\"#1f2937\"/><circle cx=\"215.64\" cy=\"122.57\" r=\"4\" fill=\"#1f2937\"/><circle cx=\"246.36\" cy=\"150.46\" r=\"4\" fill=\"#1f2937\"/><circle cx=\"277.09\" cy=\"157.43\" r=\"4\" fill=\"#1f2937\"/><circle cx=\"307.82\" cy=\"188.8\" r=\"4\" fill=\"#1f2937\"/><circle cx=\"338.55\" cy=\"202.74\" r=\"4\" fill=\"#1f2937\"/><circle cx=\"369.27\" cy=\"227.14\" r=\"4\" fill=\"#1f2937\"/></svg>","options":[{"id":"A","label":"There is no association between age and resale value."},{"id":"B","label":"There is a strong positive linear association."},{"id":"C","label":"There is a weak positive linear association."},{"id":"D","label":"There is a strong negative linear association."}]}'::jsonb,43,'{"section_type":"math","sat_domain":"problem_solving_data_analysis","sat_official_domain":"problem_solving_data_analysis","sat_skill":"two_variable_data","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"psda-twovar-002","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('7b5d827a-1691-8c14-c295-7f5959f46327','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"As age increases from left to right, resale value decreases, and the points lie close to a straight line. This is a strong negative linear association. Choice D is correct. Choice A is incorrect. The points follow a clear downward linear pattern. Choice B is incorrect. Resale value decreases as age increases, so the association is negative, not positive. Choice C is incorrect. The points fall from left to right and lie close to a line, so the association is strong and negative, not weak and positive."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('027de2c1-e8bf-e0a0-f5bc-458dadaf5ee3','7404498b-69de-518e-aeec-f2bb9a98409c','question_spr','{"prompt":"A botanist models the height $y$, in centimeters, of a seedling $x$ days after planting with the equation $y = 0.75x + 12$. According to the model, what is the height of the seedling, in centimeters, $20$ days after planting?"}'::jsonb,44,'{"section_type":"math","sat_domain":"problem_solving_data_analysis","sat_official_domain":"problem_solving_data_analysis","sat_skill":"two_variable_data","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"psda-twovar-003","answer_format":"spr"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('027de2c1-e8bf-e0a0-f5bc-458dadaf5ee3','{"accepted":["27"]}'::jsonb,'{"feedback":{"explanation":"Substitute $x = 20$: $y = 0.75(20) + 12 = 15 + 12 = 27$."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('3f67ec68-d803-576f-9e99-cf97c932b24e','7404498b-69de-518e-aeec-f2bb9a98409c','question_single_choice','{"prompt":"A phone plan''s monthly cost $y$, in dollars, is modeled by $y = 3.2x + 45$, where $x$ is the number of gigabytes of data used that month. What is the best interpretation of $3.2$ in this context?","options":[{"id":"A","label":"The cost increases by 3.20 dollars for each additional gigabyte of data used."},{"id":"B","label":"A customer can use 3.2 gigabytes for each dollar spent."},{"id":"C","label":"The plan costs 3.20 dollars per month before any data are used."},{"id":"D","label":"The total monthly cost is 3.20 dollars."}]}'::jsonb,45,'{"section_type":"math","sat_domain":"problem_solving_data_analysis","sat_official_domain":"problem_solving_data_analysis","sat_skill":"two_variable_data","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"psda-twovar-004","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('3f67ec68-d803-576f-9e99-cf97c932b24e','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"In the linear model $y = 3.2x + 45$, the coefficient of $x$ is the slope, which is the change in cost per gigabyte. Each additional gigabyte adds 3.20 dollars to the monthly cost. Choice A is correct. Choice B is incorrect. The units are reversed: 3.2 is dollars per gigabyte, not gigabytes per dollar. Choice C is incorrect. The cost when $x = 0$ is the constant term, 45 dollars, not 3.20 dollars. Choice D is incorrect. The total cost depends on $x$; 3.2 is the rate of change of the cost."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('8467da7d-45cd-2167-d292-65d23fcc14f0','7404498b-69de-518e-aeec-f2bb9a98409c','question_single_choice','{"prompt":"The table shows $5$ data points. A line of best fit for the data is $y = 2x + 10$. What is the residual for the data point where $x = 8$? (A residual is the actual $y$-value minus the $y$-value predicted by the line.)","table":{"headers":["x","y"],"rows":[["2","15"],["4","17"],["6","24"],["8","30"],["10","29"]]},"options":[{"id":"A","label":"$-4$"},{"id":"B","label":"$4$"},{"id":"C","label":"$26$"},{"id":"D","label":"$30$"}]}'::jsonb,46,'{"section_type":"math","sat_domain":"problem_solving_data_analysis","sat_official_domain":"problem_solving_data_analysis","sat_skill":"two_variable_data","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"psda-twovar-005","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('8467da7d-45cd-2167-d292-65d23fcc14f0','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"The line predicts $y = 2(8) + 10 = 26$ at $x = 8$. The actual value is 30, so the residual is $30 - 26 = 4$. Choice B is correct. Choice A is incorrect. This subtracts in the wrong order, giving predicted minus actual. Choice C is incorrect. This is the predicted $y$-value at $x = 8$, not the residual. Choice D is incorrect. This is the actual $y$-value at $x = 8$, not the residual."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('31ec8bd6-a284-50fb-7f20-6ba16631dc85','7404498b-69de-518e-aeec-f2bb9a98409c','question_single_choice','{"prompt":"The table shows the number of bacteria colonies $y$ counted in a dish $x$ days after the start of an experiment. Which equation models the data in the table?","table":{"headers":["x (days)","y (colonies)"],"rows":[["0","50"],["1","60"],["2","72"],["3","86.4"],["4","103.68"]]},"options":[{"id":"A","label":"$y = 50(1.2)^x$"},{"id":"B","label":"$y = 1.2(50)^x$"},{"id":"C","label":"$y = 50(0.2)^x$"},{"id":"D","label":"$y = 50 + 10x$"}]}'::jsonb,47,'{"section_type":"math","sat_domain":"problem_solving_data_analysis","sat_official_domain":"problem_solving_data_analysis","sat_skill":"two_variable_data","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"psda-twovar-006","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('31ec8bd6-a284-50fb-7f20-6ba16631dc85','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"Each value is $1.2$ times the previous one: $\\frac{60}{50} = \\frac{72}{60} = \\frac{86.4}{72} = 1.2$, and the value at $x = 0$ is 50. So $y = 50(1.2)^x$. Choice A is correct. Choice B is incorrect. This switches the initial value and the growth factor; it gives 1.2 at $x = 0$. Choice C is incorrect. This model decreases, but the data increase. A 20% increase corresponds to the factor 1.2, not 0.2. Choice D is incorrect. This linear model matches the first two values, but it predicts 70 at $x = 2$, not 72; the data increase by a constant factor, not a constant amount."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('7f6f1b28-3b89-0a35-1abf-ab7c05709ad5','7404498b-69de-518e-aeec-f2bb9a98409c','question_spr','{"prompt":"The table shows a linear relationship between $x$ and $y$. The relationship can be written as $y = ax + b$, where $a$ and $b$ are constants. What is the value of $b$?","table":{"headers":["x","y"],"rows":[["2","11"],["5","20"],["9","32"],["14","47"]]}}'::jsonb,48,'{"section_type":"math","sat_domain":"problem_solving_data_analysis","sat_official_domain":"problem_solving_data_analysis","sat_skill":"two_variable_data","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"psda-twovar-007","answer_format":"spr"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('7f6f1b28-3b89-0a35-1abf-ab7c05709ad5','{"accepted":["5"]}'::jsonb,'{"feedback":{"explanation":"The slope is $a = \\frac{20 - 11}{5 - 2} = 3$. Using $(2, 11)$: $11 = 3(2) + b$, so $b = 5$. The other points check: $3(9) + 5 = 32$ and $3(14) + 5 = 47$."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('e00cb2f5-43a3-e01b-155a-5906ade105ad','7404498b-69de-518e-aeec-f2bb9a98409c','question_single_choice','{"prompt":"The scatterplot shows $10$ data points and the line $y = 1.5x + 4$, which is a line of best fit for the data. For how many of the data points is the actual $y$-value greater than the $y$-value predicted by the line?","figure_svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 420 320\" width=\"420\" height=\"320\" font-family=\"Arial, Helvetica, sans-serif\" font-size=\"17\" role=\"img\"><title>Scatterplot of 10 points with the line y = 1.5x + 4; points alternate above and below the line, with 6 above.</title><rect x=\"0\" y=\"0\" width=\"420\" height=\"320\" fill=\"#ffffff\"/><line x1=\"62\" y1=\"262\" x2=\"400\" y2=\"262\" stroke=\"#d1d5db\" stroke-width=\"1\"/><text x=\"54\" y=\"267\" text-anchor=\"end\" font-size=\"15\" fill=\"#1f2937\">0</text><line x1=\"62\" y1=\"221.33\" x2=\"400\" y2=\"221.33\" stroke=\"#d1d5db\" stroke-width=\"1\"/><text x=\"54\" y=\"226.33\" text-anchor=\"end\" font-size=\"15\" fill=\"#1f2937\">4</text><line x1=\"62\" y1=\"180.67\" x2=\"400\" y2=\"180.67\" stroke=\"#d1d5db\" stroke-width=\"1\"/><text x=\"54\" y=\"185.67\" text-anchor=\"end\" font-size=\"15\" fill=\"#1f2937\">8</text><line x1=\"62\" y1=\"140\" x2=\"400\" y2=\"140\" stroke=\"#d1d5db\" stroke-width=\"1\"/><text x=\"54\" y=\"145\" text-anchor=\"end\" font-size=\"15\" fill=\"#1f2937\">12</text><line x1=\"62\" y1=\"99.33\" x2=\"400\" y2=\"99.33\" stroke=\"#d1d5db\" stroke-width=\"1\"/><text x=\"54\" y=\"104.33\" text-anchor=\"end\" font-size=\"15\" fill=\"#1f2937\">16</text><line x1=\"62\" y1=\"58.67\" x2=\"400\" y2=\"58.67\" stroke=\"#d1d5db\" stroke-width=\"1\"/><text x=\"54\" y=\"63.67\" text-anchor=\"end\" font-size=\"15\" fill=\"#1f2937\">20</text><line x1=\"62\" y1=\"18\" x2=\"400\" y2=\"18\" stroke=\"#d1d5db\" stroke-width=\"1\"/><text x=\"54\" y=\"23\" text-anchor=\"end\" font-size=\"15\" fill=\"#1f2937\">24</text><line x1=\"62\" y1=\"18\" x2=\"62\" y2=\"262\" stroke=\"#d1d5db\" stroke-width=\"1\"/><text x=\"62\" y=\"282\" text-anchor=\"middle\" font-size=\"15\" fill=\"#1f2937\">0</text><line x1=\"92.73\" y1=\"18\" x2=\"92.73\" y2=\"262\" stroke=\"#d1d5db\" stroke-width=\"1\"/><text x=\"92.73\" y=\"282\" text-anchor=\"middle\" font-size=\"15\" fill=\"#1f2937\">1</text><line x1=\"123.45\" y1=\"18\" x2=\"123.45\" y2=\"262\" stroke=\"#d1d5db\" stroke-width=\"1\"/><text x=\"123.45\" y=\"282\" text-anchor=\"middle\" font-size=\"15\" fill=\"#1f2937\">2</text><line x1=\"154.18\" y1=\"18\" x2=\"154.18\" y2=\"262\" stroke=\"#d1d5db\" stroke-width=\"1\"/><text x=\"154.18\" y=\"282\" text-anchor=\"middle\" font-size=\"15\" fill=\"#1f2937\">3</text><line x1=\"184.91\" y1=\"18\" x2=\"184.91\" y2=\"262\" stroke=\"#d1d5db\" stroke-width=\"1\"/><text x=\"184.91\" y=\"282\" text-anchor=\"middle\" font-size=\"15\" fill=\"#1f2937\">4</text><line x1=\"215.64\" y1=\"18\" x2=\"215.64\" y2=\"262\" stroke=\"#d1d5db\" stroke-width=\"1\"/><text x=\"215.64\" y=\"282\" text-anchor=\"middle\" font-size=\"15\" fill=\"#1f2937\">5</text><line x1=\"246.36\" y1=\"18\" x2=\"246.36\" y2=\"262\" stroke=\"#d1d5db\" stroke-width=\"1\"/><text x=\"246.36\" y=\"282\" text-anchor=\"middle\" font-size=\"15\" fill=\"#1f2937\">6</text><line x1=\"277.09\" y1=\"18\" x2=\"277.09\" y2=\"262\" stroke=\"#d1d5db\" stroke-width=\"1\"/><text x=\"277.09\" y=\"282\" text-anchor=\"middle\" font-size=\"15\" fill=\"#1f2937\">7</text><line x1=\"307.82\" y1=\"18\" x2=\"307.82\" y2=\"262\" stroke=\"#d1d5db\" stroke-width=\"1\"/><text x=\"307.82\" y=\"282\" text-anchor=\"middle\" font-size=\"15\" fill=\"#1f2937\">8</text><line x1=\"338.55\" y1=\"18\" x2=\"338.55\" y2=\"262\" stroke=\"#d1d5db\" stroke-width=\"1\"/><text x=\"338.55\" y=\"282\" text-anchor=\"middle\" font-size=\"15\" fill=\"#1f2937\">9</text><line x1=\"369.27\" y1=\"18\" x2=\"369.27\" y2=\"262\" stroke=\"#d1d5db\" stroke-width=\"1\"/><text x=\"369.27\" y=\"282\" text-anchor=\"middle\" font-size=\"15\" fill=\"#1f2937\">10</text><line x1=\"400\" y1=\"18\" x2=\"400\" y2=\"262\" stroke=\"#d1d5db\" stroke-width=\"1\"/><text x=\"400\" y=\"282\" text-anchor=\"middle\" font-size=\"15\" fill=\"#1f2937\">11</text><line x1=\"62\" y1=\"262\" x2=\"400\" y2=\"262\" stroke=\"#1f2937\" stroke-width=\"1.5\"/><line x1=\"62\" y1=\"18\" x2=\"62\" y2=\"262\" stroke=\"#1f2937\" stroke-width=\"1.5\"/><text x=\"231\" y=\"310\" text-anchor=\"middle\" font-size=\"16\" fill=\"#1f2937\">x</text><text x=\"18\" y=\"140\" text-anchor=\"middle\" font-size=\"16\" transform=\"rotate(-90 18 140)\" fill=\"#1f2937\">y</text><line x1=\"62\" y1=\"221.33\" x2=\"400\" y2=\"53.58\" stroke=\"#1d4ed8\" stroke-width=\"2\"/><circle cx=\"92.73\" cy=\"190.83\" r=\"4\" fill=\"#1f2937\"/><circle cx=\"123.45\" cy=\"201\" r=\"4\" fill=\"#1f2937\"/><circle cx=\"154.18\" cy=\"160.33\" r=\"4\" fill=\"#1f2937\"/><circle cx=\"184.91\" cy=\"170.5\" r=\"4\" fill=\"#1f2937\"/><circle cx=\"215.64\" cy=\"129.83\" r=\"4\" fill=\"#1f2937\"/><circle cx=\"246.36\" cy=\"140\" r=\"4\" fill=\"#1f2937\"/><circle cx=\"277.09\" cy=\"99.33\" r=\"4\" fill=\"#1f2937\"/><circle cx=\"307.82\" cy=\"109.5\" r=\"4\" fill=\"#1f2937\"/><circle cx=\"338.55\" cy=\"68.83\" r=\"4\" fill=\"#1f2937\"/><circle cx=\"369.27\" cy=\"48.5\" r=\"4\" fill=\"#1f2937\"/></svg>","options":[{"id":"A","label":"$4$"},{"id":"B","label":"$5$"},{"id":"C","label":"$6$"},{"id":"D","label":"$10$"}]}'::jsonb,49,'{"section_type":"math","sat_domain":"problem_solving_data_analysis","sat_official_domain":"problem_solving_data_analysis","sat_skill":"two_variable_data","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"psda-twovar-008","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('e00cb2f5-43a3-e01b-155a-5906ade105ad','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"A point''s actual value is greater than the predicted value when the point lies above the line. Comparing each point with $1.5x + 4$: the points at $x = 1, 3, 5, 7, 9, 10$ lie above the line and the points at $x = 2, 4, 6, 8$ lie below it, so 6 points have actual values greater than predicted. Choice C is correct. Choice A is incorrect. This is the number of points below the line, where the actual value is less than the predicted value. Choice B is incorrect. This assumes a line of best fit always has exactly half the points above it; here 6 points lie above the line. Choice D is incorrect. This counts every data point."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('d758ba94-7ce3-77c8-f6ad-64e5a7f5cc3b','7404498b-69de-518e-aeec-f2bb9a98409c','question_single_choice','{"prompt":"The table shows the estimated number of fish in a lake every $2$ years. Which type of model best fits the data?","table":{"headers":["Years since 2010","Estimated number of fish"],"rows":[["0","8,000"],["2","7,200"],["4","6,480"],["6","5,832"]]},"options":[{"id":"A","label":"Increasing linear"},{"id":"B","label":"Decreasing linear"},{"id":"C","label":"Increasing exponential"},{"id":"D","label":"Decreasing exponential"}]}'::jsonb,50,'{"section_type":"math","sat_domain":"problem_solving_data_analysis","sat_official_domain":"problem_solving_data_analysis","sat_skill":"two_variable_data","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"psda-twovar-009","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('d758ba94-7ce3-77c8-f6ad-64e5a7f5cc3b','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"Each value is $0.9$ times the previous value: $\\frac{7{,}200}{8{,}000} = \\frac{6{,}480}{7{,}200} = \\frac{5{,}832}{6{,}480} = 0.9$. A constant factor less than 1 gives a decreasing exponential model. Choice D is correct. Choice A is incorrect. The number of fish decreases over time. Choice B is incorrect. The differences between consecutive values (800, 720, 648) are not constant, so a linear model does not fit exactly. Choice C is incorrect. The values are multiplied by a constant factor, but the factor is 0.9, which is less than 1, so the model is decreasing."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('758ef659-6c84-2eb0-800d-84e00148e904','7404498b-69de-518e-aeec-f2bb9a98409c','question_single_choice','{"prompt":"A data analyst models the value $V$, in dollars, of a piece of equipment $t$ years after it was purchased with the equation $V = 2{,}400(0.85)^{\\frac{t}{2}}$. According to the model, the value of the equipment decreases by approximately what percent each year?","options":[{"id":"A","label":"$7.5\\%$"},{"id":"B","label":"$7.8\\%$"},{"id":"C","label":"$15\\%$"},{"id":"D","label":"$30\\%$"}]}'::jsonb,51,'{"section_type":"math","sat_domain":"problem_solving_data_analysis","sat_official_domain":"problem_solving_data_analysis","sat_skill":"two_variable_data","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"psda-twovar-010","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('758ef659-6c84-2eb0-800d-84e00148e904','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"Rewrite the model as $V = 2{,}400\\left(0.85^{\\frac{1}{2}}\\right)^t$. Since $0.85^{\\frac{1}{2}} \\approx 0.922$, the value is multiplied by about 0.922 each year, a decrease of about $1 - 0.922 = 0.078$, or $7.8\\%$. Choice B is correct. Choice A is incorrect. This halves the 15% decrease, but a decrease that compounds over 2 years cannot be split evenly by halving. Choice C is incorrect. This is the percent decrease every 2 years, not every year. Choice D is incorrect. This doubles the 15% instead of finding the yearly factor $0.85^{\\frac{1}{2}}$."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('26cdef1f-27bf-ffdb-1866-e7f7c3353897','7404498b-69de-518e-aeec-f2bb9a98409c','question_spr','{"prompt":"A linear model $f$ and an exponential model $g$ are both fit to the same two data points, $(0, 64)$ and $(2, 144)$. Based on the models, how much greater is $g(6)$ than $f(6)$?"}'::jsonb,52,'{"section_type":"math","sat_domain":"problem_solving_data_analysis","sat_official_domain":"problem_solving_data_analysis","sat_skill":"two_variable_data","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"psda-twovar-011","answer_format":"spr"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('26cdef1f-27bf-ffdb-1866-e7f7c3353897','{"accepted":["425"]}'::jsonb,'{"feedback":{"explanation":"The linear model has slope $\\frac{144 - 64}{2} = 40$, so $f(x) = 64 + 40x$ and $f(6) = 304$. The exponential model is $g(x) = 64b^x$ with $64b^2 = 144$, so $b^2 = \\frac{9}{4}$ and $b = 1.5$. Then $g(6) = 64(1.5)^6 = 729$. The difference is $729 - 304 = 425$."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('1fe914c4-0a57-a3eb-31cb-7222afe46fb8','7404498b-69de-518e-aeec-f2bb9a98409c','question_single_choice','{"prompt":"The scatterplot shows the relationship between two variables, $x$ and $y$. Which of the following equations best models the data?","figure_svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 420 320\" width=\"420\" height=\"320\" font-family=\"Arial, Helvetica, sans-serif\" font-size=\"17\" role=\"img\"><title>Scatterplot of 10 points rising from about 8 at x = 1 to a peak near 20 at x = 6, then falling to about 13 at x = 10.</title><rect x=\"0\" y=\"0\" width=\"420\" height=\"320\" fill=\"#ffffff\"/><line x1=\"62\" y1=\"262\" x2=\"400\" y2=\"262\" stroke=\"#d1d5db\" stroke-width=\"1\"/><text x=\"54\" y=\"267\" text-anchor=\"end\" font-size=\"15\" fill=\"#1f2937\">0</text><line x1=\"62\" y1=\"221.33\" x2=\"400\" y2=\"221.33\" stroke=\"#d1d5db\" stroke-width=\"1\"/><text x=\"54\" y=\"226.33\" text-anchor=\"end\" font-size=\"15\" fill=\"#1f2937\">4</text><line x1=\"62\" y1=\"180.67\" x2=\"400\" y2=\"180.67\" stroke=\"#d1d5db\" stroke-width=\"1\"/><text x=\"54\" y=\"185.67\" text-anchor=\"end\" font-size=\"15\" fill=\"#1f2937\">8</text><line x1=\"62\" y1=\"140\" x2=\"400\" y2=\"140\" stroke=\"#d1d5db\" stroke-width=\"1\"/><text x=\"54\" y=\"145\" text-anchor=\"end\" font-size=\"15\" fill=\"#1f2937\">12</text><line x1=\"62\" y1=\"99.33\" x2=\"400\" y2=\"99.33\" stroke=\"#d1d5db\" stroke-width=\"1\"/><text x=\"54\" y=\"104.33\" text-anchor=\"end\" font-size=\"15\" fill=\"#1f2937\">16</text><line x1=\"62\" y1=\"58.67\" x2=\"400\" y2=\"58.67\" stroke=\"#d1d5db\" stroke-width=\"1\"/><text x=\"54\" y=\"63.67\" text-anchor=\"end\" font-size=\"15\" fill=\"#1f2937\">20</text><line x1=\"62\" y1=\"18\" x2=\"400\" y2=\"18\" stroke=\"#d1d5db\" stroke-width=\"1\"/><text x=\"54\" y=\"23\" text-anchor=\"end\" font-size=\"15\" fill=\"#1f2937\">24</text><line x1=\"62\" y1=\"18\" x2=\"62\" y2=\"262\" stroke=\"#d1d5db\" stroke-width=\"1\"/><text x=\"62\" y=\"282\" text-anchor=\"middle\" font-size=\"15\" fill=\"#1f2937\">0</text><line x1=\"92.73\" y1=\"18\" x2=\"92.73\" y2=\"262\" stroke=\"#d1d5db\" stroke-width=\"1\"/><text x=\"92.73\" y=\"282\" text-anchor=\"middle\" font-size=\"15\" fill=\"#1f2937\">1</text><line x1=\"123.45\" y1=\"18\" x2=\"123.45\" y2=\"262\" stroke=\"#d1d5db\" stroke-width=\"1\"/><text x=\"123.45\" y=\"282\" text-anchor=\"middle\" font-size=\"15\" fill=\"#1f2937\">2</text><line x1=\"154.18\" y1=\"18\" x2=\"154.18\" y2=\"262\" stroke=\"#d1d5db\" stroke-width=\"1\"/><text x=\"154.18\" y=\"282\" text-anchor=\"middle\" font-size=\"15\" fill=\"#1f2937\">3</text><line x1=\"184.91\" y1=\"18\" x2=\"184.91\" y2=\"262\" stroke=\"#d1d5db\" stroke-width=\"1\"/><text x=\"184.91\" y=\"282\" text-anchor=\"middle\" font-size=\"15\" fill=\"#1f2937\">4</text><line x1=\"215.64\" y1=\"18\" x2=\"215.64\" y2=\"262\" stroke=\"#d1d5db\" stroke-width=\"1\"/><text x=\"215.64\" y=\"282\" text-anchor=\"middle\" font-size=\"15\" fill=\"#1f2937\">5</text><line x1=\"246.36\" y1=\"18\" x2=\"246.36\" y2=\"262\" stroke=\"#d1d5db\" stroke-width=\"1\"/><text x=\"246.36\" y=\"282\" text-anchor=\"middle\" font-size=\"15\" fill=\"#1f2937\">6</text><line x1=\"277.09\" y1=\"18\" x2=\"277.09\" y2=\"262\" stroke=\"#d1d5db\" stroke-width=\"1\"/><text x=\"277.09\" y=\"282\" text-anchor=\"middle\" font-size=\"15\" fill=\"#1f2937\">7</text><line x1=\"307.82\" y1=\"18\" x2=\"307.82\" y2=\"262\" stroke=\"#d1d5db\" stroke-width=\"1\"/><text x=\"307.82\" y=\"282\" text-anchor=\"middle\" font-size=\"15\" fill=\"#1f2937\">8</text><line x1=\"338.55\" y1=\"18\" x2=\"338.55\" y2=\"262\" stroke=\"#d1d5db\" stroke-width=\"1\"/><text x=\"338.55\" y=\"282\" text-anchor=\"middle\" font-size=\"15\" fill=\"#1f2937\">9</text><line x1=\"369.27\" y1=\"18\" x2=\"369.27\" y2=\"262\" stroke=\"#d1d5db\" stroke-width=\"1\"/><text x=\"369.27\" y=\"282\" text-anchor=\"middle\" font-size=\"15\" fill=\"#1f2937\">10</text><line x1=\"400\" y1=\"18\" x2=\"400\" y2=\"262\" stroke=\"#d1d5db\" stroke-width=\"1\"/><text x=\"400\" y=\"282\" text-anchor=\"middle\" font-size=\"15\" fill=\"#1f2937\">11</text><line x1=\"62\" y1=\"262\" x2=\"400\" y2=\"262\" stroke=\"#1f2937\" stroke-width=\"1.5\"/><line x1=\"62\" y1=\"18\" x2=\"62\" y2=\"262\" stroke=\"#1f2937\" stroke-width=\"1.5\"/><text x=\"231\" y=\"310\" text-anchor=\"middle\" font-size=\"16\" fill=\"#1f2937\">x</text><text x=\"18\" y=\"140\" text-anchor=\"middle\" font-size=\"16\" transform=\"rotate(-90 18 140)\" fill=\"#1f2937\">y</text><circle cx=\"92.73\" cy=\"175.58\" r=\"4\" fill=\"#1f2937\"/><circle cx=\"123.45\" cy=\"150.17\" r=\"4\" fill=\"#1f2937\"/><circle cx=\"154.18\" cy=\"104.42\" r=\"4\" fill=\"#1f2937\"/><circle cx=\"184.91\" cy=\"68.83\" r=\"4\" fill=\"#1f2937\"/><circle cx=\"215.64\" cy=\"73.92\" r=\"4\" fill=\"#1f2937\"/><circle cx=\"246.36\" cy=\"58.67\" r=\"4\" fill=\"#1f2937\"/><circle cx=\"277.09\" cy=\"53.58\" r=\"4\" fill=\"#1f2937\"/><circle cx=\"307.82\" cy=\"89.17\" r=\"4\" fill=\"#1f2937\"/><circle cx=\"338.55\" cy=\"104.42\" r=\"4\" fill=\"#1f2937\"/><circle cx=\"369.27\" cy=\"129.83\" r=\"4\" fill=\"#1f2937\"/></svg>","options":[{"id":"A","label":"$y = -0.5x^2 + 4x + 12$"},{"id":"B","label":"$y = -2x + 30$"},{"id":"C","label":"$y = 0.5x^2 - 6x + 38$"},{"id":"D","label":"$y = -0.5x^2 + 6x + 2$"}]}'::jsonb,53,'{"section_type":"math","sat_domain":"problem_solving_data_analysis","sat_official_domain":"problem_solving_data_analysis","sat_skill":"two_variable_data","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"psda-twovar-012","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('1fe914c4-0a57-a3eb-31cb-7222afe46fb8','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"The data rise to a maximum of about 20 near $x = 6$ and then fall, so the model should be a downward-opening parabola with vertex near $(6, 20)$. The equation $y = -0.5x^2 + 6x + 2$ has vertex $x = -\\frac{6}{2(-0.5)} = 6$ and $y = -18 + 36 + 2 = 20$, and it gives $y \\approx 7.5$ at $x = 1$ and $y \\approx 12$ at $x = 10$, matching the plotted points. Choice D is correct. Choice A is incorrect. This parabola opens downward but has its maximum at $x = 4$, while the data reach their greatest values near $x = 6$. Choice B is incorrect. This linear model decreases throughout, but the data increase and then decrease. Choice C is incorrect. This parabola has its vertex at $(6, 20)$ but opens upward, so it has a minimum, not a maximum, there."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('c0068e8c-7947-36ad-7fbd-74b25020525e','7404498b-69de-518e-aeec-f2bb9a98409c','question_spr','{"prompt":"The table shows three values of an exponential function that models a set of data. The function can be written as $y = a(b)^x$, where $a$ and $b$ are positive constants. What is the value of $a + b$?","table":{"headers":["x","y"],"rows":[["1","24"],["2","36"],["3","54"]]}}'::jsonb,54,'{"section_type":"math","sat_domain":"problem_solving_data_analysis","sat_official_domain":"problem_solving_data_analysis","sat_skill":"two_variable_data","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"psda-twovar-013","answer_format":"spr"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('c0068e8c-7947-36ad-7fbd-74b25020525e','{"accepted":["35/2","17.5"]}'::jsonb,'{"feedback":{"explanation":"The ratio of consecutive $y$-values is $\\frac{36}{24} = \\frac{54}{36} = 1.5$, so $b = 1.5$. Then $24 = a(1.5)^1$, so $a = 16$. Therefore $a + b = 16 + 1.5 = 17.5$."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('805cc9b3-1504-d152-4bea-3af255194df5','7404498b-69de-518e-aeec-f2bb9a98409c','question_single_choice','{"prompt":"A bag contains $5$ red tiles, $7$ blue tiles, and $8$ green tiles. One tile is chosen at random. What is the probability that the tile is blue?","options":[{"id":"A","label":"$\\frac{1}{3}$"},{"id":"B","label":"$\\frac{7}{20}$"},{"id":"C","label":"$\\frac{7}{13}$"},{"id":"D","label":"$\\frac{13}{20}$"}]}'::jsonb,55,'{"section_type":"math","sat_domain":"problem_solving_data_analysis","sat_official_domain":"problem_solving_data_analysis","sat_skill":"probability_and_conditional_probability","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"psda-prob-001","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('805cc9b3-1504-d152-4bea-3af255194df5','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"There are $5 + 7 + 8 = 20$ tiles, and 7 are blue, so the probability is $\\frac{7}{20}$. Choice B is correct. Choice A is incorrect. This assumes each color is equally likely, but the colors have different numbers of tiles. Choice C is incorrect. This divides the number of blue tiles by the number of tiles that are not blue, which gives odds rather than a probability. Choice D is incorrect. This is the probability that the tile is not blue."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('50c6a9c5-63f1-a313-6cc5-4fe00cb8db0a','7404498b-69de-518e-aeec-f2bb9a98409c','question_single_choice','{"prompt":"The table shows the lunch choices of $160$ students in grades 10 and 11. If one of these students is selected at random, what is the probability that the student is in grade 11 and brings a packed lunch?","table":{"headers":["","Hot lunch","Packed lunch","Total"],"rows":[["Grade 10","42","28","70"],["Grade 11","36","54","90"],["Total","78","82","160"]]},"options":[{"id":"A","label":"$\\frac{27}{80}$"},{"id":"B","label":"$\\frac{9}{16}$"},{"id":"C","label":"$\\frac{3}{5}$"},{"id":"D","label":"$\\frac{27}{41}$"}]}'::jsonb,56,'{"section_type":"math","sat_domain":"problem_solving_data_analysis","sat_official_domain":"problem_solving_data_analysis","sat_skill":"probability_and_conditional_probability","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"psda-prob-002","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('50c6a9c5-63f1-a313-6cc5-4fe00cb8db0a','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"There are 54 grade 11 students who bring a packed lunch out of 160 students in all, so the probability is $\\frac{54}{160} = \\frac{27}{80}$. Choice A is correct. Choice B is incorrect. This is the probability that the student is in grade 11, regardless of lunch choice. Choice C is incorrect. This is the probability that a grade 11 student brings a packed lunch; it divides by the grade 11 total instead of the total of all students. Choice D is incorrect. This is the probability that a student who brings a packed lunch is in grade 11."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('bce996d5-3b46-f697-74d6-1dd0e56fddc4','7404498b-69de-518e-aeec-f2bb9a98409c','question_spr','{"prompt":"An integer from $1$ through $40$, inclusive, is chosen at random. What is the probability that the integer is a multiple of $6$?"}'::jsonb,57,'{"section_type":"math","sat_domain":"problem_solving_data_analysis","sat_official_domain":"problem_solving_data_analysis","sat_skill":"probability_and_conditional_probability","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"psda-prob-003","answer_format":"spr"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('bce996d5-3b46-f697-74d6-1dd0e56fddc4','{"accepted":["3/20",".15","0.15"]}'::jsonb,'{"feedback":{"explanation":"The multiples of 6 from 1 through 40 are 6, 12, 18, 24, 30, and 36, so there are 6 of them. The probability is $\\frac{6}{40} = \\frac{3}{20}$, or 0.15."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('9a8615ba-beef-c68c-bf8f-9543747c0b42','7404498b-69de-518e-aeec-f2bb9a98409c','question_single_choice','{"prompt":"A spinner is divided into $8$ equal sections numbered $1$ through $8$. If the spinner is spun once, what is the probability that it lands on a number greater than $5$?","options":[{"id":"A","label":"$\\frac{1}{8}$"},{"id":"B","label":"$\\frac{3}{8}$"},{"id":"C","label":"$\\frac{1}{2}$"},{"id":"D","label":"$\\frac{5}{8}$"}]}'::jsonb,58,'{"section_type":"math","sat_domain":"problem_solving_data_analysis","sat_official_domain":"problem_solving_data_analysis","sat_skill":"probability_and_conditional_probability","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"psda-prob-004","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('9a8615ba-beef-c68c-bf8f-9543747c0b42','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"The numbers greater than 5 are 6, 7, and 8, so the probability is $\\frac{3}{8}$. Choice B is correct. Choice A is incorrect. This is the probability of landing on one particular number. Choice C is incorrect. This counts the numbers greater than 4, not greater than 5. Choice D is incorrect. This is the probability of landing on a number less than or equal to 5."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('054f1ffd-0e66-b433-7743-3360e3cbada1','7404498b-69de-518e-aeec-f2bb9a98409c','question_single_choice','{"prompt":"The table summarizes a survey of $200$ adults about the type of home they live in and whether they own a pet. If a person who owns a pet is selected at random from this group, what is the probability that the person lives in a house?","table":{"headers":["","Owns a pet","Does not own a pet","Total"],"rows":[["Apartment","36","54","90"],["House","77","33","110"],["Total","113","87","200"]]},"options":[{"id":"A","label":"$\\frac{77}{200}$"},{"id":"B","label":"$\\frac{113}{200}$"},{"id":"C","label":"$\\frac{77}{113}$"},{"id":"D","label":"$\\frac{7}{10}$"}]}'::jsonb,59,'{"section_type":"math","sat_domain":"problem_solving_data_analysis","sat_official_domain":"problem_solving_data_analysis","sat_skill":"probability_and_conditional_probability","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"psda-prob-005","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('054f1ffd-0e66-b433-7743-3360e3cbada1','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"The condition limits the group to the $36 + 77 = 113$ pet owners. Of these, 77 live in a house, so the probability is $\\frac{77}{113}$. Choice C is correct. Choice A is incorrect. This is the probability that a randomly selected adult from the whole group lives in a house and owns a pet. Choice B is incorrect. This is the probability that a randomly selected adult owns a pet. Choice D is incorrect. This is the probability that a person who lives in a house owns a pet; the condition is reversed."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('e711c09f-fb87-c78e-39e9-42ba095b51d8','7404498b-69de-518e-aeec-f2bb9a98409c','question_spr','{"prompt":"The table shows the results of an experiment with $120$ plants that received either fertilizer A or fertilizer B. If a plant that grew tall is selected at random, what is the probability that it received fertilizer A?","table":{"headers":["","Grew tall","Stayed short","Total"],"rows":[["Fertilizer A","45","15","60"],["Fertilizer B","30","30","60"],["Total","75","45","120"]]}}'::jsonb,60,'{"section_type":"math","sat_domain":"problem_solving_data_analysis","sat_official_domain":"problem_solving_data_analysis","sat_skill":"probability_and_conditional_probability","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"psda-prob-006","answer_format":"spr"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('e711c09f-fb87-c78e-39e9-42ba095b51d8','{"accepted":["3/5",".6","0.6"]}'::jsonb,'{"feedback":{"explanation":"There are $45 + 30 = 75$ tall plants, and 45 of them received fertilizer A. The probability is $\\frac{45}{75} = \\frac{3}{5}$, or 0.6."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('0f8c70ae-4040-f4bc-636e-990b4774ff33','7404498b-69de-518e-aeec-f2bb9a98409c','question_single_choice','{"prompt":"Two fair six-sided dice, each with faces numbered $1$ through $6$, are rolled. What is the probability that the sum of the two numbers rolled is $8$?","options":[{"id":"A","label":"$\\frac{1}{11}$"},{"id":"B","label":"$\\frac{5}{36}$"},{"id":"C","label":"$\\frac{1}{6}$"},{"id":"D","label":"$\\frac{2}{9}$"}]}'::jsonb,61,'{"section_type":"math","sat_domain":"problem_solving_data_analysis","sat_official_domain":"problem_solving_data_analysis","sat_skill":"probability_and_conditional_probability","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"psda-prob-007","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('0f8c70ae-4040-f4bc-636e-990b4774ff33','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"There are $6 \\times 6 = 36$ equally likely outcomes. A sum of 8 occurs for $(2, 6), (3, 5), (4, 4), (5, 3), (6, 2)$, which is 5 outcomes, so the probability is $\\frac{5}{36}$. Choice B is correct. Choice A is incorrect. This treats the 11 possible sums, 2 through 12, as equally likely. Choice C is incorrect. This is the probability of the most likely sum, 7, which can occur in 6 ways. Choice D is incorrect. This uses the sum itself as the number of favorable outcomes."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('1da5923a-9bff-fb20-7831-8be25cd3c22b','7404498b-69de-518e-aeec-f2bb9a98409c','question_single_choice','{"prompt":"Events $A$ and $B$ are independent. The probability of $A$ is $0.3$, and the probability of $B$ is $0.5$. What is the probability that at least one of the two events occurs?","options":[{"id":"A","label":"$0.15$"},{"id":"B","label":"$0.35$"},{"id":"C","label":"$0.65$"},{"id":"D","label":"$0.8$"}]}'::jsonb,62,'{"section_type":"math","sat_domain":"problem_solving_data_analysis","sat_official_domain":"problem_solving_data_analysis","sat_skill":"probability_and_conditional_probability","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"psda-prob-008","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('1da5923a-9bff-fb20-7831-8be25cd3c22b','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"The probability that neither occurs is $(1 - 0.3)(1 - 0.5) = 0.35$. So the probability that at least one occurs is $1 - 0.35 = 0.65$. Choice C is correct. Choice A is incorrect. This is the probability that both events occur. Choice B is incorrect. This is the probability that neither event occurs. Choice D is incorrect. This adds the probabilities and counts the outcomes where both events occur twice."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('611fb866-fa85-f9cb-1e49-2470e8713304','7404498b-69de-518e-aeec-f2bb9a98409c','question_spr','{"prompt":"A box contains $24$ chips, each red or blue. The probability of selecting a blue chip at random is $\\frac{3}{8}$. How many red chips must be added to the box so that the probability of selecting a blue chip at random becomes $\\frac{1}{4}$?"}'::jsonb,63,'{"section_type":"math","sat_domain":"problem_solving_data_analysis","sat_official_domain":"problem_solving_data_analysis","sat_skill":"probability_and_conditional_probability","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"psda-prob-009","answer_format":"spr"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('611fb866-fa85-f9cb-1e49-2470e8713304','{"accepted":["12"]}'::jsonb,'{"feedback":{"explanation":"There are $\\frac{3}{8} \\times 24 = 9$ blue chips. After adding $r$ red chips, $\\frac{9}{24 + r} = \\frac{1}{4}$, so $24 + r = 36$ and $r = 12$."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('746a26c1-9059-a5e4-a445-571e77e65dfe','7404498b-69de-518e-aeec-f2bb9a98409c','question_single_choice','{"prompt":"A drawer contains $4$ black socks and $6$ white socks. Two socks are selected at random without replacement. What is the probability that the two socks are the same color?","options":[{"id":"A","label":"$\\frac{2}{15}$"},{"id":"B","label":"$\\frac{1}{3}$"},{"id":"C","label":"$\\frac{7}{15}$"},{"id":"D","label":"$\\frac{13}{25}$"}]}'::jsonb,64,'{"section_type":"math","sat_domain":"problem_solving_data_analysis","sat_official_domain":"problem_solving_data_analysis","sat_skill":"probability_and_conditional_probability","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"psda-prob-010","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('746a26c1-9059-a5e4-a445-571e77e65dfe','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"The probability that both are black is $\\frac{4}{10} \\cdot \\frac{3}{9} = \\frac{12}{90}$, and the probability that both are white is $\\frac{6}{10} \\cdot \\frac{5}{9} = \\frac{30}{90}$. The total is $\\frac{42}{90} = \\frac{7}{15}$. Choice C is correct. Choice A is incorrect. This is the probability that both socks are black; it leaves out the case where both are white. Choice B is incorrect. This is the probability that both socks are white; it leaves out the case where both are black. Choice D is incorrect. This treats the selections as made with replacement, using $\\frac{4}{10} \\cdot \\frac{4}{10} + \\frac{6}{10} \\cdot \\frac{6}{10}$."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('dba9b92b-233f-6318-e058-2752b5b7c4c6','7404498b-69de-518e-aeec-f2bb9a98409c','question_single_choice','{"prompt":"A factory makes parts on machine A and machine B. Machine A makes $70\\%$ of the parts, and $2\\%$ of its parts are defective. Machine B makes the rest of the parts, and $5\\%$ of its parts are defective. If a defective part is selected at random, what is the probability that it was made by machine B?","options":[{"id":"A","label":"$\\frac{1}{20}$"},{"id":"B","label":"$\\frac{3}{10}$"},{"id":"C","label":"$\\frac{14}{29}$"},{"id":"D","label":"$\\frac{15}{29}$"}]}'::jsonb,65,'{"section_type":"math","sat_domain":"problem_solving_data_analysis","sat_official_domain":"problem_solving_data_analysis","sat_skill":"probability_and_conditional_probability","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"psda-prob-011","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('dba9b92b-233f-6318-e058-2752b5b7c4c6','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"Out of all parts, $0.70 \\times 0.02 = 0.014$ are defective from A and $0.30 \\times 0.05 = 0.015$ are defective from B. Given that a part is defective, the probability it came from B is $\\frac{0.015}{0.014 + 0.015} = \\frac{15}{29}$. Choice D is correct. Choice A is incorrect. This is the probability that a part made by machine B is defective; the condition is reversed. Choice B is incorrect. This is the probability that any part, defective or not, was made by machine B. Choice C is incorrect. This is the probability that the defective part was made by machine A."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('a87954ae-e7e4-0659-4bf4-042301a14c0d','7404498b-69de-518e-aeec-f2bb9a98409c','question_spr','{"prompt":"A sports center surveyed its $300$ members, $180$ of whom are under $30$ years old. Each member prefers either indoor or outdoor sports. The probability that a randomly selected member prefers outdoor sports is $0.45$. Given that a member is under $30$, the probability that the member prefers outdoor sports is $0.5$. How many members who are $30$ or older prefer indoor sports?"}'::jsonb,66,'{"section_type":"math","sat_domain":"problem_solving_data_analysis","sat_official_domain":"problem_solving_data_analysis","sat_skill":"probability_and_conditional_probability","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"psda-prob-012","answer_format":"spr"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('a87954ae-e7e4-0659-4bf4-042301a14c0d','{"accepted":["75"]}'::jsonb,'{"feedback":{"explanation":"Outdoor sports are preferred by $0.45 \\times 300 = 135$ members, including $0.5 \\times 180 = 90$ members under 30. So $135 - 90 = 45$ members aged 30 or older prefer outdoor sports. There are $300 - 180 = 120$ members aged 30 or older, so $120 - 45 = 75$ of them prefer indoor sports."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('fe063aa3-8a71-dc33-c4a2-2fc0c2bb2ce4','7404498b-69de-518e-aeec-f2bb9a98409c','question_single_choice','{"prompt":"A school has $2{,}000$ students. In a random sample of $250$ of these students, $60$ said they ride a bicycle to school. Based on the sample, which is the best estimate of the number of students at the school who ride a bicycle to school?","options":[{"id":"A","label":"$60$"},{"id":"B","label":"$190$"},{"id":"C","label":"$480$"},{"id":"D","label":"$1{,}520$"}]}'::jsonb,67,'{"section_type":"math","sat_domain":"problem_solving_data_analysis","sat_official_domain":"problem_solving_data_analysis","sat_skill":"inference_from_samples_and_margin_of_error","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"psda-infer-001","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('fe063aa3-8a71-dc33-c4a2-2fc0c2bb2ce4','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"In the sample, $\\frac{60}{250} = 0.24$ of the students ride a bicycle. Applying this to the school gives $0.24 \\times 2{,}000 = 480$ students. Choice C is correct. Choice A is incorrect. This is the number of bicycle riders in the sample, not an estimate for the whole school. Choice B is incorrect. This is the number of students in the sample who do not ride a bicycle. Choice D is incorrect. This is the estimated number of students at the school who do not ride a bicycle."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('3e65a6cb-408e-3420-8de5-e7364ecfe6bf','7404498b-69de-518e-aeec-f2bb9a98409c','question_single_choice','{"prompt":"A city planner wants to estimate the average number of hours per week that the city''s adult residents spend commuting. Which sampling method is most likely to produce a sample that is representative of all adult residents of the city?","options":[{"id":"A","label":"Selecting 400 adults at random from a complete list of the city''s adult residents"},{"id":"B","label":"Surveying 400 adults who work in the same office building"},{"id":"C","label":"Posting an online poll and using the first 400 adults who respond"},{"id":"D","label":"Surveying the first 400 adults who leave a downtown train station on a Monday morning"}]}'::jsonb,68,'{"section_type":"math","sat_domain":"problem_solving_data_analysis","sat_official_domain":"problem_solving_data_analysis","sat_skill":"inference_from_samples_and_margin_of_error","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"psda-infer-002","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('3e65a6cb-408e-3420-8de5-e7364ecfe6bf','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"A random sample from a complete list of the population gives every adult resident an equal chance of being chosen, which makes the sample most likely to represent the population. Choice A is correct. Choice B is incorrect. People who work in one building share a commute destination and are unlikely to represent the whole city. Choice C is incorrect. Volunteers who choose to respond may differ from other residents, so the sample may be biased. Choice D is incorrect. Train commuters at one station on one morning are not typical of all adults in the city."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('c27370c4-849f-bb2d-308f-6335b7ae6b06','7404498b-69de-518e-aeec-f2bb9a98409c','question_spr','{"prompt":"An inspector randomly selects $80$ light bulbs from a shipment of $4{,}000$ bulbs and finds that $3$ of the selected bulbs are defective. Based on this sample, what is the best estimate of the number of defective bulbs in the shipment?"}'::jsonb,69,'{"section_type":"math","sat_domain":"problem_solving_data_analysis","sat_official_domain":"problem_solving_data_analysis","sat_skill":"inference_from_samples_and_margin_of_error","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"psda-infer-003","answer_format":"spr"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('c27370c4-849f-bb2d-308f-6335b7ae6b06','{"accepted":["150"]}'::jsonb,'{"feedback":{"explanation":"The sample proportion of defective bulbs is $\\frac{3}{80}$. Applying it to the shipment gives $\\frac{3}{80} \\times 4{,}000 = 150$ bulbs."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('a0d8bcb3-b278-4432-0c9c-7651239edc61','7404498b-69de-518e-aeec-f2bb9a98409c','question_single_choice','{"prompt":"A random sample of a town''s voters found that $42\\%$ support building a new library, with a margin of error of $3$ percentage points. Which of the following is a plausible value for the percent of all the town''s voters who support building the new library?","options":[{"id":"A","label":"$38\\%$"},{"id":"B","label":"$40\\%$"},{"id":"C","label":"$46\\%$"},{"id":"D","label":"$50\\%$"}]}'::jsonb,70,'{"section_type":"math","sat_domain":"problem_solving_data_analysis","sat_official_domain":"problem_solving_data_analysis","sat_skill":"inference_from_samples_and_margin_of_error","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"psda-infer-004","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('a0d8bcb3-b278-4432-0c9c-7651239edc61','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"The plausible values are within 3 percentage points of 42%, from 39% to 45%. Of the choices, only 40% is in this interval. Choice B is correct. Choice A is incorrect. 38% is below the interval from 39% to 45% given by the estimate and its margin of error. Choice C is incorrect. 46% is above the interval from 39% to 45%. Choice D is incorrect. 50% is well above the interval from 39% to 45%."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('1b7a3766-3265-12dc-d5a6-0e7ab5c39cd4','7404498b-69de-518e-aeec-f2bb9a98409c','question_single_choice','{"prompt":"Researchers estimated the mean amount of time that teenagers in a region spend reading each week, using a random sample of $300$ teenagers. They want to repeat the study and obtain an estimate with a smaller margin of error. Which change is most likely to achieve this?","options":[{"id":"A","label":"Using a smaller random sample of teenagers from the region"},{"id":"B","label":"Surveying only teenagers who visit the region''s libraries"},{"id":"C","label":"Surveying the same number of teenagers chosen from volunteers"},{"id":"D","label":"Using a larger random sample of teenagers from the region"}]}'::jsonb,71,'{"section_type":"math","sat_domain":"problem_solving_data_analysis","sat_official_domain":"problem_solving_data_analysis","sat_skill":"inference_from_samples_and_margin_of_error","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"psda-infer-005","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('1b7a3766-3265-12dc-d5a6-0e7ab5c39cd4','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"For random samples, the margin of error decreases as the sample size increases, because larger samples give estimates that vary less from sample to sample. Choice D is correct. Choice A is incorrect. Smaller samples produce more variable estimates and therefore larger margins of error. Choice B is incorrect. This introduces bias; it does not make the estimate more precise for all teenagers in the region. Choice C is incorrect. Volunteers form a biased sample, and the sample size, which drives the margin of error, is unchanged."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('42d087d7-076c-4ea1-a0ea-33efc385bfb2','7404498b-69de-518e-aeec-f2bb9a98409c','question_single_choice','{"prompt":"A random sample of students at a university found that the mean amount of sleep the students in the sample got on weeknights was $6.8$ hours. The associated margin of error is $0.4$ hour. Which statement is the most appropriate conclusion?","options":[{"id":"A","label":"It is plausible that the mean weeknight sleep of all students at the university is between 6.4 and 7.2 hours."},{"id":"B","label":"The mean weeknight sleep of all students at the university is greater than 7.2 hours."},{"id":"C","label":"The mean weeknight sleep of all students at the university is exactly 6.8 hours."},{"id":"D","label":"Every student at the university sleeps between 6.4 and 7.2 hours on weeknights."}]}'::jsonb,72,'{"section_type":"math","sat_domain":"problem_solving_data_analysis","sat_official_domain":"problem_solving_data_analysis","sat_skill":"inference_from_samples_and_margin_of_error","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"psda-infer-006","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('42d087d7-076c-4ea1-a0ea-33efc385bfb2','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"A margin of error gives an interval of plausible values for the population mean: $6.8 - 0.4 = 6.4$ to $6.8 + 0.4 = 7.2$ hours. Choice A is correct. Choice B is incorrect. 7.2 hours is the upper end of the plausible interval, so the data do not suggest a greater mean. Choice C is incorrect. 6.8 hours is an estimate from a sample; the margin of error shows that the population mean could differ from it. Choice D is incorrect. The margin of error describes the uncertainty in the estimate of the mean, not the range of individual students'' sleep."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('def89109-c7da-1803-abf0-16be9163da0c','7404498b-69de-518e-aeec-f2bb9a98409c','question_single_choice','{"prompt":"A researcher selected $500$ registered voters at random from City X and found that $58\\%$ of them favor a proposal to extend library hours. To which group can the results of the survey most appropriately be generalized?","options":[{"id":"A","label":"All registered voters in City X"},{"id":"B","label":"Only the 500 voters who were surveyed"},{"id":"C","label":"All residents of City X, including those who are not registered voters"},{"id":"D","label":"All registered voters in the country"}]}'::jsonb,73,'{"section_type":"math","sat_domain":"problem_solving_data_analysis","sat_official_domain":"problem_solving_data_analysis","sat_skill":"inference_from_samples_and_margin_of_error","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"psda-infer-007","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('def89109-c7da-1803-abf0-16be9163da0c','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"Results from a random sample can be generalized to the population from which the sample was drawn, which is the registered voters of City X. Choice A is correct. Choice B is incorrect. Because the sample was random, the results can be generalized beyond the 500 people surveyed to the population they were drawn from. Choice C is incorrect. Residents who are not registered voters had no chance of being selected. Choice D is incorrect. The sample was drawn only from City X, so it does not represent voters elsewhere."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('f1aaf938-f7ea-0d4f-536c-2c71e4a21c40','7404498b-69de-518e-aeec-f2bb9a98409c','question_spr','{"prompt":"In a random sample of $120$ of the $9{,}600$ households in a town, $45$ households own a dog. The margin of error for the estimated proportion of households in the town that own a dog is $0.05$. Based on this information, what is the greatest plausible number of households in the town that own a dog?"}'::jsonb,74,'{"section_type":"math","sat_domain":"problem_solving_data_analysis","sat_official_domain":"problem_solving_data_analysis","sat_skill":"inference_from_samples_and_margin_of_error","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"psda-infer-008","answer_format":"spr"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('f1aaf938-f7ea-0d4f-536c-2c71e4a21c40','{"accepted":["4080"]}'::jsonb,'{"feedback":{"explanation":"The sample proportion is $\\frac{45}{120} = 0.375$. The greatest plausible proportion is $0.375 + 0.05 = 0.425$, and $0.425 \\times 9{,}600 = 4{,}080$ households."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('6335e780-a124-3ba4-3e94-42c97290e005','7404498b-69de-518e-aeec-f2bb9a98409c','question_single_choice','{"prompt":"A store manager claims that more than half of the store''s customers would use a new delivery service. In a random sample of the store''s customers, $54\\%$ said they would use the service, with a margin of error of $6$ percentage points. Which statement is best supported by these results?","options":[{"id":"A","label":"The results show that exactly 54% of all the store''s customers would use the service."},{"id":"B","label":"The results establish the claim, because 54% is greater than 50%."},{"id":"C","label":"The results show that the claim is false, because the margin of error is greater than 4 percentage points."},{"id":"D","label":"The results do not establish the claim, because the plausible values include percents of 50% or less."}]}'::jsonb,75,'{"section_type":"math","sat_domain":"problem_solving_data_analysis","sat_official_domain":"problem_solving_data_analysis","sat_skill":"inference_from_samples_and_margin_of_error","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"psda-infer-009","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('6335e780-a124-3ba4-3e94-42c97290e005','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"The plausible values for the percent of all customers are $54\\% \\pm 6\\%$, or from 48% to 60%. Because this interval contains values at or below 50% as well as values above it, the data neither confirm nor refute the claim. Choice D is correct. Choice A is incorrect. 54% is an estimate from a sample, not the exact population value. Choice B is incorrect. The sample estimate is above 50%, but the plausible interval from 48% to 60% also includes values below 50%. Choice C is incorrect. Plausible values above 50% are also in the interval, so the claim is not shown to be false."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('a21ac742-3b1e-965b-a4cf-eb103f72a399','7404498b-69de-518e-aeec-f2bb9a98409c','question_single_choice','{"prompt":"Researchers selected $300$ people at random from the list of all library card holders in a city. Of those surveyed, $34\\%$ reported reading at least $3$ books last month, with an associated margin of error of $5$ percentage points. Which conclusion is most appropriate?","options":[{"id":"A","label":"It is plausible that between 29% and 39% of all residents of the city read at least 3 books last month."},{"id":"B","label":"Between 29% and 39% of the 300 people surveyed read at least 3 books last month."},{"id":"C","label":"Exactly 34% of all library card holders in the city read at least 3 books last month."},{"id":"D","label":"It is plausible that between 29% and 39% of all library card holders in the city read at least 3 books last month."}]}'::jsonb,76,'{"section_type":"math","sat_domain":"problem_solving_data_analysis","sat_official_domain":"problem_solving_data_analysis","sat_skill":"inference_from_samples_and_margin_of_error","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"psda-infer-010","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('a21ac742-3b1e-965b-a4cf-eb103f72a399','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"The interval $34\\% \\pm 5\\%$, from 29% to 39%, gives plausible values for the population that was sampled: the library card holders of the city. Choice D is correct. Choice A is incorrect. The sample was drawn only from library card holders, who may read more than residents in general. Choice B is incorrect. Exactly 34% of the people surveyed did so; the interval describes the population, not the sample. Choice C is incorrect. 34% is a sample estimate; the margin of error shows the population value may differ."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('88cbfb64-5235-ba5f-09d5-fdb4fca44697','7404498b-69de-518e-aeec-f2bb9a98409c','question_single_choice','{"prompt":"For a certain survey, the margin of error is inversely proportional to the square root of the sample size. A random sample of $400$ people gives a margin of error of $5$ percentage points. Approximately what sample size would give a margin of error of $2.5$ percentage points?","options":[{"id":"A","label":"$200$"},{"id":"B","label":"$800$"},{"id":"C","label":"$1{,}600$"},{"id":"D","label":"$3{,}200$"}]}'::jsonb,77,'{"section_type":"math","sat_domain":"problem_solving_data_analysis","sat_official_domain":"problem_solving_data_analysis","sat_skill":"inference_from_samples_and_margin_of_error","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"psda-infer-011","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('88cbfb64-5235-ba5f-09d5-fdb4fca44697','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"If $E = \\frac{k}{\\sqrt{n}}$, halving $E$ requires doubling $\\sqrt{n}$, which multiplies $n$ by 4. So the sample size should be $4 \\times 400 = 1{,}600$. Choice C is correct. Choice A is incorrect. This halves the sample size, which would make the margin of error larger, not smaller. Choice B is incorrect. This doubles the sample size; because the margin of error depends on the square root of the sample size, halving it requires 4 times as many people. Choice D is incorrect. This multiplies the sample size by 8, more than the factor of 4 needed."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('2c99ed34-5046-6d51-92af-4961543c5de6','7404498b-69de-518e-aeec-f2bb9a98409c','question_spr','{"prompt":"Biologists caught, tagged, and released $120$ fish in a lake. A month later, they caught a random sample of $250$ fish from the lake and found that $15$ of them were tagged. Assuming the tagged fish mixed evenly with the rest of the population, what is the best estimate of the total number of fish in the lake?"}'::jsonb,78,'{"section_type":"math","sat_domain":"problem_solving_data_analysis","sat_official_domain":"problem_solving_data_analysis","sat_skill":"inference_from_samples_and_margin_of_error","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"psda-infer-012","answer_format":"spr"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('2c99ed34-5046-6d51-92af-4961543c5de6','{"accepted":["2000"]}'::jsonb,'{"feedback":{"explanation":"The proportion of tagged fish in the sample, $\\frac{15}{250}$, estimates the proportion in the lake, $\\frac{120}{N}$. Solving $\\frac{120}{N} = \\frac{15}{250}$ gives $N = \\frac{120 \\times 250}{15} = 2{,}000$."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('de201e78-dd22-fe3a-726f-cdf7c3670201','7404498b-69de-518e-aeec-f2bb9a98409c','question_single_choice','{"prompt":"A researcher surveyed adults and found that those who reported drinking more water each day also reported having fewer headaches. Participants were not assigned to drink any particular amount of water. Which conclusion is best supported by the study?","options":[{"id":"A","label":"Among the people surveyed, drinking more water is associated with having fewer headaches."},{"id":"B","label":"There is no relationship between water intake and headaches."},{"id":"C","label":"Having fewer headaches causes people to drink more water."},{"id":"D","label":"Drinking more water causes people to have fewer headaches."}]}'::jsonb,79,'{"section_type":"math","sat_domain":"problem_solving_data_analysis","sat_official_domain":"problem_solving_data_analysis","sat_skill":"evaluating_statistical_claims","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"psda-claims-001","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('de201e78-dd22-fe3a-726f-cdf7c3670201','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"This is an observational study: the researcher recorded what people did rather than assigning treatments. It can show an association but not a cause-and-effect relationship. Choice A is correct. Choice B is incorrect. The survey did find a relationship; it just cannot show that one causes the other. Choice C is incorrect. An observational study cannot establish causation in either direction. Choice D is incorrect. Because the participants were not randomly assigned to drink different amounts, the study cannot show cause and effect."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('99d4c295-a89c-3bab-bba1-dd721cb32954','7404498b-69de-518e-aeec-f2bb9a98409c','question_single_choice','{"prompt":"Researchers recruited $200$ volunteers and randomly assigned half of them to use a new sleep app for one month and the other half not to use it. The group using the app slept an average of $25$ minutes longer per night. Which conclusion is most appropriate?","options":[{"id":"A","label":"Sleeping longer causes people to use the app."},{"id":"B","label":"No conclusion about cause and effect can be drawn from the study."},{"id":"C","label":"The app causes longer sleep for all adults."},{"id":"D","label":"The app is likely to cause longer sleep for people similar to the volunteers in the study."}]}'::jsonb,80,'{"section_type":"math","sat_domain":"problem_solving_data_analysis","sat_official_domain":"problem_solving_data_analysis","sat_skill":"evaluating_statistical_claims","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"psda-claims-002","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('99d4c295-a89c-3bab-bba1-dd721cb32954','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"Because the volunteers were randomly assigned to groups, the difference in sleep can be attributed to the app. Because they were not randomly selected from a larger population, the conclusion applies to people like the volunteers. Choice D is correct. Choice A is incorrect. The researchers decided who used the app, so the direction of the effect is from the app to sleep. Choice B is incorrect. Random assignment to the two groups allows a cause-and-effect conclusion for the participants. Choice C is incorrect. The participants were volunteers, not a random sample of all adults, so the result cannot be generalized to all adults."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('fa0da1c8-9bf1-3665-e555-a7f54bcdf275','7404498b-69de-518e-aeec-f2bb9a98409c','question_single_choice','{"prompt":"To estimate the average number of hours that the adults in a town exercise each week, a researcher surveyed $150$ adults at the town''s fitness center. Which statement best explains why the results may not be a good estimate for all adults in the town?","options":[{"id":"A","label":"People at a fitness center are likely to exercise more than typical adults in the town."},{"id":"B","label":"The researcher should have asked about exercise per day instead of per week."},{"id":"C","label":"A sample of 150 adults is too large to give a useful estimate."},{"id":"D","label":"The town''s adults all exercise the same amount, so no survey is needed."}]}'::jsonb,81,'{"section_type":"math","sat_domain":"problem_solving_data_analysis","sat_official_domain":"problem_solving_data_analysis","sat_skill":"evaluating_statistical_claims","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"psda-claims-003","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('fa0da1c8-9bf1-3665-e555-a7f54bcdf275','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"The sample was taken from a place where people go to exercise, so it overrepresents active adults. The sample is biased and not representative of all adults in the town. Choice A is correct. Choice B is incorrect. Changing the time unit does not fix the bias in who was surveyed. Choice C is incorrect. Larger samples generally give better estimates; the problem is how the sample was chosen. Choice D is incorrect. There is no reason to believe this, and it does not address the flaw in the sampling method."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('18ec38c2-413f-c334-6d98-1fdcf3b47bf5','7404498b-69de-518e-aeec-f2bb9a98409c','question_single_choice','{"prompt":"The bar graph shows the number of bicycles sold last month by two stores. Note that the vertical axis does not start at $0$. A newspaper claims that store B sold more than twice as many bicycles as store A. Which statement best evaluates the claim?","figure_svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 420 320\" width=\"420\" height=\"320\" font-family=\"Arial, Helvetica, sans-serif\" font-size=\"17\" role=\"img\"><title>Bar graph with vertical axis starting at 88: Store A sold 92 bicycles and Store B sold 98 bicycles.</title><rect x=\"0\" y=\"0\" width=\"420\" height=\"320\" fill=\"#ffffff\"/><line x1=\"62\" y1=\"262\" x2=\"400\" y2=\"262\" stroke=\"#d1d5db\" stroke-width=\"1\"/><text x=\"54\" y=\"267\" text-anchor=\"end\" font-size=\"15\" fill=\"#1f2937\">88</text><line x1=\"62\" y1=\"221.33\" x2=\"400\" y2=\"221.33\" stroke=\"#d1d5db\" stroke-width=\"1\"/><text x=\"54\" y=\"226.33\" text-anchor=\"end\" font-size=\"15\" fill=\"#1f2937\">90</text><line x1=\"62\" y1=\"180.67\" x2=\"400\" y2=\"180.67\" stroke=\"#d1d5db\" stroke-width=\"1\"/><text x=\"54\" y=\"185.67\" text-anchor=\"end\" font-size=\"15\" fill=\"#1f2937\">92</text><line x1=\"62\" y1=\"140\" x2=\"400\" y2=\"140\" stroke=\"#d1d5db\" stroke-width=\"1\"/><text x=\"54\" y=\"145\" text-anchor=\"end\" font-size=\"15\" fill=\"#1f2937\">94</text><line x1=\"62\" y1=\"99.33\" x2=\"400\" y2=\"99.33\" stroke=\"#d1d5db\" stroke-width=\"1\"/><text x=\"54\" y=\"104.33\" text-anchor=\"end\" font-size=\"15\" fill=\"#1f2937\">96</text><line x1=\"62\" y1=\"58.67\" x2=\"400\" y2=\"58.67\" stroke=\"#d1d5db\" stroke-width=\"1\"/><text x=\"54\" y=\"63.67\" text-anchor=\"end\" font-size=\"15\" fill=\"#1f2937\">98</text><line x1=\"62\" y1=\"18\" x2=\"400\" y2=\"18\" stroke=\"#d1d5db\" stroke-width=\"1\"/><text x=\"54\" y=\"23\" text-anchor=\"end\" font-size=\"15\" fill=\"#1f2937\">100</text><line x1=\"62\" y1=\"262\" x2=\"400\" y2=\"262\" stroke=\"#1f2937\" stroke-width=\"1.5\"/><line x1=\"62\" y1=\"18\" x2=\"62\" y2=\"262\" stroke=\"#1f2937\" stroke-width=\"1.5\"/><path d=\"M56,256 L68,250 M56,262 L68,256\" fill=\"none\" stroke=\"#1f2937\" stroke-width=\"1.5\"/><text x=\"231\" y=\"310\" text-anchor=\"middle\" font-size=\"16\" fill=\"#1f2937\">Store</text><text x=\"18\" y=\"140\" text-anchor=\"middle\" font-size=\"16\" transform=\"rotate(-90 18 140)\" fill=\"#1f2937\">Bicycles sold</text><rect x=\"95.8\" y=\"180.67\" width=\"101.4\" height=\"81.33\" fill=\"#1d4ed8\" fill-opacity=\"0.75\" stroke=\"#1f2937\" stroke-width=\"1\"/><text x=\"146.5\" y=\"282\" text-anchor=\"middle\" font-size=\"15\" fill=\"#1f2937\">Store A</text><rect x=\"264.8\" y=\"58.67\" width=\"101.4\" height=\"203.33\" fill=\"#1d4ed8\" fill-opacity=\"0.75\" stroke=\"#1f2937\" stroke-width=\"1\"/><text x=\"315.5\" y=\"282\" text-anchor=\"middle\" font-size=\"15\" fill=\"#1f2937\">Store B</text></svg>","options":[{"id":"A","label":"The claim is supported, because store B''s bar is more than twice as tall as store A''s bar."},{"id":"B","label":"The claim is supported, because store B sold 98 bicycles, which is greater than 92."},{"id":"C","label":"The claim cannot be evaluated without knowing each store''s total revenue."},{"id":"D","label":"The claim is not supported; store B sold only 6 more bicycles than store A, about 6.5% more."}]}'::jsonb,82,'{"section_type":"math","sat_domain":"problem_solving_data_analysis","sat_official_domain":"problem_solving_data_analysis","sat_skill":"evaluating_statistical_claims","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"psda-claims-004","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('18ec38c2-413f-c334-6d98-1fdcf3b47bf5','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"Reading the graph, store A sold 92 bicycles and store B sold 98. Twice 92 is 184, so the claim is false. The difference is $98 - 92 = 6$, and $\\frac{6}{92} \\approx 0.065$, so store B sold about 6.5% more. Choice D is correct. Choice A is incorrect. The axis starts at 88, so bar heights exaggerate the difference; the actual counts are 92 and 98. Choice B is incorrect. Selling more is not the same as selling more than twice as many; twice 92 is 184. Choice C is incorrect. The graph gives the number of bicycles sold, which is all that is needed to evaluate the claim."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('43c8d3c8-d50c-518b-cb7a-7828b7da6340','7404498b-69de-518e-aeec-f2bb9a98409c','question_single_choice','{"prompt":"A city council member wants to estimate how residents feel about a proposed budget. Which survey question is most likely to produce biased results?","options":[{"id":"A","label":"Do you agree that the city''s wasteful new budget should be rejected?"},{"id":"B","label":"Have you read a summary of the proposed budget?"},{"id":"C","label":"Do you support or oppose the city''s proposed budget?"},{"id":"D","label":"How would you rate the proposed budget on a scale from 1 (strongly oppose) to 5 (strongly support)?"}]}'::jsonb,83,'{"section_type":"math","sat_domain":"problem_solving_data_analysis","sat_official_domain":"problem_solving_data_analysis","sat_skill":"evaluating_statistical_claims","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"psda-claims-005","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('43c8d3c8-d50c-518b-cb7a-7828b7da6340','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"Calling the budget wasteful and asking respondents to agree that it should be rejected leads them toward one answer. Leading wording like this biases survey results. Choice A is correct. Choice B is incorrect. This asks a factual question and does not push respondents toward an opinion. Choice C is incorrect. This wording presents both options neutrally. Choice D is incorrect. This gives a balanced scale with labeled ends and does not suggest an answer."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('85b533ba-00fe-9ab7-7b3a-5a912be46dbd','7404498b-69de-518e-aeec-f2bb9a98409c','question_single_choice','{"prompt":"A study of many families found that students who take private music lessons tend to have higher math scores than students who do not. Which statement gives a possible explanation for this association that does not involve music lessons causing higher math scores?","options":[{"id":"A","label":"Students who take music lessons practice their instruments."},{"id":"B","label":"The study included many families."},{"id":"C","label":"Math scores were measured with a standardized test."},{"id":"D","label":"Families that can afford private lessons may also be able to provide other educational resources."}]}'::jsonb,84,'{"section_type":"math","sat_domain":"problem_solving_data_analysis","sat_official_domain":"problem_solving_data_analysis","sat_skill":"evaluating_statistical_claims","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"psda-claims-006","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('85b533ba-00fe-9ab7-7b3a-5a912be46dbd','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"A third factor, such as family resources, could make students both more likely to take lessons and more likely to score well in math. Such a confounding variable explains an association without causation. Choice D is correct. Choice A is incorrect. This describes the lessons; it does not offer another factor that could explain the higher math scores. Choice B is incorrect. A large sample does not explain the association or rule out causation. Choice C is incorrect. The way scores were measured does not provide an alternative explanation for the association."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('e5c7dd97-fcc0-970d-ff94-ab450437610a','7404498b-69de-518e-aeec-f2bb9a98409c','question_single_choice','{"prompt":"In a random sample of $1{,}000$ adults in Country X, those who reported walking at least $30$ minutes a day had lower average blood pressure than those who did not. Which conclusion is most appropriate?","options":[{"id":"A","label":"Among adults in Country X, walking at least 30 minutes a day is associated with lower blood pressure."},{"id":"B","label":"Walking at least 30 minutes a day is associated with lower blood pressure for all adults worldwide."},{"id":"C","label":"Walking at least 30 minutes a day causes lower blood pressure among adults in Country X."},{"id":"D","label":"There is no association, because the study was not an experiment."}]}'::jsonb,85,'{"section_type":"math","sat_domain":"problem_solving_data_analysis","sat_official_domain":"problem_solving_data_analysis","sat_skill":"evaluating_statistical_claims","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"psda-claims-007","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('e5c7dd97-fcc0-970d-ff94-ab450437610a','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"Because the sample was randomly selected from adults in Country X, the association can be generalized to that population. Because the walking was not assigned, no cause-and-effect conclusion is justified. Choice A is correct. Choice B is incorrect. The sample came only from Country X, so the results can be generalized only to adults there. Choice C is incorrect. The adults chose whether to walk; without random assignment, the study cannot show causation. Choice D is incorrect. Observational studies can establish associations; they just cannot establish causation."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('02cedcd6-c05a-59f9-5ec5-2699ea5f2e8c','7404498b-69de-518e-aeec-f2bb9a98409c','question_single_choice','{"prompt":"A farmer wants to determine whether a new fertilizer increases the yield of tomato plants. Which study design would best allow the farmer to conclude that the fertilizer causes a change in yield?","options":[{"id":"A","label":"Let the farm workers choose which plants receive the fertilizer, and compare the yields."},{"id":"B","label":"Apply the fertilizer to plants in the sunniest rows, and compare them with plants in the other rows."},{"id":"C","label":"Apply the fertilizer to all plants this year and compare the yield with last year''s yield."},{"id":"D","label":"Randomly assign 60 plants from one field to receive the fertilizer or not, and compare the yields."}]}'::jsonb,86,'{"section_type":"math","sat_domain":"problem_solving_data_analysis","sat_official_domain":"problem_solving_data_analysis","sat_skill":"evaluating_statistical_claims","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"psda-claims-008","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('02cedcd6-c05a-59f9-5ec5-2699ea5f2e8c','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"Random assignment of plants to treatment and control groups balances other factors, such as soil and sunlight, between the groups, so a difference in yield can be attributed to the fertilizer. Choice D is correct. Choice A is incorrect. Workers might choose healthier plants, which would bias the comparison. Choice B is incorrect. Sunlight would be confounded with the fertilizer, so its effect could not be separated. Choice C is incorrect. Weather and other conditions differ between years, so any difference cannot be attributed to the fertilizer."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('929c012d-ed3b-8ab2-9ecf-8c7164fb1284','7404498b-69de-518e-aeec-f2bb9a98409c','question_single_choice','{"prompt":"Two groups estimated the percent of a state''s residents who favor a new park. Group 1 posted an online poll and received $5{,}000$ responses. Group 2 surveyed $400$ residents selected at random from the state''s residents. Which statement is best supported?","options":[{"id":"A","label":"Group 2''s estimate is more reliable, because its sample was randomly selected."},{"id":"B","label":"Neither estimate can be used, because neither group surveyed every resident."},{"id":"C","label":"Both estimates are equally reliable, because both groups surveyed residents."},{"id":"D","label":"Group 1''s estimate is more reliable, because its sample is larger."}]}'::jsonb,87,'{"section_type":"math","sat_domain":"problem_solving_data_analysis","sat_official_domain":"problem_solving_data_analysis","sat_skill":"evaluating_statistical_claims","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"psda-claims-009","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('929c012d-ed3b-8ab2-9ecf-8c7164fb1284','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"People who choose to answer an online poll may hold stronger opinions than other residents, so Group 1''s sample is likely biased. A random sample gives every resident an equal chance of selection, making Group 2''s estimate more trustworthy. Choice A is correct. Choice B is incorrect. A random sample can give a reliable estimate without surveying the entire population. Choice C is incorrect. The way the residents were chosen differs, and that affects reliability. Choice D is incorrect. A large sample of volunteers can still be biased; size does not fix a biased selection method."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('9b24251d-0a08-99b5-ce8d-75419e982536','7404498b-69de-518e-aeec-f2bb9a98409c','question_single_choice','{"prompt":"A researcher selected $500$ residents of Town T at random and then randomly assigned half of them to receive weekly text reminders about recycling. After two months, the residents who received reminders recycled significantly more on average than the others. Which conclusion is most appropriate?","options":[{"id":"A","label":"Text reminders are likely to cause an increase in recycling among residents of every town."},{"id":"B","label":"Text reminders are associated with more recycling, but no cause-and-effect conclusion is possible."},{"id":"C","label":"No conclusion is possible, because only 500 of the town''s residents were studied."},{"id":"D","label":"Text reminders are likely to cause an increase in recycling among residents of Town T."}]}'::jsonb,88,'{"section_type":"math","sat_domain":"problem_solving_data_analysis","sat_official_domain":"problem_solving_data_analysis","sat_skill":"evaluating_statistical_claims","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"psda-claims-010","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('9b24251d-0a08-99b5-ce8d-75419e982536','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"Random selection from Town T allows generalization to Town T''s residents, and random assignment of reminders allows a cause-and-effect conclusion. Together they support a causal conclusion for residents of Town T. Choice D is correct. Choice A is incorrect. The residents were selected only from Town T, so the results cannot be generalized beyond Town T. Choice B is incorrect. Random assignment to the two groups is what allows a cause-and-effect conclusion. Choice C is incorrect. A random sample of 500 residents is enough to draw conclusions about the town''s population."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('28285c54-f0a6-3447-3cc1-cc937c5c6cc1','7404498b-69de-518e-aeec-f2bb9a98409c','question_single_choice','{"prompt":"In a random sample of $800$ employees of Company Q, employees who chose to work remotely reported higher job satisfaction, on average, than employees who chose to work in the office. Which conclusion is most appropriate?","options":[{"id":"A","label":"Among employees of Company Q, working remotely is associated with higher job satisfaction, but the study does not show that remote work causes it."},{"id":"B","label":"Working remotely causes higher job satisfaction among employees of Company Q."},{"id":"C","label":"Working remotely causes higher job satisfaction for workers at all companies."},{"id":"D","label":"The association applies only to the 800 employees surveyed."}]}'::jsonb,89,'{"section_type":"math","sat_domain":"problem_solving_data_analysis","sat_official_domain":"problem_solving_data_analysis","sat_skill":"evaluating_statistical_claims","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"psda-claims-011","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('28285c54-f0a6-3447-3cc1-cc937c5c6cc1','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"Random sampling supports generalizing the association to all employees of Company Q. Because employees were not randomly assigned to work locations, a cause-and-effect conclusion is not supported. Choice A is correct. Choice B is incorrect. The employees chose where to work, so other differences between the groups could explain the result. Choice C is incorrect. The study supports neither causation nor generalization beyond Company Q. Choice D is incorrect. Because the sample was random, the association can be generalized to all employees of Company Q."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('c23ea40c-84cf-ec43-1c2e-2228e1fd65a6','7404498b-69de-518e-aeec-f2bb9a98409c','question_single_choice','{"prompt":"The table shows the annual salaries, in thousands of dollars, of all $9$ employees at a small company. In an advertisement, the company claims that its typical employee earns more than $70$ thousand dollars per year. Which statement best evaluates the claim?","table":{"headers":["Employee","Salary (thousands of dollars)"],"rows":[["1","41"],["2","43"],["3","44"],["4","45"],["5","45"],["6","47"],["7","48"],["8","50"],["9","300"]]},"options":[{"id":"A","label":"The claim is misleading, because the mode of the salaries is 70 thousand dollars."},{"id":"B","label":"The claim is accurate, because the mean salary is greater than 70 thousand dollars."},{"id":"C","label":"The claim is accurate, because the range of salaries is greater than 70 thousand dollars."},{"id":"D","label":"The claim is misleading; the mean is about 73.7 thousand dollars only because of one very high salary, and the median, 45 thousand dollars, better describes a typical employee."}]}'::jsonb,90,'{"section_type":"math","sat_domain":"problem_solving_data_analysis","sat_official_domain":"problem_solving_data_analysis","sat_skill":"evaluating_statistical_claims","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"psda-claims-012","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('c23ea40c-84cf-ec43-1c2e-2228e1fd65a6','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"The sum of the salaries is $663$, so the mean is $\\frac{663}{9} \\approx 73.7$ thousand dollars. The median, the 5th value in order, is 45 thousand dollars. Because one outlier inflates the mean, the median is the better measure of a typical salary, and it is far below 70 thousand dollars. Choice D is correct. Choice A is incorrect. The mode is 45 thousand dollars, the only value that appears twice. Choice B is incorrect. The mean is pulled up by the single salary of 300 thousand dollars; 8 of the 9 employees earn 50 thousand dollars or less. Choice C is incorrect. The range measures spread, not a typical value."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.parts(id,section_id,name,display_order,metadata) values('978612a1-1a5e-c55f-a23d-ab24bca46382','bee41358-7368-5bbb-bb76-e42afe3c1c44','Geometry and Trigonometry',13,'{"sat_official_domain":"geometry_trigonometry","content_revision":"original-2026-10-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('ba819b32-b076-b56b-307e-660423704907','978612a1-1a5e-c55f-a23d-ab24bca46382','question_single_choice','{"prompt":"A rectangle has a length of $14$ inches and a width of $9$ inches. What is the area of the rectangle, in square inches?","options":[{"id":"A","label":"$23$"},{"id":"B","label":"$46$"},{"id":"C","label":"$63$"},{"id":"D","label":"$126$"}]}'::jsonb,1,'{"section_type":"math","sat_domain":"geometry_trig","sat_official_domain":"geometry_trigonometry","sat_skill":"area_and_volume","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"geo-area-001","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('ba819b32-b076-b56b-307e-660423704907','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"The area of a rectangle is length times width: $14 \\times 9 = 126$ square inches. Choice D is correct. Choice A is incorrect. This adds the length and width instead of multiplying them. Choice B is incorrect. This is the perimeter of the rectangle, not its area. Choice C is incorrect. This takes half of the product, which is the area of a triangle with this base and height, not of a rectangle."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('c9fda545-ea63-1987-7aa1-5aa9ee7a1298','978612a1-1a5e-c55f-a23d-ab24bca46382','question_spr','{"prompt":"A rectangular prism has a length of $5$ centimeters, a width of $4$ centimeters, and a height of $7$ centimeters. What is the volume of the prism, in cubic centimeters?"}'::jsonb,2,'{"section_type":"math","sat_domain":"geometry_trig","sat_official_domain":"geometry_trigonometry","sat_skill":"area_and_volume","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"geo-area-002","answer_format":"spr"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('c9fda545-ea63-1987-7aa1-5aa9ee7a1298','{"accepted":["140"]}'::jsonb,'{"feedback":{"explanation":"The volume of a rectangular prism is length times width times height: $5 \\times 4 \\times 7 = 140$ cubic centimeters."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('a928630b-0c63-c367-c1b1-23d023241e3c','978612a1-1a5e-c55f-a23d-ab24bca46382','question_single_choice','{"prompt":"In the figure, the triangle has a base of length $16$ and a height of $9$. What is the area of the triangle?","figure_svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 400 260\" width=\"400\" height=\"260\" font-family=\"Arial, Helvetica, sans-serif\" font-size=\"17\" role=\"img\"><title>Triangle with base 16 and a dashed height of 9 drawn from the top vertex to the base.</title><rect x=\"0\" y=\"0\" width=\"400\" height=\"260\" fill=\"#ffffff\"/><polygon points=\"40,220 360,220 140,40\" fill=\"none\" stroke=\"#1f2937\" stroke-width=\"2\" stroke-linejoin=\"round\"/><line x1=\"140\" y1=\"40\" x2=\"140\" y2=\"220\" stroke=\"#1f2937\" stroke-width=\"1.5\" stroke-dasharray=\"6 4\"/><path d=\"M152,220 L152,208 L140,208\" fill=\"none\" stroke=\"#1f2937\" stroke-width=\"1.2\"/><text x=\"200\" y=\"246\" text-anchor=\"middle\" fill=\"#1f2937\">16</text><text x=\"154\" y=\"135\" fill=\"#1f2937\">9</text></svg>","options":[{"id":"A","label":"$25$"},{"id":"B","label":"$36$"},{"id":"C","label":"$72$"},{"id":"D","label":"$144$"}]}'::jsonb,3,'{"section_type":"math","sat_domain":"geometry_trig","sat_official_domain":"geometry_trigonometry","sat_skill":"area_and_volume","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"geo-area-003","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('a928630b-0c63-c367-c1b1-23d023241e3c','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"The area of a triangle is $\\frac{1}{2} \\times \\text{base} \\times \\text{height} = \\frac{1}{2}(16)(9) = 72$. Choice C is correct. Choice A is incorrect. This adds the base and the height instead of using the area formula. Choice B is incorrect. This multiplies by $\\frac{1}{4}$ instead of $\\frac{1}{2}$. Choice D is incorrect. This is base times height without the factor of $\\frac{1}{2}$; it is the area of a rectangle."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('f7841daa-e5ce-b877-209d-d77da458ec62','978612a1-1a5e-c55f-a23d-ab24bca46382','question_single_choice','{"prompt":"A circle has a radius of $5$ meters. What is the area of the circle, in square meters?","options":[{"id":"A","label":"$5\\pi$"},{"id":"B","label":"$10\\pi$"},{"id":"C","label":"$25\\pi$"},{"id":"D","label":"$100\\pi$"}]}'::jsonb,4,'{"section_type":"math","sat_domain":"geometry_trig","sat_official_domain":"geometry_trigonometry","sat_skill":"area_and_volume","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"geo-area-004","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('f7841daa-e5ce-b877-209d-d77da458ec62','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"The area of a circle is $\\pi r^2 = \\pi(5)^2 = 25\\pi$ square meters. Choice C is correct. Choice A is incorrect. This multiplies $\\pi$ by the radius instead of by the square of the radius. Choice B is incorrect. This is the circumference, $2\\pi r$, not the area. Choice D is incorrect. This squares the diameter, 10, instead of the radius."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('172362b9-5b42-0640-020c-d881d65a49af','978612a1-1a5e-c55f-a23d-ab24bca46382','question_spr','{"prompt":"A cube has a volume of $343$ cubic inches. What is the length of one edge of the cube, in inches?"}'::jsonb,5,'{"section_type":"math","sat_domain":"geometry_trig","sat_official_domain":"geometry_trigonometry","sat_skill":"area_and_volume","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"geo-area-005","answer_format":"spr"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('172362b9-5b42-0640-020c-d881d65a49af','{"accepted":["7"]}'::jsonb,'{"feedback":{"explanation":"The volume of a cube is $s^3$. Since $7^3 = 343$, the edge length is $7$ inches."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('d7fd3a65-9b2a-fe18-c2ca-27cd115a4228','978612a1-1a5e-c55f-a23d-ab24bca46382','question_single_choice','{"prompt":"A right circular cylinder has a radius of $3$ feet and a height of $10$ feet. What is the volume of the cylinder, in cubic feet?","options":[{"id":"A","label":"$30\\pi$"},{"id":"B","label":"$60\\pi$"},{"id":"C","label":"$90\\pi$"},{"id":"D","label":"$360\\pi$"}]}'::jsonb,6,'{"section_type":"math","sat_domain":"geometry_trig","sat_official_domain":"geometry_trigonometry","sat_skill":"area_and_volume","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"geo-area-006","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('d7fd3a65-9b2a-fe18-c2ca-27cd115a4228','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"The volume of a cylinder is $\\pi r^2 h = \\pi(3)^2(10) = 90\\pi$ cubic feet. Choice C is correct. Choice A is incorrect. This uses $\\pi r h$, forgetting to square the radius. Choice B is incorrect. This is the lateral surface area, $2\\pi r h$, not the volume. Choice D is incorrect. This uses the diameter, 6, in place of the radius."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('646c0be0-4bac-6d82-5767-c50c6335ef62','978612a1-1a5e-c55f-a23d-ab24bca46382','question_single_choice','{"prompt":"A square has a perimeter of $36$ centimeters. What is the area of the square, in square centimeters?","options":[{"id":"A","label":"$9$"},{"id":"B","label":"$18$"},{"id":"C","label":"$36$"},{"id":"D","label":"$81$"}]}'::jsonb,7,'{"section_type":"math","sat_domain":"geometry_trig","sat_official_domain":"geometry_trigonometry","sat_skill":"area_and_volume","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"geo-area-007","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('646c0be0-4bac-6d82-5767-c50c6335ef62','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"Each side of the square has length $\\frac{36}{4} = 9$ centimeters, so the area is $9^2 = 81$ square centimeters. Choice D is correct. Choice A is incorrect. This is the side length of the square, not its area. Choice B is incorrect. This doubles the side length instead of squaring it. Choice C is incorrect. This is the perimeter of the square."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('d60e710e-af71-de0b-6102-4f71bf8cc3cc','978612a1-1a5e-c55f-a23d-ab24bca46382','question_single_choice','{"prompt":"A rectangle has an area of $96$ square feet and a length of $12$ feet. What is the perimeter of the rectangle, in feet?","options":[{"id":"A","label":"$8$"},{"id":"B","label":"$20$"},{"id":"C","label":"$28$"},{"id":"D","label":"$40$"}]}'::jsonb,8,'{"section_type":"math","sat_domain":"geometry_trig","sat_official_domain":"geometry_trigonometry","sat_skill":"area_and_volume","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"geo-area-008","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('d60e710e-af71-de0b-6102-4f71bf8cc3cc','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"The width is $\\frac{96}{12} = 8$ feet, so the perimeter is $2(12 + 8) = 40$ feet. Choice D is correct. Choice A is incorrect. This is the width of the rectangle, not its perimeter. Choice B is incorrect. This adds the length and width once; the perimeter includes each side twice. Choice C is incorrect. This adds only three of the four sides."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('61a384ad-ddf1-8187-e494-52da59993f88','978612a1-1a5e-c55f-a23d-ab24bca46382','question_single_choice','{"prompt":"In the figure, all angles are right angles. What is the area of the figure?","figure_svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 360 290\" width=\"360\" height=\"290\" font-family=\"Arial, Helvetica, sans-serif\" font-size=\"17\" role=\"img\"><title>L-shaped figure: a 12 by 10 rectangle with a 5 by 4 rectangle removed from its upper right corner.</title><rect x=\"0\" y=\"0\" width=\"360\" height=\"290\" fill=\"#ffffff\"/><polygon points=\"40,250 304,250 304,118 194,118 194,30 40,30\" fill=\"none\" stroke=\"#1f2937\" stroke-width=\"2\" stroke-linejoin=\"round\"/><text x=\"172\" y=\"272\" text-anchor=\"middle\" fill=\"#1f2937\">12</text><text x=\"24\" y=\"145\" text-anchor=\"end\" fill=\"#1f2937\">10</text><text x=\"249\" y=\"110\" text-anchor=\"middle\" fill=\"#1f2937\">5</text><text x=\"186\" y=\"79\" text-anchor=\"end\" fill=\"#1f2937\">4</text></svg>","options":[{"id":"A","label":"$44$"},{"id":"B","label":"$100$"},{"id":"C","label":"$120$"},{"id":"D","label":"$140$"}]}'::jsonb,9,'{"section_type":"math","sat_domain":"geometry_trig","sat_official_domain":"geometry_trigonometry","sat_skill":"area_and_volume","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"geo-area-009","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('61a384ad-ddf1-8187-e494-52da59993f88','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"The figure is a 12-by-10 rectangle with a 5-by-4 rectangle removed. Its area is $12 \\times 10 - 5 \\times 4 = 120 - 20 = 100$. Choice B is correct. Choice A is incorrect. This is the perimeter of the figure, not its area. Choice C is incorrect. This is the area of the full 12-by-10 rectangle; it does not remove the 5-by-4 corner. Choice D is incorrect. This adds the corner''s area instead of subtracting it."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('f4a0fd57-09e9-56da-e5c9-786fde1167d8','978612a1-1a5e-c55f-a23d-ab24bca46382','question_single_choice','{"prompt":"Each of the length, width, and height of a rectangular box is multiplied by $3$. The volume of the new box is how many times the volume of the original box?","options":[{"id":"A","label":"$3$"},{"id":"B","label":"$6$"},{"id":"C","label":"$9$"},{"id":"D","label":"$27$"}]}'::jsonb,10,'{"section_type":"math","sat_domain":"geometry_trig","sat_official_domain":"geometry_trigonometry","sat_skill":"area_and_volume","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"geo-area-010","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('f4a0fd57-09e9-56da-e5c9-786fde1167d8','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"If the dimensions are $l$, $w$, and $h$, the new volume is $(3l)(3w)(3h) = 27lwh$, which is 27 times the original volume. Choice D is correct. Choice A is incorrect. This multiplies only one dimension by 3; all three dimensions are multiplied. Choice B is incorrect. This adds the factor 3 twice instead of multiplying it three times. Choice C is incorrect. This is the factor by which the area of each face changes, $3^2$."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('1ef6e80e-a4ba-4ac8-8acb-419b99eafecb','978612a1-1a5e-c55f-a23d-ab24bca46382','question_spr','{"prompt":"A sphere has a volume of $36\\pi$ cubic centimeters. What is the radius of the sphere, in centimeters?"}'::jsonb,11,'{"section_type":"math","sat_domain":"geometry_trig","sat_official_domain":"geometry_trigonometry","sat_skill":"area_and_volume","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"geo-area-011","answer_format":"spr"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('1ef6e80e-a4ba-4ac8-8acb-419b99eafecb','{"accepted":["3"]}'::jsonb,'{"feedback":{"explanation":"The volume of a sphere is $\\frac{4}{3}\\pi r^3$. Setting $\\frac{4}{3}\\pi r^3 = 36\\pi$ gives $r^3 = 27$, so $r = 3$."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('e5450abc-c6d9-49e7-b5e7-8402bd80a67f','978612a1-1a5e-c55f-a23d-ab24bca46382','question_single_choice','{"prompt":"A right circular cone has a radius of $6$ inches, a height of $8$ inches, and a slant height of $10$ inches. What is the volume of the cone, in cubic inches?","options":[{"id":"A","label":"$16\\pi$"},{"id":"B","label":"$96\\pi$"},{"id":"C","label":"$120\\pi$"},{"id":"D","label":"$288\\pi$"}]}'::jsonb,12,'{"section_type":"math","sat_domain":"geometry_trig","sat_official_domain":"geometry_trigonometry","sat_skill":"area_and_volume","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"geo-area-012","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('e5450abc-c6d9-49e7-b5e7-8402bd80a67f','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"The volume of a cone is $\\frac{1}{3}\\pi r^2 h = \\frac{1}{3}\\pi(6)^2(8) = 96\\pi$ cubic inches. Choice B is correct. Choice A is incorrect. This uses the radius instead of the square of the radius. Choice C is incorrect. This uses the slant height, 10, in place of the height, 8. Choice D is incorrect. This is $\\pi r^2 h$, the volume of a cylinder; the cone''s volume includes a factor of $\\frac{1}{3}$."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('9c5f02bc-8c98-b6e6-32a1-bd7d427631d4','978612a1-1a5e-c55f-a23d-ab24bca46382','question_single_choice','{"prompt":"A trapezoid has parallel bases of lengths $10$ and $16$ and a height of $7$. What is the area of the trapezoid?","options":[{"id":"A","label":"$70$"},{"id":"B","label":"$91$"},{"id":"C","label":"$112$"},{"id":"D","label":"$182$"}]}'::jsonb,13,'{"section_type":"math","sat_domain":"geometry_trig","sat_official_domain":"geometry_trigonometry","sat_skill":"area_and_volume","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"geo-area-013","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('9c5f02bc-8c98-b6e6-32a1-bd7d427631d4','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"The area of a trapezoid is $\\frac{1}{2}(b_1 + b_2)h = \\frac{1}{2}(10 + 16)(7) = 91$. Choice B is correct. Choice A is incorrect. This uses only the shorter base. Choice C is incorrect. This uses only the longer base. Choice D is incorrect. This leaves out the factor of $\\frac{1}{2}$ in the trapezoid area formula."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('47f2f1e7-7427-3887-165b-dc1f0272244e','978612a1-1a5e-c55f-a23d-ab24bca46382','question_spr','{"prompt":"A rectangular tank has a base that is $40$ centimeters by $25$ centimeters. The tank contains water to a depth of $18$ centimeters. When a rock is placed in the tank and completely submerged, the water level rises to $21$ centimeters. What is the volume of the rock, in cubic centimeters?"}'::jsonb,14,'{"section_type":"math","sat_domain":"geometry_trig","sat_official_domain":"geometry_trigonometry","sat_skill":"area_and_volume","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"geo-area-014","answer_format":"spr"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('47f2f1e7-7427-3887-165b-dc1f0272244e','{"accepted":["3000"]}'::jsonb,'{"feedback":{"explanation":"The rock displaces water with a volume equal to its own. The water rises $21 - 18 = 3$ centimeters over a base of $40 \\times 25 = 1{,}000$ square centimeters, so the rock''s volume is $1{,}000 \\times 3 = 3{,}000$ cubic centimeters."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('3528b039-e1e5-66f3-462c-115f144962ba','978612a1-1a5e-c55f-a23d-ab24bca46382','question_single_choice','{"prompt":"A cube has a volume of $125$ cubic meters. What is the total surface area of the cube, in square meters?","options":[{"id":"A","label":"$25$"},{"id":"B","label":"$100$"},{"id":"C","label":"$125$"},{"id":"D","label":"$150$"}]}'::jsonb,15,'{"section_type":"math","sat_domain":"geometry_trig","sat_official_domain":"geometry_trigonometry","sat_skill":"area_and_volume","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"geo-area-015","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('3528b039-e1e5-66f3-462c-115f144962ba','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"The edge length is $\\sqrt[3]{125} = 5$ meters. Each face has area $5^2 = 25$ square meters, so the surface area is $6 \\times 25 = 150$ square meters. Choice D is correct. Choice A is incorrect. This is the area of one face; a cube has 6 faces. Choice B is incorrect. This counts only 4 of the cube''s 6 faces. Choice C is incorrect. This is the volume of the cube, not its surface area."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('61a132ac-8a27-ec62-a269-3298bf860b80','978612a1-1a5e-c55f-a23d-ab24bca46382','question_single_choice','{"prompt":"A right circular cylinder has a volume of $200\\pi$ cubic inches and a radius of $5$ inches. What is the height of the cylinder, in inches?","options":[{"id":"A","label":"$\\frac{8}{5}$"},{"id":"B","label":"$2$"},{"id":"C","label":"$4$"},{"id":"D","label":"$8$"}]}'::jsonb,16,'{"section_type":"math","sat_domain":"geometry_trig","sat_official_domain":"geometry_trigonometry","sat_skill":"area_and_volume","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"geo-area-016","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('61a132ac-8a27-ec62-a269-3298bf860b80','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"From $V = \\pi r^2 h$: $200\\pi = \\pi(5)^2 h = 25\\pi h$, so $h = \\frac{200}{25} = 8$ inches. Choice D is correct. Choice A is incorrect. This divides by $r^3$ instead of by $r^2$. Choice B is incorrect. This uses the diameter, 10, in place of the radius, dividing 200 by $10^2$. Choice C is incorrect. This divides by $2r^2$, as if the volume formula were $2\\pi r^2 h$."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('3e7f44c7-4c31-aee4-5821-ca4d7db130ee','978612a1-1a5e-c55f-a23d-ab24bca46382','question_single_choice','{"prompt":"A rectangular prism has a square base and a height of $5$ units. The volume of the prism is $180$ cubic units. What is the total surface area of the prism, in square units?","options":[{"id":"A","label":"$120$"},{"id":"B","label":"$132$"},{"id":"C","label":"$156$"},{"id":"D","label":"$192$"}]}'::jsonb,17,'{"section_type":"math","sat_domain":"geometry_trig","sat_official_domain":"geometry_trigonometry","sat_skill":"area_and_volume","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"geo-area-017","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('3e7f44c7-4c31-aee4-5821-ca4d7db130ee','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"The base area is $\\frac{180}{5} = 36$, so each side of the base is 6. The surface area is two bases plus four rectangular sides: $2(36) + 4(6 \\times 5) = 72 + 120 = 192$. Choice D is correct. Choice A is incorrect. This is the lateral area only; it leaves out the two square bases. Choice B is incorrect. This includes only two of the four rectangular faces. Choice C is incorrect. This includes only one of the two square bases."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('c037fdcc-f291-2dbb-6ccc-7a771b81bc60','978612a1-1a5e-c55f-a23d-ab24bca46382','question_single_choice','{"prompt":"Two right circular cylinders are similar. The ratio of the radius of the smaller cylinder to the radius of the larger cylinder is $2 : 3$. The volume of the smaller cylinder is $48\\pi$ cubic centimeters. What is the volume of the larger cylinder, in cubic centimeters?","options":[{"id":"A","label":"$72\\pi$"},{"id":"B","label":"$96\\pi$"},{"id":"C","label":"$108\\pi$"},{"id":"D","label":"$162\\pi$"}]}'::jsonb,18,'{"section_type":"math","sat_domain":"geometry_trig","sat_official_domain":"geometry_trigonometry","sat_skill":"area_and_volume","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"geo-area-018","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('c037fdcc-f291-2dbb-6ccc-7a771b81bc60','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"For similar solids, volumes scale by the cube of the scale factor. The scale factor from small to large is $\\frac{3}{2}$, so the larger volume is $48\\pi \\left(\\frac{3}{2}\\right)^3 = 48\\pi \\cdot \\frac{27}{8} = 162\\pi$ cubic centimeters. Choice D is correct. Choice A is incorrect. This scales the volume by the linear ratio $\\frac{3}{2}$; volumes scale by the cube of that ratio. Choice B is incorrect. This doubles the volume, which does not use the given ratio. Choice C is incorrect. This scales the volume by the square of the ratio, which is how areas scale."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('db4c23bb-19d3-236a-e18f-a12a812a5227','978612a1-1a5e-c55f-a23d-ab24bca46382','question_spr','{"prompt":"A container is shaped like a right circular cone with its vertex pointing down. The cone has a radius of $6$ inches and a height of $12$ inches. Water fills the container to a depth of $8$ inches. The volume of the water is $k\\pi$ cubic inches. What is the value of $k$?"}'::jsonb,19,'{"section_type":"math","sat_domain":"geometry_trig","sat_official_domain":"geometry_trigonometry","sat_skill":"area_and_volume","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"geo-area-019","answer_format":"spr"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('db4c23bb-19d3-236a-e18f-a12a812a5227','{"accepted":["128/3","42.66","42.67"]}'::jsonb,'{"feedback":{"explanation":"The water forms a smaller cone similar to the container. Its radius is $6 \\cdot \\frac{8}{12} = 4$ inches. Its volume is $\\frac{1}{3}\\pi(4)^2(8) = \\frac{128}{3}\\pi$, so $k = \\frac{128}{3}$, or about 42.67."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('949232ec-680b-bc9d-cfc1-876f65888f32','978612a1-1a5e-c55f-a23d-ab24bca46382','question_single_choice','{"prompt":"In the figure, a square is inscribed in a circle with radius $5$. What is the area of the region inside the circle but outside the square?","figure_svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 360 300\" width=\"360\" height=\"300\" font-family=\"Arial, Helvetica, sans-serif\" font-size=\"17\" role=\"img\"><title>Square with all four vertices on a circle; a radius of length 5 is drawn from the center to a vertex.</title><rect x=\"0\" y=\"0\" width=\"360\" height=\"300\" fill=\"#ffffff\"/><circle cx=\"180\" cy=\"150\" r=\"110\" fill=\"none\" stroke=\"#1f2937\" stroke-width=\"2\"/><polygon points=\"257.78,227.78 102.22,227.78 102.22,72.22 257.78,72.22\" fill=\"none\" stroke=\"#1f2937\" stroke-width=\"2\" stroke-linejoin=\"round\"/><circle cx=\"180\" cy=\"150\" r=\"3\" fill=\"#1f2937\"/><line x1=\"180\" y1=\"150\" x2=\"257.78\" y2=\"227.78\" stroke=\"#1f2937\" stroke-width=\"1.5\"/><text x=\"227.38\" y=\"185.41\" text-anchor=\"middle\" fill=\"#1f2937\">5</text></svg>","options":[{"id":"A","label":"$25\\pi - 100$"},{"id":"B","label":"$100 - 25\\pi$"},{"id":"C","label":"$25\\pi - 50$"},{"id":"D","label":"$25\\pi - 25$"}]}'::jsonb,20,'{"section_type":"math","sat_domain":"geometry_trig","sat_official_domain":"geometry_trigonometry","sat_skill":"area_and_volume","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"geo-area-020","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('949232ec-680b-bc9d-cfc1-876f65888f32','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"The diagonal of the square is a diameter, 10. A square with diagonal 10 has side $\\frac{10}{\\sqrt{2}} = 5\\sqrt{2}$ and area $(5\\sqrt{2})^2 = 50$. The circle''s area is $25\\pi$, so the region has area $25\\pi - 50$. Choice C is correct. Choice A is incorrect. This uses 100 for the square''s area, as if its side were the diameter 10; the diameter is the square''s diagonal. Choice B is incorrect. This subtracts the circle''s area from the area of a square with side 10, which is the square circumscribed about the circle. Choice D is incorrect. This uses 25 for the square''s area, as if its side were the radius 5; the side is $5\\sqrt{2}$."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('66d0cd46-d490-0e50-9b40-1238987acc35','978612a1-1a5e-c55f-a23d-ab24bca46382','question_single_choice','{"prompt":"A regular hexagon has a side length of $6$. What is the area of the hexagon?","options":[{"id":"A","label":"$9\\sqrt{3}$"},{"id":"B","label":"$54\\sqrt{3}$"},{"id":"C","label":"$108\\sqrt{3}$"},{"id":"D","label":"$216$"}]}'::jsonb,21,'{"section_type":"math","sat_domain":"geometry_trig","sat_official_domain":"geometry_trigonometry","sat_skill":"area_and_volume","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"geo-area-021","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('66d0cd46-d490-0e50-9b40-1238987acc35','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"A regular hexagon with side 6 can be divided into 6 equilateral triangles with side 6. Each triangle has area $\\frac{\\sqrt{3}}{4}(6)^2 = 9\\sqrt{3}$, so the hexagon''s area is $6 \\times 9\\sqrt{3} = 54\\sqrt{3}$. Choice B is correct. Choice A is incorrect. This is the area of just one of the six equilateral triangles that make up the hexagon. Choice C is incorrect. This finds each triangle''s area as base times height without the factor of $\\frac{1}{2}$. Choice D is incorrect. This treats the hexagon as six squares with side 6."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('01176054-1217-f919-11b2-e839e8f941c0','978612a1-1a5e-c55f-a23d-ab24bca46382','question_spr','{"prompt":"A right pyramid has a square base with side length $10$ meters. The slant height of each triangular face, measured from the midpoint of a base edge to the apex, is $13$ meters. What is the volume of the pyramid, in cubic meters?"}'::jsonb,22,'{"section_type":"math","sat_domain":"geometry_trig","sat_official_domain":"geometry_trigonometry","sat_skill":"area_and_volume","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"geo-area-022","answer_format":"spr"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('01176054-1217-f919-11b2-e839e8f941c0','{"accepted":["400"]}'::jsonb,'{"feedback":{"explanation":"The height, half the base side (5), and the slant height (13) form a right triangle, so the height is $\\sqrt{13^2 - 5^2} = 12$ meters. The volume is $\\frac{1}{3}(10^2)(12) = 400$ cubic meters."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('6d21121c-42a2-08df-26a0-0f3d4a6480e0','978612a1-1a5e-c55f-a23d-ab24bca46382','question_single_choice','{"prompt":"A sphere and a right circular cylinder have the same radius $r$ and the same volume. Which expression represents the height of the cylinder in terms of $r$?","options":[{"id":"A","label":"$\\frac{r}{3}$"},{"id":"B","label":"$\\frac{3r}{4}$"},{"id":"C","label":"$\\frac{4r}{3}$"},{"id":"D","label":"$2r$"}]}'::jsonb,23,'{"section_type":"math","sat_domain":"geometry_trig","sat_official_domain":"geometry_trigonometry","sat_skill":"area_and_volume","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"geo-area-023","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('6d21121c-42a2-08df-26a0-0f3d4a6480e0','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"Set the volumes equal: $\\pi r^2 h = \\frac{4}{3}\\pi r^3$. Dividing both sides by $\\pi r^2$ gives $h = \\frac{4}{3}r$. Choice C is correct. Choice A is incorrect. This drops the factor of 4 from the sphere volume formula. Choice B is incorrect. This inverts the ratio when solving $\\pi r^2 h = \\frac{4}{3}\\pi r^3$. Choice D is incorrect. This is the height of a cylinder that just encloses the sphere, which has a greater volume than the sphere."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('10263a29-5fde-18f0-a336-956a32b9a7b5','978612a1-1a5e-c55f-a23d-ab24bca46382','question_single_choice','{"prompt":"In the figure, line $\\ell$ is parallel to line $m$. What is the value of $x$?","figure_svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 420 300\" width=\"420\" height=\"300\" font-family=\"Arial, Helvetica, sans-serif\" font-size=\"17\" role=\"img\"><title>Two parallel horizontal lines l and m cut by a transversal; the upper angle is labeled 65 degrees and an angle at the lower intersection is labeled x degrees.</title><rect x=\"0\" y=\"0\" width=\"420\" height=\"300\" fill=\"#ffffff\"/><line x1=\"20\" y1=\"90\" x2=\"396\" y2=\"90\" stroke=\"#1f2937\" stroke-width=\"2\"/><line x1=\"20\" y1=\"210\" x2=\"396\" y2=\"210\" stroke=\"#1f2937\" stroke-width=\"2\"/><line x1=\"150\" y1=\"280\" x2=\"271.24\" y2=\"20\" stroke=\"#1f2937\" stroke-width=\"2\"/><text x=\"404\" y=\"96\" font-style=\"italic\" fill=\"#1f2937\">ℓ</text><text x=\"404\" y=\"216\" font-style=\"italic\" fill=\"#1f2937\">m</text><path d=\"M247.05,71.87 A20,20 0 0 1 258.6,90\" fill=\"none\" stroke=\"#1f2937\" stroke-width=\"1.2\"/><text x=\"270.65\" y=\"74.58\" text-anchor=\"middle\" fill=\"#1f2937\">65°</text><path d=\"M202.64,210 A20,20 0 0 1 174.19,228.13\" fill=\"none\" stroke=\"#1f2937\" stroke-width=\"1.2\"/><text x=\"204.13\" y=\"248.74\" text-anchor=\"middle\" fill=\"#1f2937\">x°</text></svg>","options":[{"id":"A","label":"$25$"},{"id":"B","label":"$50$"},{"id":"C","label":"$65$"},{"id":"D","label":"$115$"}]}'::jsonb,24,'{"section_type":"math","sat_domain":"geometry_trig","sat_official_domain":"geometry_trigonometry","sat_skill":"lines_angles_triangles","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"geo-lines-001","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('10263a29-5fde-18f0-a336-956a32b9a7b5','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"At the lower intersection, the angle between line $m$ (to the right) and the transversal (going up) corresponds to the 65° angle, so it also measures 65°. That angle and the angle marked $x°$ form a linear pair, so $x = 180 - 65 = 115$. Choice D is correct. Choice A is incorrect. This finds the complement of 65°, but the angles form a linear pair relationship, not a right angle. Choice B is incorrect. This subtracts 65° twice from 180°, as if two 65° angles and the angle marked $x°$ formed a straight angle. Choice C is incorrect. This assumes the two marked angles are congruent, but they are on opposite sides of the transversal relative to the parallel lines, so they are supplementary."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('1a777233-1ff4-bc1d-86c7-1de5fb1fad9b','978612a1-1a5e-c55f-a23d-ab24bca46382','question_spr','{"prompt":"Two angles of a triangle measure $48°$ and $67°$. What is the measure, in degrees, of the third angle?"}'::jsonb,25,'{"section_type":"math","sat_domain":"geometry_trig","sat_official_domain":"geometry_trigonometry","sat_skill":"lines_angles_triangles","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"geo-lines-002","answer_format":"spr"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('1a777233-1ff4-bc1d-86c7-1de5fb1fad9b','{"accepted":["65"]}'::jsonb,'{"feedback":{"explanation":"The angles of a triangle add to $180°$, so the third angle measures $180 - 48 - 67 = 65$ degrees."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('a72db2af-0ad9-3a5d-cd8c-1baa7dd4faab','978612a1-1a5e-c55f-a23d-ab24bca46382','question_single_choice','{"prompt":"Two lines intersect, forming a pair of vertical angles with measures $(3x + 10)°$ and $(5x - 20)°$. What is the value of $x$?","options":[{"id":"A","label":"$5$"},{"id":"B","label":"$15$"},{"id":"C","label":"$23.75$"},{"id":"D","label":"$55$"}]}'::jsonb,26,'{"section_type":"math","sat_domain":"geometry_trig","sat_official_domain":"geometry_trigonometry","sat_skill":"lines_angles_triangles","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"geo-lines-003","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('a72db2af-0ad9-3a5d-cd8c-1baa7dd4faab','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"Vertical angles are congruent, so $3x + 10 = 5x - 20$. Then $30 = 2x$ and $x = 15$. Choice B is correct. Choice A is incorrect. This combines the constants incorrectly, using $2x = 20 - 10$ instead of $2x = 10 + 20$. Choice C is incorrect. This treats the angles as supplementary, but vertical angles are congruent. Choice D is incorrect. This is the measure of each angle, not the value of $x$."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('9f8d9711-f61f-41cc-4abe-bfaf674c0b7d','978612a1-1a5e-c55f-a23d-ab24bca46382','question_single_choice','{"prompt":"In isosceles triangle $ABC$, $AB = AC$ and the measure of angle $A$ is $40°$. What is the measure of angle $B$?","options":[{"id":"A","label":"$40^\\circ$"},{"id":"B","label":"$70^\\circ$"},{"id":"C","label":"$100^\\circ$"},{"id":"D","label":"$140^\\circ$"}]}'::jsonb,27,'{"section_type":"math","sat_domain":"geometry_trig","sat_official_domain":"geometry_trigonometry","sat_skill":"lines_angles_triangles","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"geo-lines-004","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('9f8d9711-f61f-41cc-4abe-bfaf674c0b7d','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"Since $AB = AC$, the base angles $B$ and $C$ are congruent. Each measures $\\frac{180 - 40}{2} = 70°$. Choice B is correct. Choice A is incorrect. Angle $B$ is a base angle; it is not congruent to the vertex angle $A$. Choice C is incorrect. This assumes angle $B$ equals angle $A$ and finds angle $C$ from that. Choice D is incorrect. This is the sum of the two base angles, not the measure of one of them."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('f8c5e388-d7db-ab95-3fe4-683fa93b0d20','978612a1-1a5e-c55f-a23d-ab24bca46382','question_spr','{"prompt":"Three angles together form a straight angle. Their measures are $x°$, $2x°$, and $3x°$. What is the value of $x$?"}'::jsonb,28,'{"section_type":"math","sat_domain":"geometry_trig","sat_official_domain":"geometry_trigonometry","sat_skill":"lines_angles_triangles","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"geo-lines-005","answer_format":"spr"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('f8c5e388-d7db-ab95-3fe4-683fa93b0d20','{"accepted":["30"]}'::jsonb,'{"feedback":{"explanation":"The angles add to $180°$, so $x + 2x + 3x = 6x = 180$, and $x = 30$."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('736c7e4e-a44d-eed4-bab1-f1d7117c5ce0','978612a1-1a5e-c55f-a23d-ab24bca46382','question_single_choice','{"prompt":"An exterior angle of a triangle measures $120°$. One of the two interior angles not adjacent to it measures $45°$. What is the measure of the other nonadjacent interior angle?","options":[{"id":"A","label":"$45^\\circ$"},{"id":"B","label":"$60^\\circ$"},{"id":"C","label":"$75^\\circ$"},{"id":"D","label":"$135^\\circ$"}]}'::jsonb,29,'{"section_type":"math","sat_domain":"geometry_trig","sat_official_domain":"geometry_trigonometry","sat_skill":"lines_angles_triangles","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"geo-lines-006","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('736c7e4e-a44d-eed4-bab1-f1d7117c5ce0','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"An exterior angle equals the sum of the two nonadjacent interior angles. So the other angle measures $120 - 45 = 75°$. Choice C is correct. Choice A is incorrect. This assumes the two nonadjacent interior angles are congruent. Choice B is incorrect. This is the interior angle adjacent to the exterior angle. Choice D is incorrect. This finds the supplement of 45°, which is not one of the triangle''s angles here."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('01e43cce-ae9d-fec3-35aa-2f00b53f09d4','978612a1-1a5e-c55f-a23d-ab24bca46382','question_single_choice','{"prompt":"Triangle $ABC$ is similar to triangle $DEF$, where $A$, $B$, and $C$ correspond to $D$, $E$, and $F$, respectively. If $AB = 6$, $BC = 8$, and $DE = 9$, what is $EF$?","options":[{"id":"A","label":"$\\frac{16}{3}$"},{"id":"B","label":"$6.75$"},{"id":"C","label":"$11$"},{"id":"D","label":"$12$"}]}'::jsonb,30,'{"section_type":"math","sat_domain":"geometry_trig","sat_official_domain":"geometry_trigonometry","sat_skill":"lines_angles_triangles","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"geo-lines-007","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('01e43cce-ae9d-fec3-35aa-2f00b53f09d4','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"The scale factor from $ABC$ to $DEF$ is $\\frac{DE}{AB} = \\frac{9}{6} = 1.5$. So $EF = 1.5 \\times 8 = 12$. Choice D is correct. Choice A is incorrect. This inverts the scale factor, multiplying by $\\frac{6}{9}$ instead of $\\frac{9}{6}$. Choice B is incorrect. This matches $\\overline{AB}$ with $\\overline{EF}$ instead of with $\\overline{DE}$, computing $\\frac{6 \\cdot 9}{8}$. Choice C is incorrect. This adds the difference $9 - 6$ instead of multiplying by the scale factor."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('aa7ccf35-c40c-3808-2aa5-dfae2b87e150','978612a1-1a5e-c55f-a23d-ab24bca46382','question_single_choice','{"prompt":"What is the sum of the measures of the interior angles of a hexagon?","options":[{"id":"A","label":"$540^\\circ$"},{"id":"B","label":"$720^\\circ$"},{"id":"C","label":"$900^\\circ$"},{"id":"D","label":"$1{,}080^\\circ$"}]}'::jsonb,31,'{"section_type":"math","sat_domain":"geometry_trig","sat_official_domain":"geometry_trigonometry","sat_skill":"lines_angles_triangles","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"geo-lines-008","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('aa7ccf35-c40c-3808-2aa5-dfae2b87e150','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"A polygon with $n$ sides can be divided into $n - 2$ triangles, so the angle sum is $(n - 2) \\cdot 180°$. For a hexagon, $(6 - 2)(180°) = 720°$. Choice B is correct. Choice A is incorrect. This is the angle sum of a pentagon, which has 5 sides. Choice C is incorrect. This is the angle sum of a heptagon, which has 7 sides. Choice D is incorrect. This multiplies 180° by 6 instead of by $6 - 2$."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('a058f277-04d9-456a-cf27-f000ede89edb','978612a1-1a5e-c55f-a23d-ab24bca46382','question_single_choice','{"prompt":"In the figure, $\\overline{DE}$ is parallel to $\\overline{BC}$. What is the length of $\\overline{EC}$? Note: Figure not drawn to scale.","figure_svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 420 290\" width=\"420\" height=\"290\" font-family=\"Arial, Helvetica, sans-serif\" font-size=\"17\" role=\"img\"><title>Triangle ABC with segment DE parallel to BC; D is on AB and E is on AC. AD = 4, DB = 6, AE = 5.</title><rect x=\"0\" y=\"0\" width=\"420\" height=\"290\" fill=\"#ffffff\"/><polygon points=\"200,30 60,250 360,250\" fill=\"none\" stroke=\"#1f2937\" stroke-width=\"2\" stroke-linejoin=\"round\"/><line x1=\"144\" y1=\"118\" x2=\"264\" y2=\"118\" stroke=\"#1f2937\" stroke-width=\"2\"/><text x=\"200\" y=\"22\" text-anchor=\"middle\" fill=\"#1f2937\">A</text><text x=\"48\" y=\"256\" text-anchor=\"middle\" fill=\"#1f2937\">B</text><text x=\"372\" y=\"256\" text-anchor=\"middle\" fill=\"#1f2937\">C</text><text x=\"130\" y=\"122\" text-anchor=\"middle\" fill=\"#1f2937\">D</text><text x=\"278\" y=\"122\" text-anchor=\"middle\" fill=\"#1f2937\">E</text><text x=\"160.19\" y=\"71.48\" text-anchor=\"middle\" fill=\"#1f2937\">4</text><text x=\"90.19\" y=\"181.48\" text-anchor=\"middle\" fill=\"#1f2937\">6</text><text x=\"243.32\" y=\"70.77\" text-anchor=\"middle\" fill=\"#1f2937\">5</text></svg>","options":[{"id":"A","label":"$\\frac{10}{3}$"},{"id":"B","label":"$4.8$"},{"id":"C","label":"$\\frac{15}{2}$"},{"id":"D","label":"$\\frac{25}{2}$"}]}'::jsonb,32,'{"section_type":"math","sat_domain":"geometry_trig","sat_official_domain":"geometry_trigonometry","sat_skill":"lines_angles_triangles","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"geo-lines-009","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('a058f277-04d9-456a-cf27-f000ede89edb','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"Because $\\overline{DE} \\parallel \\overline{BC}$, the segment divides the two sides proportionally: $\\frac{AD}{DB} = \\frac{AE}{EC}$. So $\\frac{4}{6} = \\frac{5}{EC}$ and $EC = \\frac{30}{4} = 7.5$. Choice C is correct. Choice A is incorrect. This sets up the proportion with $AD$ and $DB$ in the wrong places, $\\frac{6}{4} = \\frac{5}{EC}$. Choice B is incorrect. This multiplies $DB$ by $AD$ and divides by $AE$, which does not match corresponding parts. Choice D is incorrect. This is the length of $\\overline{AC}$, found from $\\frac{AD}{AB} = \\frac{AE}{AC}$, not the length of $\\overline{EC}$."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('fad3508e-003c-58d2-4e41-b446dddad4e6','978612a1-1a5e-c55f-a23d-ab24bca46382','question_spr','{"prompt":"At the same time of day, a person who is $1.8$ meters tall casts a shadow $2.4$ meters long, and a tree casts a shadow $16$ meters long. What is the height of the tree, in meters?"}'::jsonb,33,'{"section_type":"math","sat_domain":"geometry_trig","sat_official_domain":"geometry_trigonometry","sat_skill":"lines_angles_triangles","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"geo-lines-010","answer_format":"spr"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('fad3508e-003c-58d2-4e41-b446dddad4e6','{"accepted":["12"]}'::jsonb,'{"feedback":{"explanation":"The sun''s rays make similar right triangles, so $\\frac{\\text{height}}{\\text{shadow}}$ is the same: $\\frac{1.8}{2.4} = \\frac{h}{16}$. Then $h = 16 \\times 0.75 = 12$ meters."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('6a2bcd24-ff24-dadd-a2f3-54c3f861cd11','978612a1-1a5e-c55f-a23d-ab24bca46382','question_single_choice','{"prompt":"Each interior angle of a regular polygon measures $140°$. How many sides does the polygon have?","options":[{"id":"A","label":"$9$"},{"id":"B","label":"$10$"},{"id":"C","label":"$11$"},{"id":"D","label":"$12$"}]}'::jsonb,34,'{"section_type":"math","sat_domain":"geometry_trig","sat_official_domain":"geometry_trigonometry","sat_skill":"lines_angles_triangles","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"geo-lines-011","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('6a2bcd24-ff24-dadd-a2f3-54c3f861cd11','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"Each exterior angle measures $180 - 140 = 40°$, and the exterior angles of a polygon add to $360°$. So the polygon has $\\frac{360}{40} = 9$ sides. Choice A is correct. Choice B is incorrect. A regular decagon has interior angles of $180 - 36 = 144°$. Choice C is incorrect. A regular polygon with 11 sides has interior angles of about 147.3°. Choice D is incorrect. A regular dodecagon has interior angles of $180 - 30 = 150°$."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('b2bfa898-0075-8623-f471-c0822669d0c1','978612a1-1a5e-c55f-a23d-ab24bca46382','question_single_choice','{"prompt":"Two sides of a triangle have lengths $7$ and $12$. Which of the following could be the length of the third side?","options":[{"id":"A","label":"$2$"},{"id":"B","label":"$4$"},{"id":"C","label":"$5$"},{"id":"D","label":"$18$"}]}'::jsonb,35,'{"section_type":"math","sat_domain":"geometry_trig","sat_official_domain":"geometry_trigonometry","sat_skill":"lines_angles_triangles","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"geo-lines-012","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('b2bfa898-0075-8623-f471-c0822669d0c1','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"By the triangle inequality, the third side $s$ must satisfy $12 - 7 < s < 12 + 7$, or $5 < s < 19$. Only 18 is in this range. Choice D is correct. Choice A is incorrect. A side of length 2 would be too short: $7 + 2 = 9$, which is less than 12. Choice B is incorrect. A side of length 4 would be too short: $7 + 4 = 11$, which is less than 12. Choice C is incorrect. A side of length 5 would make $7 + 5 = 12$, equal to the third side, so the triangle would collapse into a segment."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('51221952-efa4-464c-8139-26ae0322a451','978612a1-1a5e-c55f-a23d-ab24bca46382','question_single_choice','{"prompt":"A transversal intersects two parallel lines, forming alternate interior angles with measures $(2x + 15)°$ and $(3x - 40)°$. What is the measure of one of these angles, in degrees?","options":[{"id":"A","label":"$41$"},{"id":"B","label":"$55$"},{"id":"C","label":"$97$"},{"id":"D","label":"$125$"}]}'::jsonb,36,'{"section_type":"math","sat_domain":"geometry_trig","sat_official_domain":"geometry_trigonometry","sat_skill":"lines_angles_triangles","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"geo-lines-013","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('51221952-efa4-464c-8139-26ae0322a451','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"Alternate interior angles formed by parallel lines are congruent: $2x + 15 = 3x - 40$, so $x = 55$. Each angle measures $2(55) + 15 = 125°$. Choice D is correct. Choice A is incorrect. This is the value of $x$ when the angles are treated as supplementary; alternate interior angles are congruent. Choice B is incorrect. This is the value of $x$, not the measure of the angle. Choice C is incorrect. This is the angle measure that results from treating the angles as supplementary."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('e4b97adc-83f8-d20a-0e7d-c6e6d54f4e44','978612a1-1a5e-c55f-a23d-ab24bca46382','question_single_choice','{"prompt":"In triangle $ABC$, $AB = AC$. The measure of angle $B$ is $(3x + 5)°$ and the measure of angle $C$ is $(5x - 25)°$. What is the measure of angle $A$?","options":[{"id":"A","label":"$50^\\circ$"},{"id":"B","label":"$80^\\circ$"},{"id":"C","label":"$100^\\circ$"},{"id":"D","label":"$130^\\circ$"}]}'::jsonb,37,'{"section_type":"math","sat_domain":"geometry_trig","sat_official_domain":"geometry_trigonometry","sat_skill":"lines_angles_triangles","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"geo-lines-014","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('e4b97adc-83f8-d20a-0e7d-c6e6d54f4e44','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"Since $AB = AC$, angles $B$ and $C$ are congruent: $3x + 5 = 5x - 25$, so $x = 15$ and each base angle is $50°$. Then angle $A$ measures $180 - 2(50) = 80°$. Choice B is correct. Choice A is incorrect. This is the measure of angle $B$ (and angle $C$), not angle $A$. Choice C is incorrect. This is the sum of the two base angles, not the measure of angle $A$. Choice D is incorrect. This subtracts only one base angle from 180°."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('5231f621-fb0e-23df-86e9-fd2b92d959cf','978612a1-1a5e-c55f-a23d-ab24bca46382','question_spr','{"prompt":"Two triangles are similar. A side of the smaller triangle has length $4$, and the corresponding side of the larger triangle has length $10$. The area of the smaller triangle is $12$. What is the area of the larger triangle?"}'::jsonb,38,'{"section_type":"math","sat_domain":"geometry_trig","sat_official_domain":"geometry_trigonometry","sat_skill":"lines_angles_triangles","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"geo-lines-015","answer_format":"spr"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('5231f621-fb0e-23df-86e9-fd2b92d959cf','{"accepted":["75"]}'::jsonb,'{"feedback":{"explanation":"The scale factor is $\\frac{10}{4} = 2.5$, and areas scale by the square of the scale factor: $12 \\times 2.5^2 = 12 \\times 6.25 = 75$."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('9e4df1cf-5ce1-c596-401f-e48e374611e6','978612a1-1a5e-c55f-a23d-ab24bca46382','question_single_choice','{"prompt":"In the figure, line $j$ is parallel to line $k$. What is the value of $x$?","figure_svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 420 290\" width=\"420\" height=\"290\" font-family=\"Arial, Helvetica, sans-serif\" font-size=\"17\" role=\"img\"><title>Two parallel horizontal lines j and k with a point P between them. Segments from P meet line j at a 38 degree angle and line k at a 47 degree angle; the angle at P is labeled x degrees.</title><rect x=\"0\" y=\"0\" width=\"420\" height=\"290\" fill=\"#ffffff\"/><line x1=\"20\" y1=\"60\" x2=\"396\" y2=\"60\" stroke=\"#1f2937\" stroke-width=\"2\"/><line x1=\"20\" y1=\"240\" x2=\"396\" y2=\"240\" stroke=\"#1f2937\" stroke-width=\"2\"/><polyline points=\"144.81,60 260,150 176.07,240\" fill=\"none\" stroke=\"#1f2937\" stroke-width=\"2\" stroke-linejoin=\"round\"/><text x=\"404\" y=\"66\" font-style=\"italic\" fill=\"#1f2937\">j</text><text x=\"404\" y=\"246\" font-style=\"italic\" fill=\"#1f2937\">k</text><path d=\"M170.81,60 A26,26 0 0 1 165.29,76.01\" fill=\"none\" stroke=\"#1f2937\" stroke-width=\"1.2\"/><text x=\"190.19\" y=\"80.63\" text-anchor=\"middle\" fill=\"#1f2937\">38°</text><path d=\"M193.81,220.98 A26,26 0 0 1 202.07,240\" fill=\"none\" stroke=\"#1f2937\" stroke-width=\"1.2\"/><text x=\"220.09\" y=\"225.86\" text-anchor=\"middle\" fill=\"#1f2937\">47°</text><path d=\"M246.36,164.63 A20,20 0 0 1 244.24,137.69\" fill=\"none\" stroke=\"#1f2937\" stroke-width=\"1.2\"/><text x=\"226\" y=\"155\" text-anchor=\"middle\" fill=\"#1f2937\">x°</text><text x=\"270\" y=\"155\" fill=\"#1f2937\">P</text></svg>","options":[{"id":"A","label":"$47$"},{"id":"B","label":"$85$"},{"id":"C","label":"$95$"},{"id":"D","label":"$133$"}]}'::jsonb,39,'{"section_type":"math","sat_domain":"geometry_trig","sat_official_domain":"geometry_trigonometry","sat_skill":"lines_angles_triangles","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"geo-lines-016","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('9e4df1cf-5ce1-c596-401f-e48e374611e6','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"Draw a line through $P$ parallel to $j$ and $k$. It splits the angle at $P$ into two parts that are alternate interior angles with the 38° and 47° angles. So $x = 38 + 47 = 85$. Choice B is correct. Choice A is incorrect. This uses only one of the two given angles. Choice C is incorrect. This finds the supplement of the correct angle. Choice D is incorrect. This is the supplement of 47°, which is not the angle at $P$."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('35a92260-88b1-f4a9-3f97-461163a274d5','978612a1-1a5e-c55f-a23d-ab24bca46382','question_single_choice','{"prompt":"In triangle $PQR$, the measure of angle $P$ is $30°$ greater than the measure of angle $Q$, and the measure of angle $R$ is twice the measure of angle $Q$. What is the measure of angle $R$?","options":[{"id":"A","label":"$37.5^\\circ$"},{"id":"B","label":"$67.5^\\circ$"},{"id":"C","label":"$75^\\circ$"},{"id":"D","label":"$90^\\circ$"}]}'::jsonb,40,'{"section_type":"math","sat_domain":"geometry_trig","sat_official_domain":"geometry_trigonometry","sat_skill":"lines_angles_triangles","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"geo-lines-017","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('35a92260-88b1-f4a9-3f97-461163a274d5','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"Let angle $Q$ measure $q$. Then $q + (q + 30) + 2q = 180$, so $4q = 150$ and $q = 37.5$. Angle $R$ measures $2(37.5) = 75°$. Choice C is correct. Choice A is incorrect. This is the measure of angle $Q$. Choice B is incorrect. This is the measure of angle $P$. Choice D is incorrect. This assumes the triangle is a right triangle, which is not given."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('ed497637-2441-ddb9-6080-9928c1934369','978612a1-1a5e-c55f-a23d-ab24bca46382','question_single_choice','{"prompt":"In the figure, point $D$ lies on $\\overline{AB}$, point $E$ lies on $\\overline{AC}$, and angle $ADE$ is congruent to angle $ACB$. If $AD = 4$, $AE = 6$, and $AC = 12$, what is the length of $\\overline{DB}$?","figure_svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 400 280\" width=\"400\" height=\"280\" font-family=\"Arial, Helvetica, sans-serif\" font-size=\"17\" role=\"img\"><title>Triangle ABC with D on side AB and E on side AC. Segment DE is drawn. Angle ADE and angle ACB are marked congruent. AD = 4, AE = 6, AC = 12.</title><rect x=\"0\" y=\"0\" width=\"400\" height=\"280\" fill=\"#ffffff\"/><polygon points=\"40,240 364,240 178.84,74.53\" fill=\"none\" stroke=\"#1f2937\" stroke-width=\"2\" stroke-linejoin=\"round\"/><line x1=\"112\" y1=\"240\" x2=\"109.42\" y2=\"157.27\" stroke=\"#1f2937\" stroke-width=\"2\"/><text x=\"30\" y=\"258\" text-anchor=\"middle\" fill=\"#1f2937\">A</text><text x=\"374\" y=\"258\" text-anchor=\"middle\" fill=\"#1f2937\">B</text><text x=\"178.84\" y=\"64.53\" text-anchor=\"middle\" fill=\"#1f2937\">C</text><text x=\"112\" y=\"260\" text-anchor=\"middle\" fill=\"#1f2937\">D</text><text x=\"95.42\" y=\"157.27\" text-anchor=\"middle\" fill=\"#1f2937\">E</text><path d=\"M96,240 A16,16 0 0 1 111.5,224.01\" fill=\"none\" stroke=\"#1f2937\" stroke-width=\"1.2\"/><path d=\"M195.25,89.19 A22,22 0 0 1 164.7,91.39\" fill=\"none\" stroke=\"#1f2937\" stroke-width=\"1.2\"/><text x=\"76\" y=\"261\" text-anchor=\"middle\" fill=\"#1f2937\">4</text><text x=\"63.99\" y=\"194.63\" text-anchor=\"middle\" fill=\"#1f2937\">6</text><text x=\"133.41\" y=\"111.9\" text-anchor=\"middle\" fill=\"#1f2937\">6</text></svg>","options":[{"id":"A","label":"$4$"},{"id":"B","label":"$8$"},{"id":"C","label":"$14$"},{"id":"D","label":"$18$"}]}'::jsonb,41,'{"section_type":"math","sat_domain":"geometry_trig","sat_official_domain":"geometry_trigonometry","sat_skill":"lines_angles_triangles","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"geo-lines-018","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('ed497637-2441-ddb9-6080-9928c1934369','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"Triangles $ADE$ and $ACB$ share angle $A$, and angle $ADE \\cong$ angle $ACB$, so triangle $ADE \\sim$ triangle $ACB$ with $D \\leftrightarrow C$ and $E \\leftrightarrow B$. Then $\\frac{AD}{AC} = \\frac{AE}{AB}$, so $\\frac{4}{12} = \\frac{6}{AB}$ and $AB = 18$. Therefore $DB = 18 - 4 = 14$. Choice C is correct. Choice A is incorrect. This assumes $\\overline{DE}$ is parallel to $\\overline{BC}$, but the congruent angles make $D$ correspond to $C$, not to $B$. Choice B is incorrect. This is the length of $\\overline{AB}$ under the incorrect assumption that $\\overline{DE} \\parallel \\overline{BC}$. Choice D is incorrect. This is the length of $\\overline{AB}$; the length of $\\overline{DB}$ is $AB - AD$."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('85fca509-ec34-8415-ae18-5bd68cc667bc','978612a1-1a5e-c55f-a23d-ab24bca46382','question_single_choice','{"prompt":"Each exterior angle of a regular polygon measures $24°$. What is the sum of the measures of the interior angles of the polygon?","options":[{"id":"A","label":"$156^\\circ$"},{"id":"B","label":"$2{,}160^\\circ$"},{"id":"C","label":"$2{,}340^\\circ$"},{"id":"D","label":"$2{,}700^\\circ$"}]}'::jsonb,42,'{"section_type":"math","sat_domain":"geometry_trig","sat_official_domain":"geometry_trigonometry","sat_skill":"lines_angles_triangles","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"geo-lines-019","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('85fca509-ec34-8415-ae18-5bd68cc667bc','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"The polygon has $\\frac{360}{24} = 15$ sides. The sum of its interior angles is $(15 - 2)(180°) = 2{,}340°$. Choice C is correct. Choice A is incorrect. This is the measure of one interior angle, not the sum of all of them. Choice B is incorrect. This uses $n - 3$ triangles instead of $n - 2$. Choice D is incorrect. This multiplies 180° by the number of sides without subtracting 2."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('6da8f66a-a27c-0d44-e430-c11c69986cd5','978612a1-1a5e-c55f-a23d-ab24bca46382','question_single_choice','{"prompt":"In triangle $ABC$, the measure of angle $A$ is $64°$. The bisectors of angles $B$ and $C$ intersect at point $I$. What is the measure of angle $BIC$?","options":[{"id":"A","label":"$32^\\circ$"},{"id":"B","label":"$58^\\circ$"},{"id":"C","label":"$116^\\circ$"},{"id":"D","label":"$122^\\circ$"}]}'::jsonb,43,'{"section_type":"math","sat_domain":"geometry_trig","sat_official_domain":"geometry_trigonometry","sat_skill":"lines_angles_triangles","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"geo-lines-020","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('6da8f66a-a27c-0d44-e430-c11c69986cd5','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"Angles $B$ and $C$ add to $180 - 64 = 116°$, so half of each adds to $58°$. In triangle $BIC$, angle $BIC = 180 - 58 = 122°$. Choice D is correct. Choice A is incorrect. This halves angle $A$; the bisectors divide angles $B$ and $C$, not angle $A$. Choice B is incorrect. This is the sum of angles $IBC$ and $ICB$, not angle $BIC$. Choice C is incorrect. This is the sum of angles $B$ and $C$; the bisectors take only half of each."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('84e7d4b8-461d-2477-db99-9cf9eccf2e35','978612a1-1a5e-c55f-a23d-ab24bca46382','question_spr','{"prompt":"Triangle $ABC$ is similar to triangle $DEF$, with $\\overline{AB}$ corresponding to $\\overline{DE}$. The area of triangle $ABC$ is $32$ and the area of triangle $DEF$ is $72$. If $AB = x$ and $DE = x + 4$, what is the value of $x$?"}'::jsonb,44,'{"section_type":"math","sat_domain":"geometry_trig","sat_official_domain":"geometry_trigonometry","sat_skill":"lines_angles_triangles","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"geo-lines-021","answer_format":"spr"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('84e7d4b8-461d-2477-db99-9cf9eccf2e35','{"accepted":["8"]}'::jsonb,'{"feedback":{"explanation":"The ratio of the areas is $\\frac{72}{32} = \\frac{9}{4}$, so the ratio of corresponding sides is $\\sqrt{\\frac{9}{4}} = \\frac{3}{2}$. Then $\\frac{x + 4}{x} = \\frac{3}{2}$, so $2x + 8 = 3x$ and $x = 8$."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('7c1bfcaf-31ea-ffe2-c50c-be120d4a04ac','978612a1-1a5e-c55f-a23d-ab24bca46382','question_spr','{"prompt":"Two sides of a triangle have lengths $9$ and $15$. The third side has a length that is an integer. How many different lengths are possible for the third side?"}'::jsonb,45,'{"section_type":"math","sat_domain":"geometry_trig","sat_official_domain":"geometry_trigonometry","sat_skill":"lines_angles_triangles","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"geo-lines-022","answer_format":"spr"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('7c1bfcaf-31ea-ffe2-c50c-be120d4a04ac','{"accepted":["17"]}'::jsonb,'{"feedback":{"explanation":"By the triangle inequality, the third side $s$ satisfies $15 - 9 < s < 15 + 9$, or $6 < s < 24$. The integers from 7 through 23 inclusive number $23 - 7 + 1 = 17$."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('58ac1d8c-0eb8-543e-b90f-f4e5f0651cf3','978612a1-1a5e-c55f-a23d-ab24bca46382','question_single_choice','{"prompt":"In triangle $XYZ$, the measure of angle $X$ is equal to the sum of the measures of angles $Y$ and $Z$, and the measure of angle $Y$ is $4$ times the measure of angle $Z$. What is the measure of angle $Y$?","options":[{"id":"A","label":"$18^\\circ$"},{"id":"B","label":"$36^\\circ$"},{"id":"C","label":"$72^\\circ$"},{"id":"D","label":"$90^\\circ$"}]}'::jsonb,46,'{"section_type":"math","sat_domain":"geometry_trig","sat_official_domain":"geometry_trigonometry","sat_skill":"lines_angles_triangles","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"geo-lines-023","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('58ac1d8c-0eb8-543e-b90f-f4e5f0651cf3','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"Since $X = Y + Z$ and $X + Y + Z = 180$, $2X = 180$ and $X = 90$. Then $Y + Z = 90$ with $Y = 4Z$, so $5Z = 90$, $Z = 18$, and $Y = 72°$. Choice C is correct. Choice A is incorrect. This is the measure of angle $Z$. Choice B is incorrect. This divides 180° into 5 parts for angles $Y$ and $Z$, ignoring that angle $X$ takes half of the 180°. Choice D is incorrect. This is the measure of angle $X$."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('28d13162-5686-d116-c9b1-b9b88d9bdb6a','978612a1-1a5e-c55f-a23d-ab24bca46382','question_single_choice','{"prompt":"The legs of a right triangle have lengths $9$ and $12$. What is the length of the hypotenuse?","options":[{"id":"A","label":"$3\\sqrt{7}$"},{"id":"B","label":"$15$"},{"id":"C","label":"$21$"},{"id":"D","label":"$225$"}]}'::jsonb,47,'{"section_type":"math","sat_domain":"geometry_trig","sat_official_domain":"geometry_trigonometry","sat_skill":"right_triangles_and_trigonometry","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"geo-trig-001","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('28d13162-5686-d116-c9b1-b9b88d9bdb6a','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"By the Pythagorean theorem, $c^2 = 9^2 + 12^2 = 81 + 144 = 225$, so $c = 15$. Choice B is correct. Choice A is incorrect. This is $\\sqrt{144 - 81}$, which treats 12 as the hypotenuse. Choice C is incorrect. This adds the leg lengths; the hypotenuse is found with the Pythagorean theorem. Choice D is incorrect. This is the square of the hypotenuse, not the hypotenuse."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('fd422f36-c2fc-c58b-b3f9-9a409a02091b','978612a1-1a5e-c55f-a23d-ab24bca46382','question_spr','{"prompt":"A right triangle has a hypotenuse of length $26$ and one leg of length $10$. What is the length of the other leg?"}'::jsonb,48,'{"section_type":"math","sat_domain":"geometry_trig","sat_official_domain":"geometry_trigonometry","sat_skill":"right_triangles_and_trigonometry","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"geo-trig-002","answer_format":"spr"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('fd422f36-c2fc-c58b-b3f9-9a409a02091b','{"accepted":["24"]}'::jsonb,'{"feedback":{"explanation":"By the Pythagorean theorem, the other leg is $\\sqrt{26^2 - 10^2} = \\sqrt{676 - 100} = \\sqrt{576} = 24$."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('e7e0ff55-288f-3a8c-6e3f-d87a1c1a7393','978612a1-1a5e-c55f-a23d-ab24bca46382','question_single_choice','{"prompt":"In right triangle $ABC$ shown, what is the value of $\\sin A$?","figure_svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 340 270\" width=\"340\" height=\"270\" font-family=\"Arial, Helvetica, sans-serif\" font-size=\"17\" role=\"img\"><title>Right triangle ABC with the right angle at C. AC = 15, BC = 8, and AB = 17.</title><rect x=\"0\" y=\"0\" width=\"340\" height=\"270\" fill=\"#ffffff\"/><polygon points=\"50,230 290,102 290,230\" fill=\"none\" stroke=\"#1f2937\" stroke-width=\"2\" stroke-linejoin=\"round\"/><path d=\"M278,230 L278,218 L290,218\" fill=\"none\" stroke=\"#1f2937\" stroke-width=\"1.2\"/><text x=\"40\" y=\"246\" text-anchor=\"middle\" fill=\"#1f2937\">A</text><text x=\"300\" y=\"98\" text-anchor=\"middle\" fill=\"#1f2937\">B</text><text x=\"302\" y=\"246\" text-anchor=\"middle\" fill=\"#1f2937\">C</text><text x=\"170\" y=\"252\" text-anchor=\"middle\" fill=\"#1f2937\">15</text><text x=\"304\" y=\"171\" fill=\"#1f2937\">8</text><text x=\"163.41\" y=\"158.65\" text-anchor=\"middle\" fill=\"#1f2937\">17</text></svg>","options":[{"id":"A","label":"$\\frac{8}{17}$"},{"id":"B","label":"$\\frac{8}{15}$"},{"id":"C","label":"$\\frac{15}{17}$"},{"id":"D","label":"$\\frac{17}{8}$"}]}'::jsonb,49,'{"section_type":"math","sat_domain":"geometry_trig","sat_official_domain":"geometry_trigonometry","sat_skill":"right_triangles_and_trigonometry","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"geo-trig-003","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('e7e0ff55-288f-3a8c-6e3f-d87a1c1a7393','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"The sine of an acute angle is the length of the opposite side divided by the hypotenuse. The side opposite angle $A$ is $BC = 8$ and the hypotenuse is 17, so $\\sin A = \\frac{8}{17}$. Choice A is correct. Choice B is incorrect. This is $\\tan A$, the opposite side over the adjacent side. Choice C is incorrect. This is $\\cos A$, the adjacent side over the hypotenuse. Choice D is incorrect. This is the hypotenuse over the opposite side, the reciprocal of $\\sin A$."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('a9b62370-f66a-f465-3538-6c5503f89091','978612a1-1a5e-c55f-a23d-ab24bca46382','question_single_choice','{"prompt":"In a right triangle, one acute angle measures $x°$, and $\\sin(x°) = 0.6$. What is the value of $\\cos((90 - x)°)$?","options":[{"id":"A","label":"$0.4$"},{"id":"B","label":"$0.6$"},{"id":"C","label":"$0.8$"},{"id":"D","label":"$1.67$"}]}'::jsonb,50,'{"section_type":"math","sat_domain":"geometry_trig","sat_official_domain":"geometry_trigonometry","sat_skill":"right_triangles_and_trigonometry","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"geo-trig-004","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('a9b62370-f66a-f465-3538-6c5503f89091','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"For complementary angles, $\\cos((90 - x)°) = \\sin(x°)$. So $\\cos((90 - x)°) = 0.6$. Choice B is correct. Choice A is incorrect. This subtracts 0.6 from 1, but sine and cosine of complementary angles are equal. Choice C is incorrect. This is $\\cos(x°)$, which is found from $\\sqrt{1 - 0.6^2}$, not $\\cos((90 - x)°)$. Choice D is incorrect. This is the reciprocal of 0.6."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('4e559f82-831a-7333-419f-eeb3ce592a58','978612a1-1a5e-c55f-a23d-ab24bca46382','question_single_choice','{"prompt":"In a $30°$-$60°$-$90°$ triangle, the shortest side has length $6$. What is the length of the hypotenuse?","options":[{"id":"A","label":"$6\\sqrt{2}$"},{"id":"B","label":"$6\\sqrt{3}$"},{"id":"C","label":"$12$"},{"id":"D","label":"$18$"}]}'::jsonb,51,'{"section_type":"math","sat_domain":"geometry_trig","sat_official_domain":"geometry_trigonometry","sat_skill":"right_triangles_and_trigonometry","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"geo-trig-005","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('4e559f82-831a-7333-419f-eeb3ce592a58','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"In a $30°$-$60°$-$90°$ triangle, the sides are in the ratio $1 : \\sqrt{3} : 2$. The hypotenuse is twice the shortest side: $2 \\times 6 = 12$. Choice C is correct. Choice A is incorrect. This uses the ratio for a 45°-45°-90° triangle. Choice B is incorrect. This is the length of the longer leg, opposite the 60° angle. Choice D is incorrect. This multiplies by 3 instead of 2."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('96c44caf-8ce8-beee-c4a1-705149095bc3','978612a1-1a5e-c55f-a23d-ab24bca46382','question_single_choice','{"prompt":"In the right triangle shown, what is the value of $\\tan \\theta$?","figure_svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 320 280\" width=\"320\" height=\"280\" font-family=\"Arial, Helvetica, sans-serif\" font-size=\"17\" role=\"img\"><title>Right triangle with the right angle at C. The horizontal leg CA = 7, the vertical leg CB = 24, the hypotenuse AB = 25, and angle theta is at vertex A.</title><rect x=\"0\" y=\"0\" width=\"320\" height=\"280\" fill=\"#ffffff\"/><polygon points=\"213,250 150,34 150,250\" fill=\"none\" stroke=\"#1f2937\" stroke-width=\"2\" stroke-linejoin=\"round\"/><path d=\"M162,250 L162,238 L150,238\" fill=\"none\" stroke=\"#1f2937\" stroke-width=\"1.2\"/><path d=\"M195,250 A18,18 0 0 1 207.96,232.72\" fill=\"none\" stroke=\"#1f2937\" stroke-width=\"1.2\"/><text x=\"195\" y=\"226\" text-anchor=\"middle\" fill=\"#1f2937\">θ</text><text x=\"138\" y=\"266\" text-anchor=\"middle\" fill=\"#1f2937\">C</text><text x=\"225\" y=\"266\" text-anchor=\"middle\" fill=\"#1f2937\">A</text><text x=\"138\" y=\"32\" text-anchor=\"middle\" fill=\"#1f2937\">B</text><text x=\"181.5\" y=\"272\" text-anchor=\"middle\" fill=\"#1f2937\">7</text><text x=\"138\" y=\"142\" text-anchor=\"end\" fill=\"#1f2937\">24</text><text x=\"194.94\" y=\"143.08\" text-anchor=\"middle\" fill=\"#1f2937\">25</text></svg>","options":[{"id":"A","label":"$\\frac{7}{25}$"},{"id":"B","label":"$\\frac{7}{24}$"},{"id":"C","label":"$\\frac{24}{25}$"},{"id":"D","label":"$\\frac{24}{7}$"}]}'::jsonb,52,'{"section_type":"math","sat_domain":"geometry_trig","sat_official_domain":"geometry_trigonometry","sat_skill":"right_triangles_and_trigonometry","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"geo-trig-006","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('96c44caf-8ce8-beee-c4a1-705149095bc3','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"The tangent is the opposite side divided by the adjacent side. The side opposite $\\theta$ is 24 and the adjacent leg is 7, so $\\tan \\theta = \\frac{24}{7}$. Choice D is correct. Choice A is incorrect. This is $\\cos \\theta$, the adjacent side over the hypotenuse. Choice B is incorrect. This is the adjacent side over the opposite side, the reciprocal of $\\tan \\theta$. Choice C is incorrect. This is $\\sin \\theta$, the opposite side over the hypotenuse."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('af818054-759f-fd54-bb46-9bac2d60ea43','978612a1-1a5e-c55f-a23d-ab24bca46382','question_single_choice','{"prompt":"A $13$-foot ladder leans against a vertical wall. The bottom of the ladder is $5$ feet from the base of the wall on level ground. How high up the wall, in feet, does the top of the ladder reach?","options":[{"id":"A","label":"$8$"},{"id":"B","label":"$12$"},{"id":"C","label":"$13.9$"},{"id":"D","label":"$18$"}]}'::jsonb,53,'{"section_type":"math","sat_domain":"geometry_trig","sat_official_domain":"geometry_trigonometry","sat_skill":"right_triangles_and_trigonometry","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"geo-trig-007","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('af818054-759f-fd54-bb46-9bac2d60ea43','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"The ladder is the hypotenuse of a right triangle with the ground and wall. The height is $\\sqrt{13^2 - 5^2} = \\sqrt{144} = 12$ feet. Choice B is correct. Choice A is incorrect. This subtracts the lengths instead of using the Pythagorean theorem. Choice C is incorrect. This adds the squares, treating the ladder as a leg instead of the hypotenuse. Choice D is incorrect. This adds the lengths instead of using the Pythagorean theorem."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('3524cc2e-ddeb-981a-b982-3b6e5b36ea1e','978612a1-1a5e-c55f-a23d-ab24bca46382','question_single_choice','{"prompt":"What is the measure of a $150°$ angle in radians?","options":[{"id":"A","label":"$\\frac{\\pi}{6}$"},{"id":"B","label":"$\\frac{5\\pi}{12}$"},{"id":"C","label":"$\\frac{5\\pi}{6}$"},{"id":"D","label":"$\\frac{5\\pi}{3}$"}]}'::jsonb,54,'{"section_type":"math","sat_domain":"geometry_trig","sat_official_domain":"geometry_trigonometry","sat_skill":"right_triangles_and_trigonometry","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"geo-trig-008","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('3524cc2e-ddeb-981a-b982-3b6e5b36ea1e','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"Multiply by $\\frac{\\pi}{180}$: $150 \\cdot \\frac{\\pi}{180} = \\frac{5\\pi}{6}$ radians. Choice C is correct. Choice A is incorrect. This is $30°$ in radians. Choice B is incorrect. This is $75°$ in radians; it divides by 360 instead of 180. Choice D is incorrect. This is $300°$ in radians; it divides by 90 instead of 180."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('b81df2a8-7786-f0d9-93d5-d4e346520e05','978612a1-1a5e-c55f-a23d-ab24bca46382','question_single_choice','{"prompt":"In the right triangle shown, what is the value of $x$?","figure_svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 320 260\" width=\"320\" height=\"260\" font-family=\"Arial, Helvetica, sans-serif\" font-size=\"17\" role=\"img\"><title>Right triangle ABC with the right angle at C. Angle A measures 30 degrees, hypotenuse AB = 10, and side AC is labeled x.</title><rect x=\"0\" y=\"0\" width=\"320\" height=\"260\" fill=\"#ffffff\"/><polygon points=\"40,220 265.17,90 265.17,220\" fill=\"none\" stroke=\"#1f2937\" stroke-width=\"2\" stroke-linejoin=\"round\"/><path d=\"M253.17,220 L253.17,208 L265.17,208\" fill=\"none\" stroke=\"#1f2937\" stroke-width=\"1.2\"/><path d=\"M65.98,205 A30,30 0 0 1 70,220\" fill=\"none\" stroke=\"#1f2937\" stroke-width=\"1.2\"/><text x=\"92\" y=\"214\" text-anchor=\"middle\" fill=\"#1f2937\">30°</text><text x=\"30\" y=\"236\" text-anchor=\"middle\" fill=\"#1f2937\">A</text><text x=\"275.17\" y=\"88\" text-anchor=\"middle\" fill=\"#1f2937\">B</text><text x=\"277.17\" y=\"236\" text-anchor=\"middle\" fill=\"#1f2937\">C</text><text x=\"145.58\" y=\"147.88\" text-anchor=\"middle\" fill=\"#1f2937\">10</text><text x=\"152.58\" y=\"244\" text-anchor=\"middle\" font-style=\"italic\" fill=\"#1f2937\">x</text></svg>","options":[{"id":"A","label":"$5$"},{"id":"B","label":"$5\\sqrt{2}$"},{"id":"C","label":"$5\\sqrt{3}$"},{"id":"D","label":"$10\\sqrt{3}$"}]}'::jsonb,55,'{"section_type":"math","sat_domain":"geometry_trig","sat_official_domain":"geometry_trigonometry","sat_skill":"right_triangles_and_trigonometry","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"geo-trig-009","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('b81df2a8-7786-f0d9-93d5-d4e346520e05','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"In a $30°$-$60°$-$90°$ triangle, the side opposite 30° is half the hypotenuse, 5, and the side opposite 60° is $\\sqrt{3}$ times that: $x = 5\\sqrt{3}$. Equivalently, $x = 10\\cos 30° = 10 \\cdot \\frac{\\sqrt{3}}{2}$. Choice C is correct. Choice A is incorrect. This is the length of $\\overline{BC}$, the side opposite the 30° angle. Choice B is incorrect. This uses the side ratio of a 45°-45°-90° triangle. Choice D is incorrect. This multiplies the hypotenuse by $\\sqrt{3}$ instead of the shorter leg."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('b77027dd-d56b-c4cd-7fa6-3359913c6d04','978612a1-1a5e-c55f-a23d-ab24bca46382','question_spr','{"prompt":"In right triangle $ABC$, angle $C$ is a right angle and $\\sin A = \\frac{5}{13}$. What is the value of $\\tan A$?"}'::jsonb,56,'{"section_type":"math","sat_domain":"geometry_trig","sat_official_domain":"geometry_trigonometry","sat_skill":"right_triangles_and_trigonometry","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"geo-trig-010","answer_format":"spr"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('b77027dd-d56b-c4cd-7fa6-3359913c6d04','{"accepted":["5/12",".4166",".4167","0.416","0.417"]}'::jsonb,'{"feedback":{"explanation":"If $\\sin A = \\frac{5}{13}$, the side opposite $A$ can be taken as 5 and the hypotenuse as 13. The adjacent side is $\\sqrt{13^2 - 5^2} = 12$, so $\\tan A = \\frac{5}{12}$."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('c524147b-0f5a-8cea-ffbe-a272b3aba841','978612a1-1a5e-c55f-a23d-ab24bca46382','question_single_choice','{"prompt":"The diagonal of a square has length $12$. What is the area of the square?","options":[{"id":"A","label":"$36$"},{"id":"B","label":"$72$"},{"id":"C","label":"$72\\sqrt{2}$"},{"id":"D","label":"$144$"}]}'::jsonb,57,'{"section_type":"math","sat_domain":"geometry_trig","sat_official_domain":"geometry_trigonometry","sat_skill":"right_triangles_and_trigonometry","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"geo-trig-011","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('c524147b-0f5a-8cea-ffbe-a272b3aba841','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"The diagonal of a square is $s\\sqrt{2}$, so $s = \\frac{12}{\\sqrt{2}} = 6\\sqrt{2}$. The area is $s^2 = 72$. (Equivalently, the area is $\\frac{d^2}{2} = \\frac{144}{2}$.) Choice B is correct. Choice A is incorrect. This uses half the diagonal, 6, as the side length. Choice C is incorrect. This multiplies the area by $\\sqrt{2}$ an extra time. Choice D is incorrect. This squares the diagonal, as if it were the side length."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('33889bdc-2d74-5c64-3997-746adcb69d1d','978612a1-1a5e-c55f-a23d-ab24bca46382','question_single_choice','{"prompt":"A straight ramp is $20$ feet long and makes an angle of $12°$ with the level ground. Which of the following is closest to the vertical height of the top of the ramp above the ground, in feet?","options":[{"id":"A","label":"$4.16$"},{"id":"B","label":"$4.25$"},{"id":"C","label":"$19.56$"},{"id":"D","label":"$96.19$"}]}'::jsonb,58,'{"section_type":"math","sat_domain":"geometry_trig","sat_official_domain":"geometry_trigonometry","sat_skill":"right_triangles_and_trigonometry","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"geo-trig-012","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('33889bdc-2d74-5c64-3997-746adcb69d1d','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"The ramp is the hypotenuse and the height is the side opposite the 12° angle, so the height is $20\\sin 12° \\approx 20(0.2079) \\approx 4.16$ feet. Choice A is correct. Choice B is incorrect. This uses $20\\tan 12°$, which treats the ramp as the horizontal leg instead of the hypotenuse. Choice C is incorrect. This is the horizontal distance covered by the ramp, $20\\cos 12°$. Choice D is incorrect. This divides 20 by $\\sin 12°$ instead of multiplying; the height must be less than the ramp''s length."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('ff37615a-29b7-5d92-cba4-5172a1d1db1d','978612a1-1a5e-c55f-a23d-ab24bca46382','question_spr','{"prompt":"In the $xy$-plane, what is the distance between the points $(-2, 3)$ and $(10, 8)$?"}'::jsonb,59,'{"section_type":"math","sat_domain":"geometry_trig","sat_official_domain":"geometry_trigonometry","sat_skill":"right_triangles_and_trigonometry","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"geo-trig-013","answer_format":"spr"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('ff37615a-29b7-5d92-cba4-5172a1d1db1d','{"accepted":["13"]}'::jsonb,'{"feedback":{"explanation":"The horizontal change is $10 - (-2) = 12$ and the vertical change is $8 - 3 = 5$. By the Pythagorean theorem, the distance is $\\sqrt{12^2 + 5^2} = \\sqrt{169} = 13$."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('3c1ebef3-3b9d-cef4-82f8-c3a12fbc3e42','978612a1-1a5e-c55f-a23d-ab24bca46382','question_single_choice','{"prompt":"For an acute angle $\\theta$, $\\cos \\theta = 0.28$. What is the value of $\\sin \\theta$?","options":[{"id":"A","label":"$0.0784$"},{"id":"B","label":"$0.28$"},{"id":"C","label":"$0.72$"},{"id":"D","label":"$0.96$"}]}'::jsonb,60,'{"section_type":"math","sat_domain":"geometry_trig","sat_official_domain":"geometry_trigonometry","sat_skill":"right_triangles_and_trigonometry","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"geo-trig-014","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('3c1ebef3-3b9d-cef4-82f8-c3a12fbc3e42','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"Use $\\sin^2 \\theta + \\cos^2 \\theta = 1$: $\\sin^2 \\theta = 1 - 0.0784 = 0.9216$, so $\\sin \\theta = 0.96$ (positive because $\\theta$ is acute). Choice D is correct. Choice A is incorrect. This is $\\cos^2 \\theta$; the square root of $1 - \\cos^2 \\theta$ is still needed. Choice B is incorrect. This assumes sine equals cosine, which is true only for a 45° angle. Choice C is incorrect. This subtracts 0.28 from 1; the identity is $\\sin^2 \\theta + \\cos^2 \\theta = 1$."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('98adf0a1-753b-24cb-196e-2c47793282cb','978612a1-1a5e-c55f-a23d-ab24bca46382','question_single_choice','{"prompt":"A triangle has side lengths $20$, $21$, and $29$. What is the measure of the angle opposite the side of length $29$?","options":[{"id":"A","label":"$60^\\circ$"},{"id":"B","label":"$75^\\circ$"},{"id":"C","label":"$90^\\circ$"},{"id":"D","label":"$120^\\circ$"}]}'::jsonb,61,'{"section_type":"math","sat_domain":"geometry_trig","sat_official_domain":"geometry_trigonometry","sat_skill":"right_triangles_and_trigonometry","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"geo-trig-015","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('98adf0a1-753b-24cb-196e-2c47793282cb','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"Since $20^2 + 21^2 = 400 + 441 = 841 = 29^2$, the converse of the Pythagorean theorem shows that the triangle is a right triangle with the right angle opposite the longest side, so the angle measures 90°. Choice C is correct. Choice A is incorrect. If the angle measured 60°, the square of 29 would be less than $20^2 + 21^2$; instead it is equal. Choice B is incorrect. This guesses an angle less than 90°, but $29^2 = 20^2 + 21^2$ exactly. Choice D is incorrect. An obtuse angle would require $29^2 > 20^2 + 21^2$."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('f4321877-0732-2766-b6bb-4b60369914e5','978612a1-1a5e-c55f-a23d-ab24bca46382','question_single_choice','{"prompt":"For acute angles measuring $(2x + 10)°$ and $(3x + 5)°$, $\\sin((2x + 10)°) = \\cos((3x + 5)°)$. What is the value of $x$?","options":[{"id":"A","label":"$5$"},{"id":"B","label":"$15$"},{"id":"C","label":"$33$"},{"id":"D","label":"$40$"}]}'::jsonb,62,'{"section_type":"math","sat_domain":"geometry_trig","sat_official_domain":"geometry_trigonometry","sat_skill":"right_triangles_and_trigonometry","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"geo-trig-016","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('f4321877-0732-2766-b6bb-4b60369914e5','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"If $\\sin a = \\cos b$ for acute angles, then $a + b = 90$. So $(2x + 10) + (3x + 5) = 90$, giving $5x = 75$ and $x = 15$. Choice B is correct. Choice A is incorrect. This sets the two angle measures equal, but sine and cosine are equal for complementary angles. Choice C is incorrect. This makes the angles supplementary, adding to 180°, instead of complementary. Choice D is incorrect. This is the measure of one of the angles, not the value of $x$."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('61a1f384-5ae1-4fca-ddc9-4142ed4c8339','978612a1-1a5e-c55f-a23d-ab24bca46382','question_single_choice','{"prompt":"An isosceles triangle has side lengths $10$, $10$, and $12$. What is the area of the triangle?","options":[{"id":"A","label":"$40$"},{"id":"B","label":"$48$"},{"id":"C","label":"$80$"},{"id":"D","label":"$96$"}]}'::jsonb,63,'{"section_type":"math","sat_domain":"geometry_trig","sat_official_domain":"geometry_trigonometry","sat_skill":"right_triangles_and_trigonometry","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"geo-trig-017","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('61a1f384-5ae1-4fca-ddc9-4142ed4c8339','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"The height to the base of length 12 bisects it, forming right triangles with legs 6 and $h$ and hypotenuse 10. So $h = \\sqrt{10^2 - 6^2} = 8$, and the area is $\\frac{1}{2}(12)(8) = 48$. Choice B is correct. Choice A is incorrect. This uses 10 as the base with the height to the side of length 12. Choice C is incorrect. This multiplies a side of length 10 by the height 8 and leaves out the factor of $\\frac{1}{2}$; the height is perpendicular to the base of 12. Choice D is incorrect. This is base times height without the factor of $\\frac{1}{2}$."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('9d730063-9e9b-2b4e-6e1d-8293b577a0e3','978612a1-1a5e-c55f-a23d-ab24bca46382','question_spr','{"prompt":"In the figure, triangle $ABC$ has a right angle at $C$, and $\\overline{CD}$ is the altitude to hypotenuse $\\overline{AB}$. If $AD = 4$ and $DB = 9$, what is the area of triangle $ABC$?","figure_svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 380 270\" width=\"380\" height=\"270\" font-family=\"Arial, Helvetica, sans-serif\" font-size=\"17\" role=\"img\"><title>Right triangle ABC with the right angle at C. Altitude CD is drawn to hypotenuse AB, with AD = 4 and DB = 9.</title><rect x=\"0\" y=\"0\" width=\"380\" height=\"270\" fill=\"#ffffff\"/><polygon points=\"40,230 352,230 136,86\" fill=\"none\" stroke=\"#1f2937\" stroke-width=\"2\" stroke-linejoin=\"round\"/><line x1=\"136\" y1=\"86\" x2=\"136\" y2=\"230\" stroke=\"#1f2937\" stroke-width=\"1.5\" stroke-dasharray=\"6 4\"/><path d=\"M129.34,95.98 L139.33,102.64 L145.98,92.66\" fill=\"none\" stroke=\"#1f2937\" stroke-width=\"1.2\"/><path d=\"M146,230 L146,220 L136,220\" fill=\"none\" stroke=\"#1f2937\" stroke-width=\"1.2\"/><text x=\"30\" y=\"246\" text-anchor=\"middle\" fill=\"#1f2937\">A</text><text x=\"362\" y=\"246\" text-anchor=\"middle\" fill=\"#1f2937\">B</text><text x=\"136\" y=\"76\" text-anchor=\"middle\" fill=\"#1f2937\">C</text><text x=\"136\" y=\"252\" text-anchor=\"middle\" fill=\"#1f2937\">D</text><text x=\"88\" y=\"252\" text-anchor=\"middle\" fill=\"#1f2937\">4</text><text x=\"244\" y=\"252\" text-anchor=\"middle\" fill=\"#1f2937\">9</text></svg>"}'::jsonb,64,'{"section_type":"math","sat_domain":"geometry_trig","sat_official_domain":"geometry_trigonometry","sat_skill":"right_triangles_and_trigonometry","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"geo-trig-018","answer_format":"spr"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('9d730063-9e9b-2b4e-6e1d-8293b577a0e3','{"accepted":["39"]}'::jsonb,'{"feedback":{"explanation":"The altitude to the hypotenuse creates triangles $ADC$ and $CDB$, which are similar, so $\\frac{AD}{CD} = \\frac{CD}{DB}$ and $CD^2 = 4 \\cdot 9 = 36$, giving $CD = 6$. The hypotenuse is $AB = 4 + 9 = 13$, so the area is $\\frac{1}{2}(13)(6) = 39$."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('6af085de-4214-bc2f-b5bd-8d539915b996','978612a1-1a5e-c55f-a23d-ab24bca46382','question_single_choice','{"prompt":"In right triangle $PQR$, angle $Q$ is a right angle and $\\sin P = \\frac{3}{5}$. The hypotenuse is $12$ units longer than $\\overline{QR}$. What is the length of $\\overline{PQ}$?","options":[{"id":"A","label":"$6$"},{"id":"B","label":"$\\frac{48}{5}$"},{"id":"C","label":"$18$"},{"id":"D","label":"$24$"}]}'::jsonb,65,'{"section_type":"math","sat_domain":"geometry_trig","sat_official_domain":"geometry_trigonometry","sat_skill":"right_triangles_and_trigonometry","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"geo-trig-019","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('6af085de-4214-bc2f-b5bd-8d539915b996','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"Since $\\sin P = \\frac{QR}{PR} = \\frac{3}{5}$, write $QR = 3k$ and $PR = 5k$. Then $5k - 3k = 12$, so $k = 6$. The remaining leg is $PQ = 4k = 24$, from the 3-4-5 relationship. Choice D is correct. Choice A is incorrect. This is the value of $k$ in $QR = 3k$ and $PR = 5k$, not a side length. Choice B is incorrect. This assumes the hypotenuse itself is 12 and finds the leg as $\\frac{4}{5}$ of it. Choice C is incorrect. This is the length of $\\overline{QR}$, the side opposite angle $P$."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('fc8a7c1f-6fbd-cc41-7b13-52ab7f688873','978612a1-1a5e-c55f-a23d-ab24bca46382','question_single_choice','{"prompt":"For an acute angle $x$, $\\sin x = k$. Which expression is equal to $\\cos(90° - x) + \\sin(90° - x)$?","options":[{"id":"A","label":"$k + \\sqrt{1 - k^2}$"},{"id":"B","label":"$2k$"},{"id":"C","label":"$1$"},{"id":"D","label":"$k + (1 - k^2)$"}]}'::jsonb,66,'{"section_type":"math","sat_domain":"geometry_trig","sat_official_domain":"geometry_trigonometry","sat_skill":"right_triangles_and_trigonometry","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"geo-trig-020","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('fc8a7c1f-6fbd-cc41-7b13-52ab7f688873','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"By the complementary angle relationships, $\\cos(90° - x) = \\sin x = k$ and $\\sin(90° - x) = \\cos x$. Since $x$ is acute, $\\cos x = \\sqrt{1 - \\sin^2 x} = \\sqrt{1 - k^2}$. The sum is $k + \\sqrt{1 - k^2}$. Choice A is correct. Choice B is incorrect. This treats both terms as equal to $k$, but $\\sin(90° - x) = \\cos x$, not $\\sin x$. Choice C is incorrect. This assumes the two terms add to 1, which is true for their squares, not the terms themselves. Choice D is incorrect. This uses $\\cos x = 1 - k^2$ instead of $\\cos x = \\sqrt{1 - k^2}$."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('f8bf1618-35fb-99f4-0bc1-61e2304f5332','978612a1-1a5e-c55f-a23d-ab24bca46382','question_single_choice','{"prompt":"In the $xy$-plane, the terminal side of an angle $\\theta$ in standard position, where $0 \\le \\theta < 2\\pi$, intersects the unit circle at $\\left(-\\frac{\\sqrt{3}}{2}, \\frac{1}{2}\\right)$. What is the value of $\\theta$?","options":[{"id":"A","label":"$\\frac{\\pi}{6}$"},{"id":"B","label":"$\\frac{2\\pi}{3}$"},{"id":"C","label":"$\\frac{5\\pi}{6}$"},{"id":"D","label":"$\\frac{7\\pi}{6}$"}]}'::jsonb,67,'{"section_type":"math","sat_domain":"geometry_trig","sat_official_domain":"geometry_trigonometry","sat_skill":"right_triangles_and_trigonometry","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"geo-trig-021","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('f8bf1618-35fb-99f4-0bc1-61e2304f5332','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"The point has $\\cos \\theta = -\\frac{\\sqrt{3}}{2}$ and $\\sin \\theta = \\frac{1}{2}$, so it is in the second quadrant with a reference angle of $\\frac{\\pi}{6}$. Then $\\theta = \\pi - \\frac{\\pi}{6} = \\frac{5\\pi}{6}$. Choice C is correct. Choice A is incorrect. This angle ends at $\\left(\\frac{\\sqrt{3}}{2}, \\frac{1}{2}\\right)$, in the first quadrant; the given point has a negative $x$-coordinate. Choice B is incorrect. This angle ends at $\\left(-\\frac{1}{2}, \\frac{\\sqrt{3}}{2}\\right)$; the coordinates are switched. Choice D is incorrect. This angle ends at $\\left(-\\frac{\\sqrt{3}}{2}, -\\frac{1}{2}\\right)$, in the third quadrant."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('7b1653ab-b325-43bd-0413-856daa077b1f','978612a1-1a5e-c55f-a23d-ab24bca46382','question_spr','{"prompt":"An isosceles trapezoid has parallel bases of lengths $10$ and $22$, and each of its nonparallel sides has length $10$. What is the area of the trapezoid?"}'::jsonb,68,'{"section_type":"math","sat_domain":"geometry_trig","sat_official_domain":"geometry_trigonometry","sat_skill":"right_triangles_and_trigonometry","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"geo-trig-022","answer_format":"spr"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('7b1653ab-b325-43bd-0413-856daa077b1f','{"accepted":["128"]}'::jsonb,'{"feedback":{"explanation":"Dropping perpendiculars from the ends of the shorter base splits the longer base into $6 + 10 + 6$. Each right triangle has hypotenuse 10 and leg 6, so the height is $\\sqrt{10^2 - 6^2} = 8$. The area is $\\frac{1}{2}(10 + 22)(8) = 128$."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('ea2e43d8-e6ac-c72b-b8b8-ed5d2ccf6a93','978612a1-1a5e-c55f-a23d-ab24bca46382','question_single_choice','{"prompt":"A circle has a radius of $9$ centimeters. What is the circumference of the circle, in centimeters?","options":[{"id":"A","label":"$18\\pi$"},{"id":"B","label":"$36\\pi$"},{"id":"C","label":"$81\\pi$"},{"id":"D","label":"$162\\pi$"}]}'::jsonb,69,'{"section_type":"math","sat_domain":"geometry_trig","sat_official_domain":"geometry_trigonometry","sat_skill":"circles","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"geo-circle-001","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('ea2e43d8-e6ac-c72b-b8b8-ed5d2ccf6a93','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"The circumference is $2\\pi r = 2\\pi(9) = 18\\pi$ centimeters. Choice A is correct. Choice B is incorrect. This uses $2\\pi d$, doubling the diameter. Choice C is incorrect. This is the area of the circle, $\\pi r^2$. Choice D is incorrect. This is $2\\pi r^2$, which mixes the circumference and area formulas."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('e18eb5b4-3b1c-4e8a-c8ea-64810085281d','978612a1-1a5e-c55f-a23d-ab24bca46382','question_spr','{"prompt":"A circle has an area of $49\\pi$ square inches. What is the diameter of the circle, in inches?"}'::jsonb,70,'{"section_type":"math","sat_domain":"geometry_trig","sat_official_domain":"geometry_trigonometry","sat_skill":"circles","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"geo-circle-002","answer_format":"spr"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('e18eb5b4-3b1c-4e8a-c8ea-64810085281d','{"accepted":["14"]}'::jsonb,'{"feedback":{"explanation":"From $\\pi r^2 = 49\\pi$, $r^2 = 49$ and $r = 7$. The diameter is $2r = 14$ inches."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('d1ce9e8b-d25a-1d6b-8646-b7010086df51','978612a1-1a5e-c55f-a23d-ab24bca46382','question_single_choice','{"prompt":"Which equation represents a circle in the $xy$-plane with center $(3, -2)$ and radius $5$?","options":[{"id":"A","label":"$(x - 3)^2 + (y + 2)^2 = 25$"},{"id":"B","label":"$(x - 3)^2 + (y + 2)^2 = 5$"},{"id":"C","label":"$(x + 3)^2 + (y - 2)^2 = 5$"},{"id":"D","label":"$(x + 3)^2 + (y - 2)^2 = 25$"}]}'::jsonb,71,'{"section_type":"math","sat_domain":"geometry_trig","sat_official_domain":"geometry_trigonometry","sat_skill":"circles","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"geo-circle-003","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('d1ce9e8b-d25a-1d6b-8646-b7010086df51','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"A circle with center $(h, k)$ and radius $r$ has equation $(x - h)^2 + (y - k)^2 = r^2$. Here that is $(x - 3)^2 + (y - (-2))^2 = 5^2$, or $(x - 3)^2 + (y + 2)^2 = 25$. Choice A is correct. Choice B is incorrect. The right side must be the square of the radius, $5^2 = 25$. Choice C is incorrect. This has both the wrong center and the radius not squared. Choice D is incorrect. This circle has center $(-3, 2)$; the signs in the equation are opposite to the coordinates of the center."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('21387205-809e-7a8c-3236-a1830052c08b','978612a1-1a5e-c55f-a23d-ab24bca46382','question_single_choice','{"prompt":"In the figure, $O$ is the center of the circle, and the measure of central angle $AOB$ is $80°$. What is the value of $x$?","figure_svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 400 290\" width=\"400\" height=\"290\" font-family=\"Arial, Helvetica, sans-serif\" font-size=\"17\" role=\"img\"><title>Circle with center O. Points A and B are on the circle with central angle AOB of 80 degrees; point P is on the circle opposite them, and angle APB is labeled x degrees.</title><rect x=\"0\" y=\"0\" width=\"400\" height=\"290\" fill=\"#ffffff\"/><circle cx=\"200\" cy=\"150\" r=\"110\" fill=\"none\" stroke=\"#1f2937\" stroke-width=\"2\"/><line x1=\"200\" y1=\"150\" x2=\"129.29\" y2=\"234.26\" stroke=\"#1f2937\" stroke-width=\"1.5\"/><line x1=\"200\" y1=\"150\" x2=\"270.71\" y2=\"234.26\" stroke=\"#1f2937\" stroke-width=\"1.5\"/><line x1=\"200\" y1=\"40\" x2=\"129.29\" y2=\"234.26\" stroke=\"#1f2937\" stroke-width=\"1.5\"/><line x1=\"200\" y1=\"40\" x2=\"270.71\" y2=\"234.26\" stroke=\"#1f2937\" stroke-width=\"1.5\"/><circle cx=\"200\" cy=\"150\" r=\"3\" fill=\"#1f2937\"/><path d=\"M212.86,165.32 A20,20 0 0 1 187.14,165.32\" fill=\"none\" stroke=\"#1f2937\" stroke-width=\"1.2\"/><text x=\"200\" y=\"192\" text-anchor=\"middle\" fill=\"#1f2937\">80°</text><path d=\"M208.89,64.43 A26,26 0 0 1 191.11,64.43\" fill=\"none\" stroke=\"#1f2937\" stroke-width=\"1.2\"/><text x=\"200\" y=\"86\" text-anchor=\"middle\" fill=\"#1f2937\">x°</text><text x=\"214\" y=\"146\" fill=\"#1f2937\">O</text><text x=\"117.29\" y=\"248.26\" text-anchor=\"middle\" fill=\"#1f2937\">A</text><text x=\"282.71\" y=\"248.26\" text-anchor=\"middle\" fill=\"#1f2937\">B</text><text x=\"200\" y=\"32\" text-anchor=\"middle\" fill=\"#1f2937\">P</text></svg>","options":[{"id":"A","label":"$40$"},{"id":"B","label":"$80$"},{"id":"C","label":"$100$"},{"id":"D","label":"$160$"}]}'::jsonb,72,'{"section_type":"math","sat_domain":"geometry_trig","sat_official_domain":"geometry_trigonometry","sat_skill":"circles","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"geo-circle-004","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('21387205-809e-7a8c-3236-a1830052c08b','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"Angle $APB$ is an inscribed angle that intercepts the same arc $AB$ as central angle $AOB$. An inscribed angle measures half of the central angle, so $x = \\frac{80}{2} = 40$. Choice A is correct. Choice B is incorrect. This assumes the inscribed angle equals the central angle. Choice C is incorrect. This is the supplement of the central angle; an inscribed angle is one-half of the central angle that intercepts the same arc. Choice D is incorrect. This doubles the central angle instead of halving it."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('07c7a433-73aa-b502-641d-457e5eafc793','978612a1-1a5e-c55f-a23d-ab24bca46382','question_single_choice','{"prompt":"A circle in the $xy$-plane has equation $(x + 1)^2 + (y - 4)^2 = 36$. What is the radius of the circle?","options":[{"id":"A","label":"$6$"},{"id":"B","label":"$12$"},{"id":"C","label":"$18$"},{"id":"D","label":"$36$"}]}'::jsonb,73,'{"section_type":"math","sat_domain":"geometry_trig","sat_official_domain":"geometry_trigonometry","sat_skill":"circles","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"geo-circle-005","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('07c7a433-73aa-b502-641d-457e5eafc793','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"In the form $(x - h)^2 + (y - k)^2 = r^2$, $r^2 = 36$, so the radius is $r = 6$. Choice A is correct. Choice B is incorrect. This is the diameter of the circle, not the radius. Choice C is incorrect. This divides 36 by 2 instead of taking its square root. Choice D is incorrect. This is the square of the radius."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('24e67740-4a06-260e-eb4d-2b91298411df','978612a1-1a5e-c55f-a23d-ab24bca46382','question_spr','{"prompt":"A circle has a circumference of $30\\pi$ meters. What is the radius of the circle, in meters?"}'::jsonb,74,'{"section_type":"math","sat_domain":"geometry_trig","sat_official_domain":"geometry_trigonometry","sat_skill":"circles","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"geo-circle-006","answer_format":"spr"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('24e67740-4a06-260e-eb4d-2b91298411df','{"accepted":["15"]}'::jsonb,'{"feedback":{"explanation":"The circumference is $2\\pi r = 30\\pi$, so $r = 15$ meters."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('e18807bf-24c9-8aa5-563c-73dca54f92fd','978612a1-1a5e-c55f-a23d-ab24bca46382','question_single_choice','{"prompt":"In the figure, $\\overline{OP}$ is a radius of the circle with center $O$, and line $PQ$ is tangent to the circle at $P$. If the measure of angle $POQ$ is $35°$, what is the value of $x$?","figure_svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 400 280\" width=\"400\" height=\"280\" font-family=\"Arial, Helvetica, sans-serif\" font-size=\"17\" role=\"img\"><title>Circle with center O and radius OP. Line through P and Q is tangent to the circle at P. Angle POQ is 35 degrees.</title><rect x=\"0\" y=\"0\" width=\"400\" height=\"280\" fill=\"#ffffff\"/><circle cx=\"150\" cy=\"120\" r=\"120\" fill=\"none\" stroke=\"#1f2937\" stroke-width=\"2\"/><line x1=\"20\" y1=\"240\" x2=\"390\" y2=\"240\" stroke=\"#1f2937\" stroke-width=\"2\"/><line x1=\"150\" y1=\"120\" x2=\"150\" y2=\"240\" stroke=\"#1f2937\" stroke-width=\"1.5\"/><line x1=\"150\" y1=\"120\" x2=\"234.02\" y2=\"240\" stroke=\"#1f2937\" stroke-width=\"1.5\"/><circle cx=\"150\" cy=\"120\" r=\"3\" fill=\"#1f2937\"/><path d=\"M150,228 L162,228 L162,240\" fill=\"none\" stroke=\"#1f2937\" stroke-width=\"1.2\"/><path d=\"M169.5,147.85 A34,34 0 0 1 150,154\" fill=\"none\" stroke=\"#1f2937\" stroke-width=\"1.2\"/><text x=\"166\" y=\"172\" fill=\"#1f2937\">35°</text><text x=\"138\" y=\"116\" text-anchor=\"middle\" fill=\"#1f2937\">O</text><text x=\"138\" y=\"258\" text-anchor=\"middle\" fill=\"#1f2937\">P</text><text x=\"238.02\" y=\"258\" text-anchor=\"middle\" fill=\"#1f2937\">Q</text><path d=\"M212.02,240 A22,22 0 0 1 221.41,221.98\" fill=\"none\" stroke=\"#1f2937\" stroke-width=\"1.2\"/><text x=\"195\" y=\"224.68\" text-anchor=\"middle\" fill=\"#1f2937\">x°</text></svg>","options":[{"id":"A","label":"$55$"},{"id":"B","label":"$90$"},{"id":"C","label":"$125$"},{"id":"D","label":"$145$"}]}'::jsonb,75,'{"section_type":"math","sat_domain":"geometry_trig","sat_official_domain":"geometry_trigonometry","sat_skill":"circles","difficulty":"easy","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"geo-circle-007","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('e18807bf-24c9-8aa5-563c-73dca54f92fd','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"A tangent line is perpendicular to the radius at the point of tangency, so angle $OPQ = 90°$. In triangle $OPQ$, $x = 180 - 90 - 35 = 55$. Choice A is correct. Choice B is incorrect. This is the measure of angle $OPQ$, the angle between the radius and the tangent. Choice C is incorrect. This adds the right angle and the 35° angle; the three angles of the triangle must add to 180°. Choice D is incorrect. This subtracts only 35° from 180°, leaving out the right angle at $P$."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('903c05d0-5c24-d5f8-c4de-fbd3014f625c','978612a1-1a5e-c55f-a23d-ab24bca46382','question_single_choice','{"prompt":"A circle has a radius of $12$. What is the length of an arc of the circle intercepted by a central angle of $60°$?","options":[{"id":"A","label":"$2\\pi$"},{"id":"B","label":"$4\\pi$"},{"id":"C","label":"$24\\pi$"},{"id":"D","label":"$720$"}]}'::jsonb,76,'{"section_type":"math","sat_domain":"geometry_trig","sat_official_domain":"geometry_trigonometry","sat_skill":"circles","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"geo-circle-008","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('903c05d0-5c24-d5f8-c4de-fbd3014f625c','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"The arc is $\\frac{60}{360} = \\frac{1}{6}$ of the circumference. The circumference is $2\\pi(12) = 24\\pi$, so the arc length is $\\frac{24\\pi}{6} = 4\\pi$. Choice B is correct. Choice A is incorrect. This uses $\\pi r = 12\\pi$ as the circumference instead of $2\\pi r = 24\\pi$. Choice C is incorrect. This is the area of the sector, not the arc length. Choice D is incorrect. This multiplies the radius by the angle in degrees; the formula $s = r\\theta$ requires $\\theta$ in radians."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('d4994221-8e52-cb95-26a1-600959f6384f','978612a1-1a5e-c55f-a23d-ab24bca46382','question_spr','{"prompt":"A sector of a circle with radius $6$ has a central angle of $100°$. The area of the sector is $a\\pi$. What is the value of $a$?"}'::jsonb,77,'{"section_type":"math","sat_domain":"geometry_trig","sat_official_domain":"geometry_trigonometry","sat_skill":"circles","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"geo-circle-009","answer_format":"spr"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('d4994221-8e52-cb95-26a1-600959f6384f','{"accepted":["10"]}'::jsonb,'{"feedback":{"explanation":"The sector is $\\frac{100}{360}$ of the circle''s area, $36\\pi$. So the area is $\\frac{100}{360} \\cdot 36\\pi = 10\\pi$, and $a = 10$."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('973ab91c-93e8-7f95-03c1-fdf3237b28a7','978612a1-1a5e-c55f-a23d-ab24bca46382','question_single_choice','{"prompt":"A circle in the $xy$-plane has equation $x^2 + y^2 - 6x + 10y - 15 = 0$. What is the radius of the circle?","options":[{"id":"A","label":"$\\sqrt{15}$"},{"id":"B","label":"$7$"},{"id":"C","label":"$15$"},{"id":"D","label":"$49$"}]}'::jsonb,78,'{"section_type":"math","sat_domain":"geometry_trig","sat_official_domain":"geometry_trigonometry","sat_skill":"circles","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"geo-circle-010","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('973ab91c-93e8-7f95-03c1-fdf3237b28a7','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"Complete the square: $(x^2 - 6x + 9) + (y^2 + 10y + 25) = 15 + 9 + 25$, so $(x - 3)^2 + (y + 5)^2 = 49$. The radius is $\\sqrt{49} = 7$. Choice B is correct. Choice A is incorrect. This takes the square root of the constant term, without completing the square. Choice C is incorrect. This uses the constant term as the radius. Choice D is incorrect. This is the square of the radius."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('a73311f3-eaf9-d495-483d-c1a6ac98d405','978612a1-1a5e-c55f-a23d-ab24bca46382','question_single_choice','{"prompt":"A circle has a radius of $9$. What is the length of the arc intercepted by a central angle of $\\frac{2\\pi}{3}$ radians?","options":[{"id":"A","label":"$3\\pi$"},{"id":"B","label":"$6\\pi$"},{"id":"C","label":"$12\\pi$"},{"id":"D","label":"$27\\pi$"}]}'::jsonb,79,'{"section_type":"math","sat_domain":"geometry_trig","sat_official_domain":"geometry_trigonometry","sat_skill":"circles","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"geo-circle-011","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('a73311f3-eaf9-d495-483d-c1a6ac98d405','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"For an angle in radians, the arc length is $s = r\\theta = 9 \\cdot \\frac{2\\pi}{3} = 6\\pi$. Choice B is correct. Choice A is incorrect. This is half the correct arc length; it uses $\\frac{\\pi}{3}$ instead of $\\frac{2\\pi}{3}$. Choice C is incorrect. This uses the diameter, 18, in place of the radius. Choice D is incorrect. This is the area of the sector, $\\frac{1}{2}r^2\\theta$."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('d850959a-754b-72d9-c2dc-180d0d9d2a6e','978612a1-1a5e-c55f-a23d-ab24bca46382','question_single_choice','{"prompt":"The point $(5, k)$ lies on the circle with equation $x^2 + y^2 = 169$. If $k > 0$, what is the value of $k$?","options":[{"id":"A","label":"$8$"},{"id":"B","label":"$12$"},{"id":"C","label":"$13$"},{"id":"D","label":"$144$"}]}'::jsonb,80,'{"section_type":"math","sat_domain":"geometry_trig","sat_official_domain":"geometry_trigonometry","sat_skill":"circles","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"geo-circle-012","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('d850959a-754b-72d9-c2dc-180d0d9d2a6e','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"Substitute $x = 5$: $25 + k^2 = 169$, so $k^2 = 144$ and $k = 12$ (positive). Choice B is correct. Choice A is incorrect. This subtracts 5 from the radius instead of using $5^2 + k^2 = 169$. Choice C is incorrect. This is the radius of the circle. Choice D is incorrect. This is $k^2$, not $k$."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('b3145414-2971-c5e3-f445-12aaf492bfe2','978612a1-1a5e-c55f-a23d-ab24bca46382','question_spr','{"prompt":"From point $P$ outside a circle, two segments are drawn tangent to the circle at points $A$ and $B$. If $PA = 3x + 4$ and $PB = 5x - 6$, what is the length of $\\overline{PA}$?"}'::jsonb,81,'{"section_type":"math","sat_domain":"geometry_trig","sat_official_domain":"geometry_trigonometry","sat_skill":"circles","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"geo-circle-013","answer_format":"spr"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('b3145414-2971-c5e3-f445-12aaf492bfe2','{"accepted":["19"]}'::jsonb,'{"feedback":{"explanation":"Two tangent segments drawn to a circle from the same external point are congruent, so $3x + 4 = 5x - 6$, giving $x = 5$. Then $PA = 3(5) + 4 = 19$."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('03dd2252-8d22-4935-bdc1-526d5747fe6f','978612a1-1a5e-c55f-a23d-ab24bca46382','question_single_choice','{"prompt":"In the figure, a chord of length $24$ is drawn in a circle with center $O$ and radius $13$. What is the distance $d$ from $O$ to the chord?","figure_svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 400 280\" width=\"400\" height=\"280\" font-family=\"Arial, Helvetica, sans-serif\" font-size=\"17\" role=\"img\"><title>Circle with center O and radius 13. A chord of length 24 lies below the center; a dashed perpendicular segment of length d joins the center to the chord''s midpoint.</title><rect x=\"0\" y=\"0\" width=\"400\" height=\"280\" fill=\"#ffffff\"/><circle cx=\"200\" cy=\"140\" r=\"117\" fill=\"none\" stroke=\"#1f2937\" stroke-width=\"2\"/><line x1=\"92\" y1=\"185\" x2=\"308\" y2=\"185\" stroke=\"#1f2937\" stroke-width=\"2\"/><line x1=\"200\" y1=\"140\" x2=\"308\" y2=\"185\" stroke=\"#1f2937\" stroke-width=\"1.5\"/><line x1=\"200\" y1=\"140\" x2=\"200\" y2=\"185\" stroke=\"#1f2937\" stroke-width=\"1.5\" stroke-dasharray=\"5 4\"/><path d=\"M210,185 L210,175 L200,175\" fill=\"none\" stroke=\"#1f2937\" stroke-width=\"1.2\"/><circle cx=\"200\" cy=\"140\" r=\"3\" fill=\"#1f2937\"/><text x=\"188\" y=\"136\" text-anchor=\"middle\" fill=\"#1f2937\">O</text><text x=\"258.62\" y=\"156.42\" text-anchor=\"middle\" fill=\"#1f2937\">13</text><text x=\"186\" y=\"167.5\" text-anchor=\"middle\" font-style=\"italic\" fill=\"#1f2937\">d</text><text x=\"150\" y=\"205\" text-anchor=\"middle\" fill=\"#1f2937\">24</text></svg>","options":[{"id":"A","label":"$1$"},{"id":"B","label":"$5$"},{"id":"C","label":"$12$"},{"id":"D","label":"$\\sqrt{313}$"}]}'::jsonb,82,'{"section_type":"math","sat_domain":"geometry_trig","sat_official_domain":"geometry_trigonometry","sat_skill":"circles","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"geo-circle-014","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('03dd2252-8d22-4935-bdc1-526d5747fe6f','{"option_id":"B"}'::jsonb,'{"feedback":{"explanation":"The perpendicular from the center bisects the chord, giving a right triangle with hypotenuse 13 (the radius) and leg 12 (half the chord). So $d = \\sqrt{13^2 - 12^2} = 5$. Choice B is correct. Choice A is incorrect. This subtracts half the chord from the radius instead of using the Pythagorean theorem. Choice C is incorrect. This is half the length of the chord. Choice D is incorrect. This adds the squares, $\\sqrt{13^2 + 12^2}$, but the radius is the hypotenuse of the right triangle."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('d7bb9463-a63a-6dad-83b2-70d5c0b441d1','978612a1-1a5e-c55f-a23d-ab24bca46382','question_single_choice','{"prompt":"Triangle $ABC$ is inscribed in a circle so that $\\overline{AB}$ is a diameter of the circle. If the measure of angle $A$ is $34°$, what is the measure of angle $B$?","options":[{"id":"A","label":"$56^\\circ$"},{"id":"B","label":"$68^\\circ$"},{"id":"C","label":"$90^\\circ$"},{"id":"D","label":"$146^\\circ$"}]}'::jsonb,83,'{"section_type":"math","sat_domain":"geometry_trig","sat_official_domain":"geometry_trigonometry","sat_skill":"circles","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"geo-circle-015","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('d7bb9463-a63a-6dad-83b2-70d5c0b441d1','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"An angle inscribed in a semicircle is a right angle, so angle $C = 90°$. Then angle $B = 180 - 90 - 34 = 56°$. Choice A is correct. Choice B is incorrect. This doubles angle $A$, as if angle $B$ were a central angle. Choice C is incorrect. This is the measure of angle $C$, which is inscribed in a semicircle. Choice D is incorrect. This is the supplement of angle $A$; it leaves out the right angle at $C$."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('6a773a0f-9895-c794-af67-18e525c68f37','978612a1-1a5e-c55f-a23d-ab24bca46382','question_single_choice','{"prompt":"In the $xy$-plane, a circle has equation $(x - 2)^2 + (y + 1)^2 = 20$. Which of the following points lies inside the circle?","options":[{"id":"A","label":"$(5, 2)$"},{"id":"B","label":"$(0, 4)$"},{"id":"C","label":"$(-3, -1)$"},{"id":"D","label":"$(6, 1)$"}]}'::jsonb,84,'{"section_type":"math","sat_domain":"geometry_trig","sat_official_domain":"geometry_trigonometry","sat_skill":"circles","difficulty":"medium","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"geo-circle-016","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('6a773a0f-9895-c794-af67-18e525c68f37','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"A point is inside the circle when $(x - 2)^2 + (y + 1)^2 < 20$. For $(5, 2)$: $3^2 + 3^2 = 18 < 20$, so it is inside. Choice A is correct. Choice B is incorrect. For this point, $(0 - 2)^2 + (4 + 1)^2 = 29 > 20$, so it lies outside the circle. Choice C is incorrect. For this point, $(-3 - 2)^2 + (-1 + 1)^2 = 25 > 20$, so it lies outside the circle. Choice D is incorrect. For this point, $(6 - 2)^2 + (1 + 1)^2 = 20$, so it lies on the circle, not inside it."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('b008eb25-afdb-ab6f-460f-2c1a265f1948','978612a1-1a5e-c55f-a23d-ab24bca46382','question_spr','{"prompt":"The equation $x^2 + y^2 + 8x - 4y = k$ represents a circle in the $xy$-plane with radius $6$. What is the value of $k$?"}'::jsonb,85,'{"section_type":"math","sat_domain":"geometry_trig","sat_official_domain":"geometry_trigonometry","sat_skill":"circles","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"geo-circle-017","answer_format":"spr"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('b008eb25-afdb-ab6f-460f-2c1a265f1948','{"accepted":["16"]}'::jsonb,'{"feedback":{"explanation":"Complete the square: $(x^2 + 8x + 16) + (y^2 - 4y + 4) = k + 16 + 4$, so $(x + 4)^2 + (y - 2)^2 = k + 20$. The radius is 6, so $k + 20 = 36$ and $k = 16$."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('ac4fe77d-fb8a-1371-af1c-d9b812dd85d8','978612a1-1a5e-c55f-a23d-ab24bca46382','question_single_choice','{"prompt":"On a circle with radius $9$, an arc has length $5\\pi$. What is the measure, in radians, of the central angle that intercepts this arc?","options":[{"id":"A","label":"$\\frac{5}{9}$"},{"id":"B","label":"$\\frac{5\\pi}{18}$"},{"id":"C","label":"$\\frac{5\\pi}{9}$"},{"id":"D","label":"$\\frac{10\\pi}{9}$"}]}'::jsonb,86,'{"section_type":"math","sat_domain":"geometry_trig","sat_official_domain":"geometry_trigonometry","sat_skill":"circles","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"geo-circle-018","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('ac4fe77d-fb8a-1371-af1c-d9b812dd85d8','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"For an angle in radians, $s = r\\theta$, so $\\theta = \\frac{s}{r} = \\frac{5\\pi}{9}$. Choice C is correct. Choice A is incorrect. This drops the factor of $\\pi$ from the arc length. Choice B is incorrect. This divides the arc length by the diameter instead of the radius. Choice D is incorrect. This doubles the angle, as if the arc length were $10\\pi$."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('d22d82d7-1fa5-22ba-222a-1bdd693f1c8f','978612a1-1a5e-c55f-a23d-ab24bca46382','question_single_choice','{"prompt":"A circle in the $xy$-plane passes through the points $(1, 2)$, $(7, 2)$, and $(1, 10)$. Which equation represents the circle?","options":[{"id":"A","label":"$(x - 4)^2 + (y - 6)^2 = 25$"},{"id":"B","label":"$(x - 4)^2 + (y - 6)^2 = 100$"},{"id":"C","label":"$(x - 1)^2 + (y - 2)^2 = 100$"},{"id":"D","label":"$(x + 4)^2 + (y + 6)^2 = 25$"}]}'::jsonb,87,'{"section_type":"math","sat_domain":"geometry_trig","sat_official_domain":"geometry_trigonometry","sat_skill":"circles","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"geo-circle-019","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('d22d82d7-1fa5-22ba-222a-1bdd693f1c8f','{"option_id":"A"}'::jsonb,'{"feedback":{"explanation":"The segments from $(1, 2)$ to $(7, 2)$ and from $(1, 2)$ to $(1, 10)$ are perpendicular, so the angle at $(1, 2)$ is a right angle inscribed in the circle. The opposite side, from $(7, 2)$ to $(1, 10)$, is a diameter. Its midpoint, $(4, 6)$, is the center, and its length is $\\sqrt{6^2 + 8^2} = 10$, so the radius is 5. The equation is $(x - 4)^2 + (y - 6)^2 = 25$. Choice A is correct. Choice B is incorrect. This uses the diameter, 10, as the radius. Choice C is incorrect. This places the center at one of the given points; that point is on the circle, not its center. Choice D is incorrect. This uses the correct radius but reverses the signs of the center''s coordinates."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('36ee2b60-05d1-3cee-6672-32b6439caf5c','978612a1-1a5e-c55f-a23d-ab24bca46382','question_spr','{"prompt":"Quadrilateral $ABCD$ is inscribed in a circle. The measure of angle $A$ is $(3x + 12)°$ and the measure of angle $C$ is $(5x - 8)°$. What is the measure of angle $C$, in degrees?"}'::jsonb,88,'{"section_type":"math","sat_domain":"geometry_trig","sat_official_domain":"geometry_trigonometry","sat_skill":"circles","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"geo-circle-020","answer_format":"spr"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('36ee2b60-05d1-3cee-6672-32b6439caf5c','{"accepted":["102"]}'::jsonb,'{"feedback":{"explanation":"Opposite angles of a quadrilateral inscribed in a circle are supplementary: $(3x + 12) + (5x - 8) = 180$, so $8x + 4 = 180$ and $x = 22$. Then angle $C$ measures $5(22) - 8 = 102$ degrees."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('0bd060e1-b56d-f33d-614f-16f0376437dd','978612a1-1a5e-c55f-a23d-ab24bca46382','question_single_choice','{"prompt":"Two circles have the same center. The larger circle has radius $10$, and the smaller circle has radius $6$. A chord of the larger circle is tangent to the smaller circle. What is the length of the chord?","options":[{"id":"A","label":"$4$"},{"id":"B","label":"$8$"},{"id":"C","label":"$2\\sqrt{34}$"},{"id":"D","label":"$16$"}]}'::jsonb,89,'{"section_type":"math","sat_domain":"geometry_trig","sat_official_domain":"geometry_trigonometry","sat_skill":"circles","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"geo-circle-021","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('0bd060e1-b56d-f33d-614f-16f0376437dd','{"option_id":"D"}'::jsonb,'{"feedback":{"explanation":"The radius of the smaller circle drawn to the point of tangency is perpendicular to the chord and bisects it. The radius of the larger circle to an endpoint of the chord is the hypotenuse of a right triangle with leg 6, so half the chord is $\\sqrt{10^2 - 6^2} = 8$. The chord has length 16. Choice D is correct. Choice A is incorrect. This is the difference of the radii, the width of the ring between the circles, not the chord. Choice B is incorrect. This is half the chord; the point of tangency is the midpoint of the chord. Choice C is incorrect. This adds the squares of the radii, $\\sqrt{10^2 + 6^2} = \\sqrt{136}$, as if the larger radius were a leg; it is the hypotenuse of the right triangle."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
insert into public.content_units(id,part_id,type,data,display_order,metadata) values('edb20df9-075d-39ea-bce3-c1166cfca7af','978612a1-1a5e-c55f-a23d-ab24bca46382','question_single_choice','{"prompt":"A sector of a circle has an area of $15\\pi$ square units and an arc length of $5\\pi$ units. What is the radius of the circle?","options":[{"id":"A","label":"$3$"},{"id":"B","label":"$\\sqrt{15}$"},{"id":"C","label":"$6$"},{"id":"D","label":"$30$"}]}'::jsonb,90,'{"section_type":"math","sat_domain":"geometry_trig","sat_official_domain":"geometry_trigonometry","sat_skill":"circles","difficulty":"hard","difficulty_basis":"editorial","content_status":"published","content_revision":"original-2026-10-v2","original_slug":"geo-circle-022","answer_format":"mcq"}'::jsonb) on conflict do nothing;
insert into public.answer_keys(content_unit_id,correct,metadata) values('edb20df9-075d-39ea-bce3-c1166cfca7af','{"option_id":"C"}'::jsonb,'{"feedback":{"explanation":"The area of a sector is $\\frac{1}{2}rs$, where $s$ is the arc length. So $\\frac{1}{2}r(5\\pi) = 15\\pi$, which gives $r = 6$. Choice C is correct. Choice A is incorrect. This uses sector area $= r \\cdot s$ without the factor of $\\frac{1}{2}$. Choice B is incorrect. This treats $15\\pi$ as the area of the whole circle, solving $\\pi r^2 = 15\\pi$. Choice D is incorrect. This multiplies the area by 2 without dividing by the arc length."},"source":"original-schood-practice-v2"}'::jsonb) on conflict do nothing;
